const PREMIUM_KEY = 'guverte-premium-v1';
const PREMIUM_PRODUCT_ID = 'premium_full_pack';
const PREMIUM_PRICE_LABEL = '75 TL';
const ADS_REMOVAL_KEY = 'guverte-no-ads-v1';
const ADS_REMOVAL_PRODUCT_ID = 'remove_ads';
const ADS_REMOVAL_PRICE_LABEL = '50 TL';
const PURCHASE_MARKER_PREFIXES = Object.freeze(['GP-', 'STORE-']);
function isTrustedPurchaseMarker(value){
  const marker = String(value || '');
  return PURCHASE_MARKER_PREFIXES.some(prefix=>marker.startsWith(prefix));
}
function readPurchasedFlag(key){
  try{return isTrustedPurchaseMarker(localStorage.getItem(key));}catch(e){return false;}
}
function writePurchasedFlag(key, receipt){
  const marker = String(receipt || '');
  if(!isTrustedPurchaseMarker(marker)) return false;
  try{localStorage.setItem(key, marker);}catch(e){}
  return true;
}
let premiumUnlocked = readPurchasedFlag(PREMIUM_KEY);
let adsRemoved = readPurchasedFlag(ADS_REMOVAL_KEY);
const PREMIUM_PACKAGE_CATALOG = [
  'Proje yuk ve heavy-lift',
  'Kruvaziyer / yolcu operasyonu',
  'Arastirma / ROV survey',
  'Offshore / DP platform',
  'Kutup ve buz seyri',
  'Ileri cihaz simulasyonu',
  'Premium hareketli 3D operasyonlar',
  'Premium chart paketleri: offshore DP, arastirma ROV, kruvaziyer medevac, proje yuk lift, buz seyri'
];
function refreshMonetizationState(){
  premiumUnlocked = readPurchasedFlag(PREMIUM_KEY);
  adsRemoved = readPurchasedFlag(ADS_REMOVAL_KEY);
  return {premiumUnlocked, adsRemoved};
}
function isPremiumShipType(typeKey){
  return !!STYPES.find(x=>x.key===typeKey && x.premium);
}
function canUseShipType(typeKey){
  return !isPremiumShipType(typeKey) || premiumUnlocked;
}
const PREMIUM_SCENE_ID_PREFIXES = Object.freeze(['proje','cruise','research','offshore','ice','cable','pipe','shuttle','premium_tanker']);
function isPremiumSceneId(id=''){
  const sid = String(id || '');
  return PREMIUM_SCENE_ID_PREFIXES.some(prefix=>sid.startsWith(prefix)) || sid === 'cin_cruise_medevac';
}
function isPremiumContentScene(sc){
  if(!sc) return false;
  return !!sc.premium || sc.cinematicKey === 'cruiseMedevac' || isPremiumSceneId(sc.id) || /^Premium\b/i.test(String(sc.day || ''));
}
function requirePremiumAccess(reason='Bu ozel gemi, rota veya operasyon premium pakete dahildir.'){
  refreshMonetizationState();
  if(premiumUnlocked) return true;
  showNotif('🔒','Premium Gerekli', reason);
  return false;
}
function filterPremiumLockedScenes(scenes){
  refreshMonetizationState();
  if(premiumUnlocked) return scenes;
  return (scenes || []).filter(sc=>!isPremiumContentScene(sc));
}
function enforcePremiumAccessGuards(context='runtime'){
  refreshMonetizationState();
  let changed = false;
  if(!premiumUnlocked){
    if(isPremiumShipType(selType)){
      selType = 'kuru';
      sn = sn || 'M/V Ege Meltem';
      changed = true;
    }
    if(Array.isArray(sceneQueue)){
      const before = sceneQueue.length;
      sceneQueue = filterPremiumLockedScenes(sceneQueue);
      if(sceneQueue.length !== before){
        currentIdx = Math.min(currentIdx, Math.max(0, sceneQueue.length - 1));
        changed = true;
      }
    }
    if(Array.isArray(shipOffers)){
      const beforeOffers = shipOffers.length;
      shipOffers = shipOffers.filter(o=>!isPremiumShipType(o.type));
      if(shipOffers.length !== beforeOffers) changed = true;
    }
    if(activeVoyageRoute && /premium|cruise|research|offshore|ice|cable|pipe|shuttle|project|proje|rov|dp/i.test(`${activeVoyageRoute.key || ''} ${activeVoyageRoute.trade || ''}`)){
      const fallback = selectVoyageRouteForShipType('kuru');
      if(fallback) activateVoyageRoute(fallback);
      changed = true;
    }
  }
  if(changed && typeof recordReleaseDiagnostic === 'function'){
    recordReleaseDiagnostic('premium_guard_applied', '', {context, selType, sceneCount:Array.isArray(sceneQueue)?sceneQueue.length:0});
  }
  return !changed;
}
function getPremiumBillingBridge(){
  if(window.GuverteBilling && typeof window.GuverteBilling.purchasePremium === 'function') return window.GuverteBilling;
  if(window.GuverteBillingNative && typeof window.GuverteBillingNative.purchasePremium === 'function'){
    let pendingResolve = null;
    let pendingReject = null;
    window.__guverteBillingNativeResult = (result) => {
      const resolve = pendingResolve;
      const reject = pendingReject;
      pendingResolve = null;
      pendingReject = null;
      if(!resolve) return;
      if(result?.ok) resolve(result);
      else reject(new Error(result?.message || 'Satin alma tamamlanmadi.'));
    };
    window.GuverteBilling = {
      purchasePremium(productId){
        return new Promise((resolve, reject)=>{
          pendingResolve = resolve;
          pendingReject = reject;
          try{
            window.GuverteBillingNative.purchasePremium(productId);
          }catch(err){
            pendingResolve = null;
            pendingReject = null;
            reject(err);
          }
        });
      },
      restorePremium(){
        return new Promise((resolve, reject)=>{
          pendingResolve = resolve;
          pendingReject = reject;
          try{
            window.GuverteBillingNative.restorePremium();
          }catch(err){
            pendingResolve = null;
            pendingReject = null;
            reject(err);
          }
        });
      },
      restoreProduct(productId){
        return new Promise((resolve, reject)=>{
          pendingResolve = resolve;
          pendingReject = reject;
          try{
            if(typeof window.GuverteBillingNative.restoreProduct === 'function') window.GuverteBillingNative.restoreProduct(productId);
            else throw new Error('Bu uygulama surumunde urun bazli geri yukleme yok.');
          }catch(err){
            pendingResolve = null;
            pendingReject = null;
            reject(err);
          }
        });
      },
      checkProducts(){
        return new Promise((resolve, reject)=>{
          pendingResolve = resolve;
          pendingReject = reject;
          try{
            if(typeof window.GuverteBillingNative.checkProducts === 'function') window.GuverteBillingNative.checkProducts();
            else throw new Error('Bu uygulama surumunde Play urun kontrolu yok.');
          }catch(err){
            pendingResolve = null;
            pendingReject = null;
            reject(err);
          }
        });
      }
    };
    return window.GuverteBilling;
  }
  return null;
}
function handleNativeAdEvent(result={}){
  const type = String(result?.type || '');
  if(type === 'shown'){
    addWatchFeed?.('Guvenli gecis noktasinda reklam arasi basladi.', 'warn');
  }else if(type === 'dismissed'){
    addWatchFeed?.('Reklam kapandi; vardiya akisi kaldigi yerden devam ediyor.', 'good');
  }else if(type === 'privacy_closed'){
    showNotif('GIZLILIK','Reklam Tercihleri','Reklam gizlilik tercihlerin guncellendi.');
  }else if(type === 'privacy_error'){
    showNotif('UYARI','Reklam Gizliligi',String(result?.message || 'Gizlilik formu acilamadi.'));
  }
}
function getAdsBridge(){
  if(window.GuverteAds && typeof window.GuverteAds.showInterstitial === 'function') return window.GuverteAds;
  if(window.GuverteAdsNative && typeof window.GuverteAdsNative.showInterstitial === 'function'){
    window.__guverteAdsNativeEvent = handleNativeAdEvent;
    window.GuverteAds = {
      initialize(){
        window.GuverteAdsNative.initializeAds();
      },
      setRemoved(removed){
        window.GuverteAdsNative.setAdsRemoved(!!removed);
      },
      showInterstitial(reason){
        window.GuverteAdsNative.showInterstitial(String(reason || 'safe_point'));
      },
      showPrivacyOptions(){
        window.GuverteAdsNative.showPrivacyOptions();
      },
      getStatus(){
        window.GuverteAdsNative.getStatus();
      }
    };
    return window.GuverteAds;
  }
  return null;
}
function syncNativeAdsState(){
  adsRemoved = readPurchasedFlag(ADS_REMOVAL_KEY);
  const ads = getAdsBridge();
  if(!ads) return false;
  ads.setRemoved(adsRemoved);
  if(!adsRemoved) ads.initialize();
  return true;
}
function initializeAdSystem(){
  window.__guverteAdsNativeEvent = handleNativeAdEvent;
  syncNativeAdsState();
}
function openAdPrivacyOptions(){
  const ads = getAdsBridge();
  if(!ads || typeof ads.showPrivacyOptions !== 'function'){
    showNotif('GIZLILIK','Reklam Tercihleri','Bu ayar Android uygulamasinda Google gizlilik formunu acar.');
    return;
  }
  ads.showPrivacyOptions();
}
async function checkBillingProducts(){
  const billing = getPremiumBillingBridge();
  if(!billing || typeof billing.checkProducts !== 'function'){
    showNotif('BILLING','Web/Test Modu','Android build icinde Google Play urun kontrolu calisir. Play Console urunleri: premium_full_pack ve remove_ads.');
    return;
  }
  try{
    showNotif('BILLING','Urunler Kontrol Ediliyor','Google Play Console urun listesi sorgulaniyor.');
    const result = await billing.checkProducts();
    const packageName = result?.packageName || 'com.captainemo.guverte';
    const msg = result?.ok
      ? `Tamam: ${packageName} icin premium_full_pack ve remove_ads bulundu.`
      : `${packageName}: ${result?.message || 'Urunlerden biri bulunamadi.'}`;
    showNotif(result?.ok?'OK':'UYARI','Play Billing Kontrol',msg);
    addLiveLogbook?.('BILLING CHECK', msg, true);
  }catch(err){
    showNotif('UYARI','Play Billing Kontrol',String(err?.message || err || 'Urun kontrolu calismadi.'));
  }
}
async function openPremiumPurchase(){
  if(premiumUnlocked){
    showNotif('🔓','Premium Aktif',`Premium paket zaten acik. Paket: ${PREMIUM_PACKAGE_CATALOG.join(' · ')}`);
    return;
  }
  const billing = getPremiumBillingBridge();
  if(billing && typeof billing.purchasePremium === 'function'){
    try{
      showNotif('💳','Premium Satin Alma',`${PREMIUM_PRICE_LABEL} · Google Play odeme ekrani aciliyor.`);
      const result = await billing.purchasePremium(PREMIUM_PRODUCT_ID);
      const receipt = result?.purchaseToken || result?.receipt || result?.orderId || '';
      if(result?.ok && receipt && (!result?.productId || result.productId === PREMIUM_PRODUCT_ID)){
        grantPremiumPackageFromPurchase(`GP-${receipt}`);
      }else{
        showNotif('🔒','Odeme Tamamlanmadi','Satin alma onayi gelmedi. Karttan cekim yapildiysa Play Store satin alma gecmisinden geri yukleme deneyebilirsin.');
      }
    }catch(err){
      showNotif('⚠️','Odeme Baslatilamadi',String(err?.message || err || 'Google Play Billing baglantisi kurulamadi.'));
    }
    return;
  }
  showNotif('💳','Premium Ucretli Paket',`${PREMIUM_PRICE_LABEL} · Google Play Billing baglaninca bu buton odeme ekranini acar. Paket: ${PREMIUM_PACKAGE_CATALOG.join(' · ')}`);
}
async function openAdsRemovalPurchase(){
  if(adsRemoved){
    showNotif('🚫','Reklamlar Kapali','Reklamlari kaldirma paketi zaten aktif.');
    return;
  }
  const billing = getPremiumBillingBridge();
  if(billing && typeof billing.purchasePremium === 'function'){
    try{
      showNotif('💳','Reklamlari Kaldir',`${ADS_REMOVAL_PRICE_LABEL} · Google Play odeme ekrani aciliyor.`);
      const result = await billing.purchasePremium(ADS_REMOVAL_PRODUCT_ID);
      const receipt = result?.purchaseToken || result?.receipt || result?.orderId || '';
      if(result?.ok && receipt && (!result?.productId || result.productId === ADS_REMOVAL_PRODUCT_ID)){
        grantAdsRemovalFromPurchase(`GP-${receipt}`);
      }else{
        showNotif('🔒','Odeme Tamamlanmadi','Reklam kaldirma onayi gelmedi. Satin alma yapildiysa geri yukleme deneyebilirsin.');
      }
    }catch(err){
      showNotif('⚠️','Odeme Baslatilamadi',String(err?.message || err || 'Google Play Billing baglantisi kurulamadi.'));
    }
    return;
  }
  showNotif('💳','Reklamlari Kaldir',`${ADS_REMOVAL_PRICE_LABEL} · Google Play Billing baglaninca bu buton odeme ekranini acar.`);
}
async function restorePremiumPurchase(){
  const billing = getPremiumBillingBridge();
  if(!billing || typeof billing.restorePremium !== 'function'){
    showNotif('🔁','Geri Yukleme Hazir Degil','Google Play Billing baglaninca daha once alinmis premium paket buradan geri yuklenir.');
    return;
  }
  try{
    showNotif('🔁','Premium Geri Yukleniyor','Google Play satin alma gecmisi kontrol ediliyor.');
    const result = await billing.restorePremium();
    const receipt = result?.purchaseToken || result?.receipt || result?.orderId || '';
    if(result?.ok && receipt && (!result?.productId || result.productId === PREMIUM_PRODUCT_ID)){
      grantPremiumPackageFromPurchase(`GP-${receipt}`);
    }else{
      showNotif('🔒','Premium Bulunamadi','Bu Google Play hesabinda premium satin alma bulunamadi.');
    }
  }catch(err){
    showNotif('⚠️','Geri Yukleme Basarisiz',String(err?.message || err || 'Satin alma gecmisi okunamadi.'));
  }
}
async function restoreAdsRemovalPurchase(){
  const billing = getPremiumBillingBridge();
  if(!billing || typeof billing.restoreProduct !== 'function'){
    showNotif('🔁','Geri Yukleme Hazir Degil','Google Play Billing urun bazli geri yukleme hazir degil.');
    return;
  }
  try{
    showNotif('🔁','Reklam Paketi','Google Play satin alma gecmisi kontrol ediliyor.');
    const result = await billing.restoreProduct(ADS_REMOVAL_PRODUCT_ID);
    const receipt = result?.purchaseToken || result?.receipt || result?.orderId || '';
    if(result?.ok && receipt && (!result?.productId || result.productId === ADS_REMOVAL_PRODUCT_ID)){
      grantAdsRemovalFromPurchase(`GP-${receipt}`);
    }else{
      showNotif('🔒','Paket Bulunamadi','Bu Google Play hesabinda reklam kaldirma satin alma bulunamadi.');
    }
  }catch(err){
    showNotif('⚠️','Geri Yukleme Basarisiz',String(err?.message || err || 'Satin alma gecmisi okunamadi.'));
  }
}
function grantPremiumPackageFromPurchase(receipt=''){
  if(!/^(GP|STORE)-/.test(String(receipt))){
    showNotif('🔒','Odeme Onayi Gerekli','Premium sadece gecerli satin alma onayi ile acilir.');
    return false;
  }
  premiumUnlocked = true;
  writePurchasedFlag(PREMIUM_KEY, receipt);
  showNotif('🔓','Premium Aktif','Odeme onayi alindi. Ozel gemiler, ileri operasyonlar ve pro kriz paketleri acildi.');
  buildIntro();
  return true;
}
function grantAdsRemovalFromPurchase(receipt=''){
  if(!/^(GP|STORE)-/.test(String(receipt))){
    showNotif('🔒','Odeme Onayi Gerekli','Reklam kaldirma sadece gecerli satin alma onayi ile acilir.');
    return false;
  }
  adsRemoved = true;
  writePurchasedFlag(ADS_REMOVAL_KEY, receipt);
  syncNativeAdsState();
  showNotif('🚫','Reklamlar Kaldirildi','50 TL reklam kaldirma paketi aktif edildi.');
  buildIntro();
  return true;
}

const SHIP_TON_PROFILES={
  kuru:{min:18000,max:32000,step:1000,unit:"DWT"},
  tanker:{min:38000,max:64000,step:2000,unit:"DWT"},
  kont:{min:12000,max:26000,step:1000,unit:"GT"},
  roro:{min:9000,max:18000,step:1000,unit:"GT"},
  bulk:{min:42000,max:82000,step:2000,unit:"DWT"},
  lng:{min:68000,max:174000,step:2000,unit:"m³"},
  proje:{min:12000,max:32000,step:1000,unit:"DWT"},
  kruvaziyer:{min:62000,max:145000,step:3000,unit:"GT"},
  arastirma:{min:3200,max:11500,step:500,unit:"GT"},
  offshore:{min:3500,max:9500,step:500,unit:"GT"},
  buz:{min:12000,max:32000,step:1000,unit:"GT"},
  cable:{min:8000,max:18000,step:1000,unit:"GT"},
  pipe:{min:18000,max:46000,step:2000,unit:"GT"},
  shuttle:{min:62000,max:120000,step:2000,unit:"DWT"},
};
let CURRENT_SHIP_SPECS={};

function formatShipTonnage(value, unit){
  return `${Math.round(value).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.')} ${unit}`;
}
function rollShipSpec(typeKey){
  const profile=SHIP_TON_PROFILES[typeKey];
  const fallback=STYPES.find(x=>x.key===typeKey);
  if(!profile){
    return {value:null, unit:'', tonLabel:fallback?.ton||''};
  }
  const steps=Math.floor((profile.max-profile.min)/profile.step);
  const value=profile.min + Math.floor(Math.random()*(steps+1))*profile.step;
  return {value, unit:profile.unit, tonLabel:formatShipTonnage(value, profile.unit)};
}
function refreshShipSpecs(){
  CURRENT_SHIP_SPECS={};
  STYPES.forEach(t=>{ CURRENT_SHIP_SPECS[t.key]=rollShipSpec(t.key); });
}
function getShipSpec(typeKey){
  return CURRENT_SHIP_SPECS[typeKey] || rollShipSpec(typeKey);
}

