function normalizeTrAscii(v=''){
  return String(v)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .replace(/i̇/g,'i')
    .replace(/ç/g,'c')
    .replace(/ğ/g,'g')
    .replace(/ı/g,'i')
    .replace(/ö/g,'o')
    .replace(/ş/g,'s')
    .replace(/ü/g,'u');
}

function inferPortraitBase(def={}){
  const normalizedName = normalizeTrAscii(def.name || '');
  if(/\bhanim\b/.test(normalizedName)) return 'female';
  if(/\bbey\b/.test(normalizedName)) return 'male';
  const tokens = normalizeTrAscii(def.name || '')
    .split(/\s+/)
    .map(t => t.replace(/[^\p{L}\p{N}.]/gu,''))
    .filter(Boolean)
    .filter(t => !NAME_STOPWORDS.has(t));
  const firstName = tokens[0] || '';
  return FEMALE_NAME_LOOKUP.has(firstName) ? 'female' : 'male';
}
