function getSceneOverlay(gfx,sc){
  let extra = getSceneFleetOverlay(gfx);
  extra += getPanelChromeOverlay(gfx, sc);
  extra += getChartWorkOverlay(sc);
  extra += getMeteorologyOverlay(sc);
  extra += getCargoIncidentOverlay(sc);
  extra += getCommsDeviceOverlay(sc);
  extra += getFireTrainingOverlay(sc);
  extra += getDrillTrainingOverlay(sc);
  extra += getLsaTrainingOverlay(sc);
  if((gfx==='compass'||gfx==='bridge') && sc && (sc.ecdisPlanKey || sc.sub?.toLowerCase().includes('ecdis') || sc.sub?.toLowerCase().includes('seyir plani') || sc.loc?.toLowerCase().includes('ecdis'))){
    extra += getEcdisRouteOverlay(sc);
  }
  if(gfx==='radar' && sc){
    extra += getRadarTrainingOverlay(sc);
  }
  return extra;
}

function getSceneVhfConsoleOverlay(sc){
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const isDistress = /mayday|distress|sahil guvenlik|sahil güvenlik|korsan|pirate|mob|fire|yangin|blackout/.test(blob);
  const isPan = /pan-pan|medical|medevac|engine alarm|makine alarm/.test(blob);
  const isVts = /vts|traffic|tss|bogaz|boğaz|strait|reporting point/.test(blob);
  const isPilot = /pilot|pilot exchange|boarding|berth|tug|romorkor|römorkör|liman|harbor/.test(blob);
  const isDsc = /dsc|ch70|channel 70/.test(blob);
  const channel = isDsc ? '70'
    : isDistress ? '16'
    : isVts ? '12'
    : isPilot ? '14'
    : isPan ? '16'
    : '13';
  const mode = isDsc ? 'DSC WATCH'
    : isDistress ? 'DISTRESS WATCH'
    : isPan ? 'URGENCY'
    : isVts ? 'VTS WORKING'
    : isPilot ? 'PILOT / TUG'
    : 'BRIDGE COMMS';
  const rxLine = isDistress ? 'MAYDAY / SECURITE TRAFFIC'
    : isPan ? 'PAN-PAN TRAFFIC'
    : isVts ? 'VTS REPORTING POINT'
    : isPilot ? 'PILOT EXCHANGE / TUG ORDER'
    : 'ROUTINE BRIDGE WATCH';
  const phrase = isDistress ? 'Position, nature of distress, assistance required.'
    : isPan ? 'Urgency call, vessel status, medical/engine update.'
    : isVts ? 'Ship name, position, course, speed, intention.'
    : isPilot ? 'Pilot ladder, ETA, side, speed and tug plan.'
    : 'Listen first, speak short, log the call.';
  const hot = isDistress || isPan || sc?.alert;
  return `<div class="live-vhf-console ${hot?'hot':''}">
    <div class="vhf-top"><span>VHF DSC RADIOTELEPHONE</span><b>${phoneSafe(mode)}</b></div>
    <div class="vhf-body">
      <div class="vhf-lcd">
        <small>CH</small><strong>${channel}</strong>
        <em>${phoneSafe(rxLine)}</em>
        <i>${phoneSafe(phrase)}</i>
      </div>
      <div class="vhf-side">
        <button>PTT</button>
        <button class="${hot?'danger':''}">DIST</button>
        <button>SQL</button>
      </div>
    </div>
    <div class="vhf-keypad">
      <span class="${channel==='16'?'active':''}">16</span>
      <span class="${channel==='70'?'active':''}">70</span>
      <span class="${channel==='12'?'active':''}">12</span>
      <span class="${channel==='14'?'active':''}">14</span>
      <span>DW</span>
      <span>SCAN</span>
    </div>
    <div class="vhf-rx"><b>RX</b><span></span><span></span><span></span><span></span><span></span></div>
  </div>`;
}

function getScene3DFeatureFlags(sc){
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const gfx = String(sc?.gfx || '').toLowerCase();
  const routineWatch = /watch|vardiya|nobet|nöbet|teslim|handover|logbook|defter|standing order|night order|gece|sabah|lookout|gözcü|gozcu|weather|hava|barometre|wind|rüzgar|ruzgar|bulut|cloud|trafik|traffic|seyir|süvari|suvari|zabit/.test(blob)
    || ['sea','night','sunrise','bridge','compass','port_arrival','pirate'].includes(gfx);
  const deckOps = /deck|guverte|güverte|cargo|yuk|yük|ambar|hold|hatch|container|konteyner|reefer|lashing|stowage|bay-row-tier|bay row tier|bulk|loading|discharge|draft|trim|ballast|crane|vinc|vinç|forklift|safety round|islak zemin|ıslak zemin/.test(blob)
    || ['deck','cargo','fire','pirate'].includes(gfx);
  const crewLife = /shipwalk|gemi ici|gemi içi|kamara|cabin|messroom|mess room|galley|aşçı|asci|kambuz|steward|kamarot|yemek|menu|menü|cay|çay|kahve|uyku|dinlen|mola|serbest zaman|telefon|aile|crew chat/.test(blob)
    || ['galley','cabin'].includes(gfx);
  const flags = {
    bridgeConsole: /bridge|kopruustu|köprüüstü|radar|arpa|ecdis|ais|vhf|dsc|mayday|pan-pan|vts|pilot|route monitor|tss|bogaz|boğaz|gmdss|bnwas|gyro|telegraph/.test(blob),
    harborApproach: /harbor|liman|terminal|berth|tug|pilot|all fast|mooring|rihtim|rıhtım|yanaşma|yanasma/.test(blob),
    mooring: /mooring|halat|snap-back|snap back|head line|stern line|fore spring|aft spring|breast line|all fast|bollard/.test(blob),
    engineRoom: /engine|makine|ecr|generator|jenerator|pompa|pump|purifier|bilge|fuel transfer|cooling water|quick closing|blackout|egzoz|exhaust|alarm panel/.test(blob),
    shipWalk: crewLife || /güverte turu|guverte turu|makine girişi|makine girisi/.test(blob),
    routineWatch,
    deckOps,
    crewLife,
    survival: /lifeboat|filika|liferaft|can sali|can salı|davit|matafora|rescue boat|life raft|abandon ship/.test(blob),
    fire: /fire|yangin|yangın|smoke|duman|extinguisher|co2|foam|dcp|fire zone|fire alarm/.test(blob),
    routeTable: /route|waypoint|chart|ecdis|tss|cpa|tcpa|ukc|squat|passage plan|pilot station|no anchoring|rota/.test(blob),
    manifold: /tanker|manifold|loading arm|esd|drip tray|sample|sopep|bunker|hose|overflow|line-up|line up/.test(blob),
    premiumOps: /offshore|platform|dp|rov|research|survey vessel|araştırma|arastirma|cruise|kruvaziyer|medevac|helicopter|helikopter|project cargo|proje yuk|proje yük|heavy-lift|cable|pipe|ice|buz|fpso|shuttle/.test(blob),
    starlink: /starlink|satellite|uydu|seanet|crew wifi|ops vlan|obstruction|latency|jitter|failover|vsat/.test(blob),
    helicopter: /helicopter|helikopter|medevac|medical evacuation|mrcc|clear deck|winchman|winching/.test(blob),
    cargoLift: /project cargo|proje yuk|proje yük|heavy-lift|agir yuk|ağır yük|lifting|sling|cog|sea fastening|crane|vinc|vinç|hook load/.test(blob),
    storm: /storm|firtina|swell|rain|yagmur|yağmur|sis|fog|beaufort|spray|icing/.test(blob),
  };
  flags.any = Object.values(flags).some(Boolean);
  return flags;
}

function getScene3DBridgeOverlay(sc){
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const flags = getScene3DFeatureFlags(sc);
  if(!flags.any) return '';
  const isDistress = /mayday|distress|sahil guvenlik|sahil güvenlik|korsan|pirate|mob|fire|yangin|blackout/.test(blob);
  const isVts = /vts|traffic|tss|bogaz|boğaz|strait|reporting point/.test(blob);
  const isPilot = /pilot|pilot exchange|boarding|berth|tug|romorkor|römorkör|liman|harbor/.test(blob);
  const isDsc = /dsc|ch70|channel 70/.test(blob);
  const channel = isDsc ? 'CH70' : isDistress ? 'CH16' : isVts ? 'CH12' : isPilot ? 'CH14' : 'CH13';
  const mode = isDistress ? 'DISTRESS'
    : isVts ? 'VTS'
    : isPilot ? 'PILOT'
    : isDsc ? 'DSC'
    : 'WATCH';
  const heading = flags.harborApproach ? '082' : flags.storm ? '248' : flags.engineRoom ? '117' : isVts ? '044' : '116';
  const sog = flags.harborApproach ? '6.2' : flags.storm ? '10.4' : flags.engineRoom ? '13.1' : '13.8';
  const depth = flags.harborApproach ? '18.6' : flags.storm ? '86.0' : flags.manifold ? '21.4' : '42.4';
  const rudder = flags.harborApproach ? 'P 05' : flags.storm ? 'MID' : flags.mooring ? 'S 03' : 'S 02';
  const telegraph = flags.harborApproach ? 'DEAD SLOW AHEAD' : flags.storm ? 'HALF AHEAD' : flags.engineRoom ? 'STAND BY' : 'FULL AWAY';
  const cpa = isDistress ? '0.7' : flags.harborApproach ? '1.1' : flags.storm ? '1.4' : '2.8';
  const tcpa = isDistress ? '08' : flags.harborApproach ? '14' : flags.storm ? '19' : '31';
  const cls = ['bridge3d','bridge3d-immersive',
    flags.harborApproach?'bridge3d-harbor':'',
    flags.storm?'bridge3d-storm':'',
    flags.engineRoom?'bridge3d-engine':'',
    flags.mooring?'bridge3d-mooring':'',
    flags.routineWatch?'bridge3d-watch':'',
    flags.deckOps?'bridge3d-deckops':'',
    flags.crewLife?'bridge3d-life':'',
    flags.survival?'bridge3d-survival':'',
    flags.fire?'bridge3d-fire':'',
    flags.routeTable?'bridge3d-route':'',
    flags.manifold?'bridge3d-manifold':'',
    flags.premiumOps?'bridge3d-premium':'',
    flags.starlink?'bridge3d-sat':'',
    flags.helicopter?'bridge3d-heli':'',
    flags.cargoLift?'bridge3d-lift':'',
  ].filter(Boolean).join(' ');
  return `<div class="${cls}" onclick="if(!event.target.closest('button')) openCurrentSceneControlWalk()">
    <div class="sky"></div>
    <div class="sea"></div>
    ${flags.harborApproach ? '<div class="bridge3d-tug"><i></i><b></b></div><div class="bridge3d-berth-lights"></div>' : ''}
    ${flags.storm ? '<div class="bridge3d-wave w1"></div><div class="bridge3d-wave w2"></div><div class="bridge3d-lightning"></div>' : ''}
    <div class="bridge3d-overhead"><span>NAV LT</span><span>BNWAS</span><span>FIRE</span><span>GMDSS</span><span>DIM</span></div>
    <div class="bridge3d-wipers"><i></i><i></i><i></i></div>
    <div class="window w1"></div><div class="window w2"></div><div class="window w3"></div><div class="window w4"></div>
    <div class="console"></div>
    <div class="bridge3d-repeater-row"><span>GYRO ${phoneSafe(heading)}°</span><span>ECHO ${phoneSafe(depth)}m</span><span>BNWAS OK</span></div>
    <div class="bridge3d-conning">
      <b>CONNING DISPLAY</b>
      <span>HDG ${phoneSafe(heading)}°</span><span>SOG ${phoneSafe(sog)} kn</span><span>RUD ${phoneSafe(rudder)}</span><span>DEP ${phoneSafe(depth)} m</span>
    </div>
    <div class="bridge3d-telegraph"><b>ENGINE TELEGRAPH</b><i></i><span>${phoneSafe(telegraph)}</span></div>
    <div class="bridge3d-ais-list"><b>AIS TARGETS</b><span>CPA ${phoneSafe(cpa)} nm</span><span>TCPA ${phoneSafe(tcpa)} m</span><span>VTS LINK</span></div>
    <div class="bridge3d-button-bank"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>
    <div class="bridge3d-device bridge3d-ecdis">
      <div class="label">ECDIS ROUTE</div>
      <div class="screen"><span class="route"></span><span class="ship"></span></div>
    </div>
    <div class="bridge3d-device bridge3d-vhf">
      <div class="label">VHF DSC</div>
      <div class="screen" data-channel="${phoneSafe(channel)}" data-mode="${phoneSafe(mode)}"></div>
      <div class="ptt">PTT</div><div class="dist">DIST</div><div class="rx"></div>
    </div>
    <div class="bridge3d-device bridge3d-radar">
      <div class="label">RADAR</div>
      <div class="screen"></div><i class="t1"></i><i class="t2"></i><i class="t3"></i>
    </div>
    ${flags.routineWatch ? '<div class="bridge3d-watch-traffic"><span class="tgt a"></span><span class="tgt b"></span><span class="note">LIVE WATCH</span><i></i></div>' : ''}
    ${flags.deckOps ? '<div class="bridge3d-deckops-panel"><span class="hold"></span><span class="box b1"></span><span class="box b2"></span><span class="box b3"></span><i class="lash l1"></i><i class="lash l2"></i><b>DECK OPS</b></div>' : ''}
    ${flags.crewLife ? '<div class="bridge3d-life-space"><span class="table"></span><span class="cup"></span><span class="bunk"></span><i class="steam s1"></i><i class="steam s2"></i><b>CREW LIFE</b></div>' : ''}
    ${flags.engineRoom ? '<div class="bridge3d-ecr bridge3d-ecr-pro"><b>ECR / IAS</b><div class="ecr-ann"><em>ME</em><em class="warn">LO</em><em>GEN</em><em>FW</em></div><div class="ecr-mimic"><u class="bus"></u><small class="g1">G1</small><small class="g2">G2</small><small class="me">ME</small><small class="pump">PMP</small><u class="pipe p1"></u><u class="pipe p2"></u><u class="pipe p3"></u></div><div class="ecr-load"><u></u><u></u><u></u></div><strong>ME 72 RPM</strong></div>' : ''}
    ${flags.mooring ? '<div class="bridge3d-mooring-deck"><span class="head"></span><span class="stern"></span><span class="spring"></span><span class="breast"></span><b>SNAP-BACK</b></div>' : ''}
    ${flags.survival ? '<div class="bridge3d-survival-station"><span class="lifeboat"></span><span class="raft"></span><i></i><b>LSA</b></div>' : ''}
    ${flags.fire ? '<div class="bridge3d-fire-room"><span></span><span></span><span></span><b>FIRE ZONE</b></div>' : ''}
    ${flags.routeTable ? '<div class="bridge3d-route-table"><span class="track"></span><i class="wp1"></i><i class="wp2"></i><i class="wp3"></i><b>CPA / UKC</b></div>' : ''}
    ${flags.manifold ? '<div class="bridge3d-manifold-panel"><span class="arm"></span><i></i><i></i><b>ESD</b></div>' : ''}
    ${flags.premiumOps ? '<div class="bridge3d-premium-ops"><span class="platform"></span><span class="rov"></span><span class="ice"></span><b>DP</b></div>' : ''}
    ${flags.starlink ? `<div class="bridge3d-starlink"><span class="dish"></span><span class="beam b1"></span><span class="beam b2"></span><b>${starlinkStatus.online?'LINK OK':'LINK DEG'}</b><i>${Number(starlinkStatus.latency||0)} ms</i></div>` : ''}
    ${flags.helicopter ? '<div class="bridge3d-helicopter"><span></span><i></i><b>MED</b></div><div class="bridge3d-helipad">CLEAR DECK</div>' : ''}
    ${flags.cargoLift ? '<div class="bridge3d-cargo-lift"><span class="hook"></span><span class="load"></span><i></i><b>COG</b></div>' : ''}
    <div class="bridge3d-control-hint">Karakter kontrolu icin sahneye tikla</div>
    <button class="bridge3d-control-launcher" onclick="event.stopPropagation(); openCurrentSceneControlWalk()">
      <b>Karakterle Kontrol Et</b><small>WASD / yon tuslari / mobil pad</small>
    </button>
  </div>`;
}

function stopThreeBridgeScene(){
  if(threeBridgeRuntime.frame) cancelAnimationFrame(threeBridgeRuntime.frame);
  threeBridgeRuntime.frame = null;
  threeBridgeRuntime.token++;
  if(threeBridgeRuntime.renderer){
    try{ threeBridgeRuntime.renderer.dispose(); }catch(e){}
    threeBridgeRuntime.renderer = null;
  }
}

async function ensureThreeBridgeModule(){
  if(threeBridgeRuntime.THREE) return threeBridgeRuntime.THREE;
  const mod = await import('./vendor/three.module.js');
  threeBridgeRuntime.THREE = mod;
  return mod;
}

function addThreeBox(THREE, scene, size, pos, color, emissive=0x000000, roughness=.55){
  const geo = new THREE.BoxGeometry(size[0], size[1], size[2]);
  const mat = new THREE.MeshStandardMaterial({color, emissive, roughness, metalness:.28});
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  scene.add(mesh);
  return mesh;
}

function addThreeCylinder(THREE, scene, radius, depth, pos, color, emissive=0x000000){
  const geo = new THREE.CylinderGeometry(radius, radius, depth, 24);
  const mat = new THREE.MeshStandardMaterial({color, emissive, roughness:.48, metalness:.22});
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  scene.add(mesh);
  return mesh;
}

function addThreeShipModel(THREE, scene, pos, scale=1, hullColor=0x18344a, cabinColor=0xdce8ef, lightColor=0xffd783){
  const group = new THREE.Group();
  const hullMat = new THREE.MeshStandardMaterial({color:hullColor, emissive:0x02070a, roughness:.56, metalness:.24});
  const deckMat = new THREE.MeshStandardMaterial({color:0x7f95a5, emissive:0x071018, roughness:.45, metalness:.16});
  const cabinMat = new THREE.MeshStandardMaterial({color:cabinColor, emissive:0x102033, roughness:.36, metalness:.12});
  const lampMat = new THREE.MeshStandardMaterial({color:lightColor, emissive:lightColor, roughness:.18});
  const hull = new THREE.Mesh(new THREE.BoxGeometry(.62,.12,.18), hullMat);
  const bow = new THREE.Mesh(new THREE.ConeGeometry(.105,.24,4), hullMat);
  const deck = new THREE.Mesh(new THREE.BoxGeometry(.48,.035,.16), deckMat);
  const house = new THREE.Mesh(new THREE.BoxGeometry(.22,.16,.14), cabinMat);
  const stack = new THREE.Mesh(new THREE.BoxGeometry(.055,.17,.055), deckMat);
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(.026, 12, 8), lampMat);
  hull.position.set(0,0,0);
  bow.position.set(.42,0,0);
  bow.rotation.z = -Math.PI/2;
  bow.rotation.y = Math.PI/4;
  deck.position.set(-.02,.08,0);
  house.position.set(.06,.19,0);
  stack.position.set(-.18,.24,0);
  lamp.position.set(.26,.25,.045);
  group.add(hull,bow,deck,house,stack,lamp);
  group.position.set(pos[0], pos[1], pos[2]);
  group.scale.setScalar(scale);
  scene.add(group);
  return group;
}

function addThreeBridgeBow(THREE, scene, flags){
  const group = new THREE.Group();
  const deckMat = new THREE.MeshStandardMaterial({color:flags.storm?0x172638:0x203448, emissive:0x030912, roughness:.62, metalness:.2, transparent:true, opacity:.9});
  const railMat = new THREE.MeshStandardMaterial({color:0x9fb6c5, emissive:0x13283a, roughness:.34, metalness:.34});
  const deck = new THREE.Mesh(new THREE.BoxGeometry(1.55,.045,1.18), deckMat);
  deck.position.set(0,-.08,0);
  deck.rotation.x = -.08;
  group.add(deck);
  [-.58,.58].forEach((x)=>{
    const rail = new THREE.Mesh(new THREE.BoxGeometry(.025,.26,1.05), railMat);
    rail.position.set(x,.08,-.04);
    rail.rotation.z = x < 0 ? -.05 : .05;
    group.add(rail);
  });
  for(let i=0;i<4;i++){
    const stanchion = new THREE.Mesh(new THREE.BoxGeometry(.028,.24,.028), railMat);
    stanchion.position.set(-.55+i*.37,.09,-.46);
    group.add(stanchion);
  }
  const center = new THREE.Mesh(new THREE.BoxGeometry(.055,.1,.72), railMat);
  center.position.set(0,.02,-.18);
  group.add(center);
  group.position.set(0,-.64,-.95);
  group.rotation.x = -.18;
  scene.add(group);
  return group;
}

function addThreeRadarSweep(THREE, scene, center, rotationY=-.18, rotationX=-.08){
  const pivot = new THREE.Group();
  const sweepGeo = new THREE.BoxGeometry(.25,.01,.01);
  sweepGeo.translate(.125,0,0);
  const sweepMat = new THREE.MeshStandardMaterial({color:0x81f7b8, emissive:0x3ddf8a, roughness:.35, metalness:.12});
  const sweep = new THREE.Mesh(sweepGeo, sweepMat);
  pivot.position.set(center[0], center[1], center[2]);
  pivot.rotation.y = rotationY;
  pivot.rotation.x = rotationX;
  pivot.add(sweep);
  scene.add(pivot);
  return pivot;
}

async function renderThreeBridgeScene(sc){
  const mount = document.getElementById('gfx-3d');
  const canvas = mount?.querySelector('.three-bridge-canvas');
  if(!mount || !canvas || !mount.classList.contains('active')) return;
  const token = ++threeBridgeRuntime.token;
  let THREE;
  try{
    THREE = await ensureThreeBridgeModule();
  }catch(err){
    console.warn('Three.js bridge layer unavailable', err);
    return;
  }
  if(token !== threeBridgeRuntime.token) return;
  if(threeBridgeRuntime.frame) cancelAnimationFrame(threeBridgeRuntime.frame);
  if(threeBridgeRuntime.renderer){
    try{ threeBridgeRuntime.renderer.dispose(); }catch(e){}
  }
  const rect = mount.getBoundingClientRect();
  const width = Math.max(320, Math.round(rect.width || 640));
  const height = Math.max(180, Math.round(rect.height || 260));
  const renderer = new THREE.WebGLRenderer({canvas, alpha:true, antialias:true});
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
  renderer.setSize(width, height, false);
  renderer.setClearColor(0x000000, 0);
  threeBridgeRuntime.renderer = renderer;

  const scene = new THREE.Scene();
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const flags = getScene3DFeatureFlags(sc);
  const ecrFocus = flags.engineRoom && !flags.harborApproach && !flags.storm;
  const storm = flags.storm;
  const harbor = flags.harborApproach;
  const cinematicScale = width > 900 ? 1 : width > 560 ? .92 : .82;
  const camera = new THREE.PerspectiveCamera(ecrFocus ? 35 : 38, width/height, .1, 100);
  const cameraBase = {x:ecrFocus ? -.55 : 0, y:ecrFocus ? .84 : .82, z:ecrFocus ? 3.45 : 3.55};
  const cameraTarget = new THREE.Vector3(ecrFocus ? -1.05 : 0, ecrFocus ? -.08 : -.12, ecrFocus ? -.52 : -.04);
  camera.position.set(cameraBase.x, cameraBase.y, cameraBase.z);
  camera.lookAt(cameraTarget);
  scene.add(new THREE.HemisphereLight(0xbddfff, 0x0a1018, 1.8));
  const key = new THREE.DirectionalLight(0x9fd4ff, 1.2);
  key.position.set(-2, 3, 4);
  scene.add(key);

  const hot = /mayday|distress|alarm|yangin|fire|blackout|korsan|pirate/.test(blob);
  const tugOps = flags.harborApproach || flags.mooring;
  const stormObjects = [];
  const harborObjects = [];
  const trainingObjects = [];
  const ambientObjects = [];

  const seaGeo = new THREE.PlaneGeometry(9, 4, 18, 5);
  const seaMat = new THREE.MeshStandardMaterial({color:storm?0x102236:harbor?0x173854:0x174a72, roughness:.9, metalness:.02, transparent:true, opacity:.72});
  const sea = new THREE.Mesh(seaGeo, seaMat);
  sea.rotation.x = -Math.PI/2.6;
  sea.position.set(0, -.58, -2.2);
  scene.add(sea);

  const bridgeBow = addThreeBridgeBow(THREE, scene, flags);
  bridgeBow.scale.setScalar(cinematicScale);
  ambientObjects.push({mesh:bridgeBow, kind:'ownBow', phase:.1, baseY:bridgeBow.position.y});
  [
    {pos:[-2.75,-.38,-2.75], scale:.52, delay:0, color:0x153c5a},
    {pos:[2.45,-.42,-2.45], scale:.42, delay:1.7, color:0x3d5363},
    {pos:[.35,-.47,-3.05], scale:.34, delay:3.1, color:0x24384a}
  ].forEach((cfg, i)=>{
    const ship = addThreeShipModel(THREE, scene, cfg.pos, cfg.scale, cfg.color, i===1?0xeaf2f7:0xdce8ef, i===2?0x81f7b8:0xffd783);
    ship.rotation.y = i===1 ? Math.PI + .08 : -.12;
    ambientObjects.push({mesh:ship, kind:'trafficShip', phase:cfg.delay, baseX:ship.position.x, baseY:ship.position.y, drift:i===1?-1:1});
  });

  for(let i=-2;i<=2;i++){
    const frame = addThreeBox(THREE, scene, [.035, 1.55, .035], [i*.72, .28, -1.25], 0x284056);
    frame.rotation.z = i*.025;
  }
  addThreeBox(THREE, scene, [4.8, .08, .08], [0, 1.05, -1.25], 0x2c4358);
  addThreeBox(THREE, scene, [4.8, .08, .08], [0, -.55, -1.2], 0x111d2a);

  const consoleBase = addThreeBox(THREE, scene, [4.5, .42, 1.52], [0, -.82, .62], 0x142233);
  consoleBase.rotation.x = -.22;
  const lip = addThreeBox(THREE, scene, [4.2, .08, .13], [0, -.45, -.02], 0x2b3e52, 0x061018);
  lip.rotation.x = -.22;

  const ecdis = addThreeBox(THREE, scene, [.82, .46, .08], [-1.18, -.46, .08], 0x0b1722, 0x071d2a);
  ecdis.rotation.y = .18;
  ecdis.rotation.x = -.08;
  const ecdisScreen = addThreeBox(THREE, scene, [.66, .31, .025], [-1.18, -.46, .02], 0x8ad5e8, 0x246070);
  ecdisScreen.rotation.y = .18;
  ecdisScreen.rotation.x = -.08;
  const routeLine = addThreeBox(THREE, scene, [.48, .014, .014], [-1.18, -.44, -.01], 0x9b2f3d, 0x5b1018);
  routeLine.rotation.z = -.28; routeLine.rotation.y = .18; routeLine.rotation.x = -.08;

  const vhf = addThreeBox(THREE, scene, [.78, .48, .16], [0, -.43, .0], 0x131e29, hot?0x2a0808:0x051018);
  vhf.rotation.x = -.06;
  const vhfScreen = addThreeBox(THREE, scene, [.4, .18, .035], [-.1, -.42, -.1], hot?0x113423:0x0c3042, hot?0x236b45:0x185a80);
  vhfScreen.rotation.x = -.06;
  const ptt = addThreeBox(THREE, scene, [.14, .14, .045], [.26, -.41, -.1], 0x1e3448, 0x071018);
  const dist = addThreeBox(THREE, scene, [.14, .1, .045], [.26, -.56, -.08], hot?0x8a1f25:0x4a1a20, hot?0x5a0808:0x1a0305);

  const radar = addThreeBox(THREE, scene, [.68, .46, .09], [1.12, -.47, .08], 0x0a151e, 0x061018);
  radar.rotation.y = -.18;
  radar.rotation.x = -.08;
  const radarDisc = new THREE.Mesh(new THREE.CircleGeometry(.18, 48), new THREE.MeshStandardMaterial({color:0x0a2b1a, emissive:0x165b31, roughness:.45}));
  radarDisc.position.set(1.07, -.47, .01);
  radarDisc.rotation.y = -.18;
  radarDisc.rotation.x = -.08;
  scene.add(radarDisc);
  const radarSweep = addThreeRadarSweep(THREE, scene, [1.07, -.47, -.012], -.18, -.08);

  const conning = addThreeBox(THREE, scene, [.94, .38, .08], [0, -.32, -.17], 0x081521, 0x082238);
  conning.rotation.x = -.1;
  const conningGlow = addThreeBox(THREE, scene, [.76, .24, .025], [0, -.32, -.225], 0x12314a, hot?0x442018:0x0d4762);
  conningGlow.rotation.x = -.1;
  const overhead = addThreeBox(THREE, scene, [2.45, .12, .12], [0, .94, -1.0], 0x172636, 0x03070c);
  overhead.rotation.x = .04;
  const telegraphBase = addThreeBox(THREE, scene, [.22, .12, .2], [.74, -.64, .28], 0x1e2b36, 0x05090d);
  telegraphBase.rotation.x = -.22;
  const telegraphLever = addThreeBox(THREE, scene, [.035, .32, .035], [.76, -.49, .25], hot?0xff6b6b:0xffc458, hot?0x5a0808:0x4a2b08);
  telegraphLever.rotation.z = harbor ? -.28 : storm ? .18 : -.08;
  telegraphLever.rotation.x = -.22;
  const aisRepeater = addThreeBox(THREE, scene, [.62, .34, .07], [1.82, -.5, .12], 0x07151d, 0x06261e);
  aisRepeater.rotation.y = -.32;
  aisRepeater.rotation.x = -.08;
  trainingObjects.push({mesh:conningGlow, kind:'display', phase:.2});
  trainingObjects.push({mesh:telegraphLever, kind:'telegraph', phase:.4, baseZ:telegraphLever.rotation.z});

  if(harbor){
    const crane = new THREE.Group();
    const craneMat = new THREE.MeshStandardMaterial({color:0xffc458, emissive:0x4a2b08, roughness:.5, metalness:.22});
    const mast = new THREE.Mesh(new THREE.BoxGeometry(.045,.82,.045), craneMat);
    const boom = new THREE.Mesh(new THREE.BoxGeometry(.74,.035,.035), craneMat);
    const hookLine = new THREE.Mesh(new THREE.BoxGeometry(.009,.42,.009), craneMat);
    mast.position.set(0,0,0);
    boom.position.set(.34,.32,0);
    boom.rotation.z = -.18;
    hookLine.position.set(.62,.08,0);
    crane.add(mast,boom,hookLine);
    crane.position.set(2.42,-.16,-1.72);
    crane.rotation.y = -.38;
    scene.add(crane);
    harborObjects.push({mesh:crane, kind:'crane', phase:.3, baseY:crane.position.y});
    for(let i=0;i<7;i++){
      const light = addThreeBox(THREE, scene, [.035,.035,.035], [-2.1+i*.7, .04, -1.62], 0xffc458, 0xffa52b);
      light.scale.set(1,1,1);
      harborObjects.push({mesh:light, baseY:light.position.y, kind:'light', phase:i*.7});
    }
    const berth = addThreeBox(THREE, scene, [3.7,.08,.18], [0,-.36,-1.78], 0x3a342a, 0x080402);
    berth.rotation.x = -.08;
    harborObjects.push({mesh:berth, baseY:berth.position.y, kind:'berth'});
    for(let i=0;i<5;i++){
      const bollard = addThreeCylinder(THREE, scene, .035, .12, [-1.5+i*.75,-.27,-1.68], 0x1b2228, 0x020406);
      bollard.rotation.x = Math.PI/2;
      harborObjects.push({mesh:bollard, baseY:bollard.position.y, kind:'bollard'});
    }
    if(tugOps){
      const tug = new THREE.Group();
      const hull = new THREE.Mesh(new THREE.BoxGeometry(.46,.12,.18), new THREE.MeshStandardMaterial({color:0x0f2435, emissive:0x02070a, roughness:.5, metalness:.25}));
      const cabin = new THREE.Mesh(new THREE.BoxGeometry(.18,.16,.14), new THREE.MeshStandardMaterial({color:0xd8e6ee, emissive:0x102036, roughness:.38, metalness:.12}));
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(.035, 16, 10), new THREE.MeshStandardMaterial({color:0xffc458, emissive:0xffa52b, roughness:.2}));
      hull.position.set(0,0,0);
      cabin.position.set(.03,.13,0);
      beacon.position.set(.03,.24,0);
      tug.add(hull,cabin,beacon);
      tug.position.set(-2.25,-.32,-1.34);
      tug.rotation.y = -.28;
      scene.add(tug);
      harborObjects.push({mesh:tug, baseX:tug.position.x, baseY:tug.position.y, kind:'tug'});
      const towLine = addThreeBox(THREE, scene, [1.15,.012,.012], [-1.53,-.32,-1.18], 0xd6c49b, 0x2a1c05);
      towLine.rotation.z = .08;
      towLine.rotation.y = -.22;
      harborObjects.push({mesh:towLine, baseX:towLine.position.x, baseY:towLine.position.y, kind:'towline'});
    }
  }

  if(storm){
    for(let i=0;i<7;i++){
      const crest = addThreeBox(THREE, scene, [.72,.018,.035], [-3.2+i*1.08,-.44,-1.48-(i%3)*.28], 0xc8e4f2, 0x28485e, .82);
      crest.rotation.x = -.34;
      crest.rotation.z = (i%2 ? .08 : -.06);
      stormObjects.push({mesh:crest, baseX:crest.position.x, baseY:crest.position.y, speed:.45+i*.06, phase:i*.8});
    }
    for(let i=0;i<12;i++){
      const rain = addThreeBox(THREE, scene, [.008,.34,.008], [-2.8+i*.52,.75-(i%4)*.18,-.85-(i%3)*.2], 0xb9d7e8, 0x1d4059, .9);
      rain.rotation.z = -.32;
      stormObjects.push({mesh:rain, baseX:rain.position.x, baseY:rain.position.y, speed:1.2+i*.03, phase:i*.35, rain:true});
    }
    const flash = addThreeBox(THREE, scene, [5.4,2.4,.015], [0,.28,-1.85], 0xd9efff, 0x709fff, .2);
    flash.material.transparent = true;
    flash.material.opacity = 0;
    stormObjects.push({mesh:flash, kind:'flash'});
  }

  if(flags.engineRoom){
    const panel = addThreeBox(THREE, scene, [1.08,.64,.08], [-1.78,.04,-.74], 0x101923, 0x071018);
    panel.rotation.y = .42;
    trainingObjects.push({mesh:panel, kind:'panel', phase:.1});
    for(let i=0;i<4;i++){
      const gauge = addThreeCylinder(THREE, scene, .055, .018, [-2.06+i*.18,.08,-.78], i===3?0xff5858:0x7fc3ff, i===3?0x7b1515:0x0d3850);
      gauge.rotation.x = Math.PI/2; gauge.rotation.y = .42;
      trainingObjects.push({mesh:gauge, kind:i===3?'alarm':'gauge', phase:i*.45});
    }
    for(let i=0;i<3;i++){
      const bar = addThreeBox(THREE, scene, [.08,.2+i*.07,.035], [-2.02+i*.22,-.22+i*.025,-.79], i===1?0xffc458:0x5dbf8a, i===1?0x4a2b08:0x0a3420);
      bar.rotation.y = .42;
      trainingObjects.push({mesh:bar, kind:'meter', phase:i*.5});
    }
  }

  if(flags.routineWatch){
    const watchPanel = addThreeBox(THREE, scene, [.82,.42,.06], [-1.95,.04,-.82], 0x081521, 0x0c3042);
    watchPanel.rotation.y = .36;
    trainingObjects.push({mesh:watchPanel, kind:'display', phase:.65});
    const cpaRing = new THREE.Mesh(
      new THREE.TorusGeometry(.18, .006, 8, 48),
      new THREE.MeshStandardMaterial({color:0x81f7b8, emissive:0x1d6840, transparent:true, opacity:.72, roughness:.4})
    );
    cpaRing.position.set(-1.96,.04,-.86);
    cpaRing.rotation.x = Math.PI/2;
    cpaRing.rotation.y = .36;
    scene.add(cpaRing);
    trainingObjects.push({mesh:cpaRing, kind:'watchRing', phase:.2});
    [
      {x:-2.14,y:.12,z:-.9,color:0x81f7b8,phase:.1},
      {x:-1.82,y:.0,z:-.88,color:0xffd783,phase:.8},
      {x:-2.0,y:-.09,z:-.9,color:0x7fc3ff,phase:1.4}
    ].forEach((target)=>{
      const marker = new THREE.Mesh(
        new THREE.SphereGeometry(.026, 14, 10),
        new THREE.MeshStandardMaterial({color:target.color, emissive:target.color, roughness:.28})
      );
      marker.position.set(target.x, target.y, target.z);
      marker.rotation.y = .36;
      scene.add(marker);
      trainingObjects.push({mesh:marker, kind:'watchTarget', phase:target.phase, baseX:marker.position.x, baseY:marker.position.y});
    });
  }

  if(flags.deckOps){
    const opDeck = addThreeBox(THREE, scene, [1.62,.052,.76], [-.62,-.43,-1.18], 0x273746, 0x05080a);
    opDeck.rotation.x = -.08;
    trainingObjects.push({mesh:opDeck, kind:'deck', phase:.2});
    [-.92,-.68,-.44].forEach((x,i)=>{
      const box = addThreeBox(THREE, scene, [.22,.16,.18], [x,-.28,-1.12+i*.04], i===0?0x9b3b34:i===1?0x2d5f96:0xc78331, 0x05080a);
      trainingObjects.push({mesh:box, kind:'container', phase:i*.35, baseY:box.position.y});
    });
    [-.75,-.52].forEach((x,i)=>{
      const lash = addThreeBox(THREE, scene, [.72,.012,.012], [x,-.19,-.82-i*.06], 0xd6c49b, 0x2a1c05);
      lash.rotation.z = i ? .14 : -.14;
      trainingObjects.push({mesh:lash, kind:'line', phase:i*.35, baseZ:lash.rotation.z});
    });
  }

  if(flags.crewLife){
    const table = addThreeCylinder(THREE, scene, .22, .05, [-1.42,-.36,-.5], 0x4b3321, 0x090603);
    table.scale.z = .55;
    trainingObjects.push({mesh:table, kind:'table', phase:.1});
    const cup = addThreeCylinder(THREE, scene, .045, .13, [-1.42,-.27,-.5], 0xf2e2c4, 0x2a1b0b);
    trainingObjects.push({mesh:cup, kind:'cup', phase:.2, baseY:cup.position.y});
    for(let i=0;i<3;i++){
      const steam = new THREE.Mesh(
        new THREE.SphereGeometry(.045+i*.008, 12, 8),
        new THREE.MeshStandardMaterial({color:0xdcecff, transparent:true, opacity:.14, roughness:1})
      );
      steam.position.set(-1.42+.02*i,-.18+i*.035,-.5);
      scene.add(steam);
      trainingObjects.push({mesh:steam, kind:'steam', phase:i*.35, baseY:steam.position.y});
    }
    const bunk = addThreeBox(THREE, scene, [.62,.12,.26], [-2.0,-.31,-.62], 0x173654, 0x041018);
    trainingObjects.push({mesh:bunk, kind:'bunk', phase:.4, baseY:bunk.position.y});
  }

  if(flags.mooring){
    const deck = addThreeBox(THREE, scene, [2.6,.06,.92], [0,-.36,-1.08], 0x26313b, 0x05080a);
    deck.rotation.x = -.08;
    trainingObjects.push({mesh:deck, kind:'deck', phase:0});
    const zone = addThreeBox(THREE, scene, [1.05,.012,.48], [.2,-.27,-.98], 0xff4040, 0x7b1010);
    zone.material.transparent = true; zone.material.opacity = .22;
    trainingObjects.push({mesh:zone, kind:'zone', phase:.2});
    [-.76,-.25,.3,.82].forEach((x,i)=>{
      const line = addThreeBox(THREE, scene, [1.12,.018,.018], [x,-.23,-.72-i*.08], i===2?0xffcc80:0xd6c49b, 0x1a1204);
      line.rotation.z = i%2 ? -.16 : .16;
      trainingObjects.push({mesh:line, kind:'line', phase:i*.4, baseZ:line.rotation.z});
    });
  }

  if(flags.survival){
    const boat = addThreeBox(THREE, scene, [.86,.18,.28], [1.72,.04,-.82], 0xff7a28, 0x5a2000);
    boat.rotation.y = -.34;
    const canopy = addThreeBox(THREE, scene, [.58,.16,.2], [1.72,.22,-.82], 0xf1d7a2, 0x2a1600);
    canopy.rotation.y = -.34;
    trainingObjects.push({mesh:boat, kind:'lifeboat', phase:0}, {mesh:canopy, kind:'lifeboat', phase:.2});
    const raft = addThreeCylinder(THREE, scene, .095, .5, [2.38,-.12,-.72], 0xf5f1df, 0x302a16);
    raft.rotation.z = Math.PI/2;
    trainingObjects.push({mesh:raft, kind:'raft', phase:.4});
    const davit = addThreeBox(THREE, scene, [.035,.72,.035], [1.28,.2,-.8], 0x596b76, 0x071018);
    davit.rotation.z = -.35;
    trainingObjects.push({mesh:davit, kind:'davit', phase:.5});
  }

  if(flags.fire){
    const bulkhead = addThreeBox(THREE, scene, [1.3,.72,.08], [.05,.08,-.88], 0x2c1b18, 0x180303);
    trainingObjects.push({mesh:bulkhead, kind:'panel', phase:.3});
    for(let i=0;i<5;i++){
      const smoke = new THREE.Mesh(new THREE.SphereGeometry(.12+i*.012, 16, 10), new THREE.MeshStandardMaterial({color:0x9ba3a8, transparent:true, opacity:.18, roughness:1}));
      smoke.position.set(-.42+i*.21, -.05+(i%2)*.12, -.7-i*.02);
      scene.add(smoke);
      trainingObjects.push({mesh:smoke, kind:'smoke', phase:i*.5});
    }
    const extinguisher = addThreeCylinder(THREE, scene, .055, .34, [.72,-.18,-.62], 0xe23b35, 0x5a0808);
    extinguisher.rotation.x = Math.PI/2;
    trainingObjects.push({mesh:extinguisher, kind:'alarm', phase:.1});
  }

  if(flags.routeTable){
    const table = addThreeBox(THREE, scene, [1.45,.08,.82], [0,-.3,.05], 0x122438, 0x061322);
    table.rotation.x = -.34;
    trainingObjects.push({mesh:table, kind:'table', phase:0});
    const route = addThreeBox(THREE, scene, [1.02,.014,.014], [0,-.22,-.28], 0xff5c63, 0x7b1018);
    route.rotation.z = -.22; route.rotation.x = -.34;
    trainingObjects.push({mesh:route, kind:'route', phase:.2});
    for(let i=0;i<4;i++){
      const wp = new THREE.Mesh(new THREE.SphereGeometry(.035, 14, 10), new THREE.MeshStandardMaterial({color:0xffd783, emissive:0xffa52b, roughness:.28}));
      wp.position.set(-.45+i*.3,-.2+i*.015,-.3+i*.035);
      scene.add(wp);
      trainingObjects.push({mesh:wp, kind:'wp', phase:i*.35});
    }
  }

  if(flags.manifold){
    const pipe = addThreeCylinder(THREE, scene, .045, 1.52, [1.58,-.3,-.5], 0x596b76, 0x071018);
    pipe.rotation.z = Math.PI/2; pipe.rotation.y = -.28;
    trainingObjects.push({mesh:pipe, kind:'pipe', phase:0});
    for(let i=0;i<3;i++){
      const valve = addThreeCylinder(THREE, scene, .07, .04, [1.1+i*.33,-.22,-.5], i===1?0xffc458:0x7fc3ff, i===1?0x4a2b08:0x0d3850);
      valve.rotation.x = Math.PI/2;
      trainingObjects.push({mesh:valve, kind:'valve', phase:i*.45});
    }
    const esd = addThreeCylinder(THREE, scene, .075, .035, [2.32,-.2,-.48], 0xe23b35, 0x8a1010);
    esd.rotation.x = Math.PI/2;
    trainingObjects.push({mesh:esd, kind:'alarm', phase:.6});
  }

  if(flags.premiumOps){
    const platform = addThreeBox(THREE, scene, [.62,.34,.52], [-2.2,.0,-1.42], 0x3b4650, 0x111820);
    trainingObjects.push({mesh:platform, kind:'platform', phase:0});
    for(let i=0;i<4;i++){
      const leg = addThreeBox(THREE, scene, [.04,.62,.04], [-2.44+(i%2)*.48,-.38,-1.62+Math.floor(i/2)*.38], 0x61727e, 0x071018);
      trainingObjects.push({mesh:leg, kind:'platform', phase:i*.2});
    }
    const dpRing = new THREE.Mesh(new THREE.TorusGeometry(.42,.01,8,48), new THREE.MeshStandardMaterial({color:0x5dbf8a, emissive:0x123d26, transparent:true, opacity:.72}));
    dpRing.position.set(-2.2,-.02,-1.42);
    dpRing.rotation.x = Math.PI/2;
    scene.add(dpRing);
    trainingObjects.push({mesh:dpRing, kind:'ring', phase:.3});
    const rov = addThreeBox(THREE, scene, [.18,.12,.14], [-1.58,-.48,-1.12], 0xffc458, 0x4a2b08);
    trainingObjects.push({mesh:rov, kind:'rov', phase:.6});
    for(let i=0;i<4;i++){
      const ice = addThreeBox(THREE, scene, [.34,.025,.18], [.8+i*.38,-.48,-1.55+(i%2)*.22], 0xd9f3ff, 0x244050);
      ice.rotation.z = i*.27;
      ice.material.transparent = true; ice.material.opacity = .72;
      trainingObjects.push({mesh:ice, kind:'ice', phase:i*.4});
    }
  }

  if(flags.starlink){
    const mast = addThreeCylinder(THREE, scene, .018, .52, [2.08,-.05,-.72], 0x9fb4c0, 0x101820);
    mast.rotation.x = 0;
    trainingObjects.push({mesh:mast, kind:'mast', phase:0});
    const dish = addThreeBox(THREE, scene, [.42,.035,.18], [2.08,.22,-.72], 0xdde7f0, 0x24384a);
    dish.rotation.z = -.18;
    dish.rotation.y = -.32;
    trainingObjects.push({mesh:dish, kind:'satDish', phase:.2});
    const beam = new THREE.Mesh(
      new THREE.TorusGeometry(.34,.008,8,46,Math.PI*1.35),
      new THREE.MeshBasicMaterial({color:0x58d6ff, transparent:true, opacity:.34})
    );
    beam.position.set(2.0,.47,-.78);
    beam.rotation.x = Math.PI/2;
    beam.rotation.z = -.55;
    scene.add(beam);
    trainingObjects.push({mesh:beam, kind:'satBeam', phase:.4});
    const linkLed = addThreeCylinder(THREE, scene, .035, .018, [2.36,.15,-.66], starlinkStatus.online?0x5df58a:0xffc458, starlinkStatus.online?0x1a7b35:0x7b4a08);
    linkLed.rotation.x = Math.PI/2;
    trainingObjects.push({mesh:linkLed, kind:'alarm', phase:.8});
  }

  if(flags.helicopter){
    const heli = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(.34,.13,.13), new THREE.MeshStandardMaterial({color:0x24384a, emissive:0x071018, roughness:.45, metalness:.28}));
    const tail = new THREE.Mesh(new THREE.BoxGeometry(.34,.035,.035), new THREE.MeshStandardMaterial({color:0x24384a, emissive:0x071018, roughness:.45, metalness:.28}));
    const rotor = new THREE.Mesh(new THREE.BoxGeometry(.64,.012,.012), new THREE.MeshStandardMaterial({color:0xdde7f0, emissive:0x24384a, roughness:.3, metalness:.18}));
    const light = new THREE.Mesh(new THREE.SphereGeometry(.026, 12, 8), new THREE.MeshStandardMaterial({color:0xff5858, emissive:0xff2020, roughness:.18}));
    body.position.set(0,0,0);
    tail.position.set(.34,.02,0);
    rotor.position.set(0,.12,0);
    light.position.set(-.16,.03,.07);
    heli.add(body, tail, rotor, light);
    heli.position.set(-1.95,.72,-1.35);
    heli.rotation.y = .28;
    scene.add(heli);
    trainingObjects.push({mesh:heli, kind:'helicopter', phase:0, baseX:heli.position.x, baseY:heli.position.y});
    trainingObjects.push({mesh:rotor, kind:'rotor', phase:0});
    const helipad = addThreeCylinder(THREE, scene, .26, .014, [-1.34,-.36,-1.58], 0x273746, 0x071018);
    helipad.rotation.x = Math.PI/2;
    trainingObjects.push({mesh:helipad, kind:'ring', phase:.6});
  }

  if(flags.cargoLift){
    const boom = addThreeBox(THREE, scene, [1.06,.035,.035], [.88,.45,-1.05], 0xb9c7d1, 0x182837);
    boom.rotation.z = -.38;
    boom.rotation.y = -.28;
    trainingObjects.push({mesh:boom, kind:'boom', phase:0});
    const cable = addThreeCylinder(THREE, scene, .007, .72, [1.25,.08,-1.05], 0xd6c49b, 0x2a1c05);
    cable.rotation.x = 0;
    trainingObjects.push({mesh:cable, kind:'hook', phase:.2, baseY:cable.position.y});
    const hook = addThreeBox(THREE, scene, [.1,.08,.045], [1.25,-.27,-1.05], 0xffc458, 0x5a3300);
    trainingObjects.push({mesh:hook, kind:'hook', phase:.3, baseY:hook.position.y});
    const load = addThreeBox(THREE, scene, [.42,.2,.28], [1.25,-.48,-1.05], 0x41505a, 0x071018);
    trainingObjects.push({mesh:load, kind:'load', phase:.4, baseY:load.position.y});
  }

  const started = performance.now();
  const animate = (now)=>{
    if(token !== threeBridgeRuntime.token) return;
    const t = (now - started) / 1000;
    radarSweep.rotation.z = t * 2.35;
    sea.position.x = Math.sin(t*.7) * .05;
    sea.position.y = -.58 + Math.sin(t*1.3) * (storm ? .035 : .012);
    consoleBase.rotation.z = Math.sin(t*.8) * (storm ? .012 : .003);
    if(storm){
      camera.rotation.z = Math.sin(t*1.6) * .012;
      camera.position.y = cameraBase.y + Math.sin(t*1.25) * .035;
      camera.position.x = cameraBase.x + Math.sin(t*.9) * .025;
    }else{
      camera.rotation.z = Math.sin(t*.45) * .003;
      camera.position.y = cameraBase.y + Math.sin(t*.65) * (ecrFocus ? .003 : .006);
      camera.position.x = cameraBase.x + Math.sin(t*.45) * (ecrFocus ? .006 : .01);
    }
    camera.lookAt(cameraTarget);
    ambientObjects.forEach((obj)=>{
      if(obj.kind === 'ownBow'){
        obj.mesh.position.y = obj.baseY + Math.sin(t*1.15 + obj.phase) * (storm ? .035 : .012);
        obj.mesh.rotation.z = Math.sin(t*.9 + obj.phase) * (storm ? .018 : .006);
      }else if(obj.kind === 'trafficShip'){
        obj.mesh.position.x = obj.baseX + Math.sin(t*.22 + obj.phase) * .18 + obj.drift * t * .012;
        obj.mesh.position.y = obj.baseY + Math.sin(t*.85 + obj.phase) * .018;
        obj.mesh.rotation.z = Math.sin(t*.75 + obj.phase) * .012;
      }
    });
    stormObjects.forEach((obj)=>{
      if(obj.kind === 'flash'){
        obj.mesh.material.opacity = (Math.sin(t*2.4) > .985) ? .34 : 0;
        return;
      }
      if(obj.rain){
        obj.mesh.position.y = obj.baseY - ((t*obj.speed + obj.phase) % 1.2);
        obj.mesh.position.x = obj.baseX + Math.sin(t*1.4+obj.phase)*.05;
      }else{
        obj.mesh.position.x = obj.baseX + Math.sin(t*obj.speed+obj.phase)*.22;
        obj.mesh.position.y = obj.baseY + Math.sin(t*(obj.speed+1)+obj.phase)*.035;
      }
    });
    harborObjects.forEach((obj)=>{
      if(obj.kind === 'light'){
        obj.mesh.material.emissiveIntensity = .7 + Math.sin(t*2.4 + obj.phase)*.28;
      }else if(obj.kind === 'tug'){
        obj.mesh.position.x = obj.baseX + Math.sin(t*.55)*.38;
        obj.mesh.position.y = obj.baseY + Math.sin(t*1.6)*.025;
        obj.mesh.rotation.y = -.28 + Math.sin(t*.7)*.08;
      }else if(obj.kind === 'towline'){
        obj.mesh.position.x = obj.baseX + Math.sin(t*.55)*.18;
        obj.mesh.rotation.z = .08 + Math.sin(t*2.2)*.025;
      }else if(obj.kind === 'crane'){
        obj.mesh.position.y = obj.baseY + Math.sin(t*.9 + obj.phase)*.018;
        obj.mesh.rotation.z = Math.sin(t*.55 + obj.phase)*.018;
      }
    });
    trainingObjects.forEach((obj)=>{
      if(obj.kind === 'alarm'){
        obj.mesh.material.emissiveIntensity = 1 + Math.max(0, Math.sin(t*6 + obj.phase))*.75;
      }else if(obj.kind === 'display'){
        obj.mesh.material.emissiveIntensity = .82 + Math.sin(t*2.2 + obj.phase)*.18;
      }else if(obj.kind === 'telegraph'){
        obj.mesh.rotation.z = obj.baseZ + Math.sin(t*1.8 + obj.phase)*.035;
        obj.mesh.material.emissiveIntensity = .62 + Math.sin(t*2.4 + obj.phase)*.12;
      }else if(obj.kind === 'watchTarget'){
        obj.mesh.position.x = obj.baseX + Math.sin(t*.55 + obj.phase)*.055;
        obj.mesh.position.y = obj.baseY + Math.cos(t*.7 + obj.phase)*.028;
        obj.mesh.material.emissiveIntensity = .78 + Math.sin(t*2.6 + obj.phase)*.18;
      }else if(obj.kind === 'watchRing'){
        obj.mesh.rotation.z = t*.44;
        obj.mesh.material.opacity = .52 + Math.sin(t*1.8 + obj.phase)*.14;
      }else if(obj.kind === 'gauge' || obj.kind === 'meter' || obj.kind === 'valve' || obj.kind === 'wp'){
        obj.mesh.scale.y = 1 + Math.sin(t*2.3 + obj.phase)*.08;
        obj.mesh.material.emissiveIntensity = .75 + Math.sin(t*2 + obj.phase)*.16;
      }else if(obj.kind === 'line'){
        obj.mesh.rotation.z = obj.baseZ + Math.sin(t*8 + obj.phase)*.025;
        obj.mesh.scale.x = 1 + Math.sin(t*5 + obj.phase)*.025;
      }else if(obj.kind === 'container'){
        obj.mesh.position.y = obj.baseY + Math.sin(t*1.4 + obj.phase)*.008;
        obj.mesh.material.emissiveIntensity = .35 + Math.sin(t*1.7 + obj.phase)*.08;
      }else if(obj.kind === 'zone'){
        obj.mesh.material.opacity = .14 + Math.abs(Math.sin(t*2.8 + obj.phase))*.18;
      }else if(obj.kind === 'smoke'){
        obj.mesh.position.y += Math.sin(t*.9 + obj.phase)*.0009;
        obj.mesh.material.opacity = .12 + Math.abs(Math.sin(t*1.4 + obj.phase))*.08;
      }else if(obj.kind === 'steam'){
        obj.mesh.position.y = obj.baseY + ((t*.18 + obj.phase) % .16);
        obj.mesh.material.opacity = .08 + Math.abs(Math.sin(t*1.2 + obj.phase))*.1;
      }else if(obj.kind === 'cup' || obj.kind === 'bunk'){
        obj.mesh.position.y = obj.baseY + Math.sin(t*.9 + obj.phase)*.006;
      }else if(obj.kind === 'lifeboat' || obj.kind === 'raft'){
        obj.mesh.position.y += Math.sin(t*1.2 + obj.phase)*.0008;
      }else if(obj.kind === 'route'){
        obj.mesh.material.emissiveIntensity = .85 + Math.sin(t*2.8)*.2;
      }else if(obj.kind === 'ring'){
        obj.mesh.rotation.z = t*.5;
        obj.mesh.material.opacity = .52 + Math.sin(t*1.8)*.12;
      }else if(obj.kind === 'rov'){
        obj.mesh.position.y = -.48 + Math.sin(t*1.7 + obj.phase)*.04;
        obj.mesh.position.x = -1.58 + Math.sin(t*.7)*.08;
      }else if(obj.kind === 'ice'){
        obj.mesh.position.x += Math.sin(t*.5 + obj.phase)*.0008;
      }else if(obj.kind === 'satDish'){
        obj.mesh.rotation.z = -.18 + Math.sin(t*1.6 + obj.phase)*.035;
        obj.mesh.material.emissiveIntensity = .45 + Math.sin(t*2.1 + obj.phase)*.1;
      }else if(obj.kind === 'satBeam'){
        obj.mesh.rotation.z = -.55 + Math.sin(t*.8 + obj.phase)*.1;
        obj.mesh.material.opacity = .18 + Math.abs(Math.sin(t*1.6 + obj.phase))*.24;
      }else if(obj.kind === 'helicopter'){
        obj.mesh.position.x = obj.baseX + Math.sin(t*.7 + obj.phase)*.18;
        obj.mesh.position.y = obj.baseY + Math.sin(t*1.4 + obj.phase)*.04;
        obj.mesh.rotation.z = Math.sin(t*1.2)*.035;
      }else if(obj.kind === 'rotor'){
        obj.mesh.rotation.y = t*12;
        obj.mesh.rotation.z = t*18;
      }else if(obj.kind === 'hook' || obj.kind === 'load'){
        obj.mesh.position.y = obj.baseY + Math.sin(t*1.5 + obj.phase)*.035;
        obj.mesh.rotation.z = Math.sin(t*1.15 + obj.phase)*.035;
      }
    });
    radarDisc.material.emissiveIntensity = .8 + Math.sin(t*3) * .12;
    vhfScreen.material.emissiveIntensity = hot ? 1.4 + Math.sin(t*7)*.35 : 1.05 + Math.sin(t*2.4)*.12;
    renderer.render(scene, camera);
    threeBridgeRuntime.frame = requestAnimationFrame(animate);
  };
  threeBridgeRuntime.frame = requestAnimationFrame(animate);
}

function getScene4KOverlay(sc, blob){
  const profile = getSceneBackdropProfile(sc);
  const tags = ['live-4k-grade', `profile-${profile}`];
  if(/radar|bridge|kopruustu|köprüüstü|ecdis|ais|arpa|chart|harita|route/.test(blob)) tags.push('nav');
  if(/harbor|liman|terminal|berth|rihtim|rıhtım|tug|pilot|all fast|cargo watch/.test(blob)) tags.push('port');
  if(/storm|firtina|swell|rain|yagmur|yağmur|salt|spray|sis|fog|mist/.test(blob)) tags.push('storm');
  if(/cruise|kruvaziyer|project|proje|heavy.?lift|research|survey|rov|offshore|platform|dp |ice|buz|cable|pipe|fpso|shuttle/.test(blob)) tags.push('premium');
  const layers = ['<div class="live-4k-noise"></div><div class="live-4k-depth"></div>'];
  if(tags.includes('nav')){
    layers.push('<div class="live-4k-glass"></div><div class="live-4k-ecdis-grid"></div><div class="live-4k-device-scan"></div><div class="live-4k-bridge-reflection"></div>');
  }
  if(tags.includes('port')){
    layers.push('<div class="live-4k-terminal-depth"><i></i><i></i><i></i></div><div class="live-4k-harbor-glow"></div><div class="live-4k-port-haze"></div>');
  }
  if(tags.includes('storm')){
    layers.push('<div class="live-4k-stormglass"></div><div class="live-4k-salt-map"></div><div class="live-4k-wave-burst"></div>');
  }
  if(tags.includes('premium')){
    layers.push('<div class="live-4k-premium-beam"></div><div class="live-4k-operation-sparks"></div><div class="live-4k-specialist-grid"></div>');
  }
  layers.push('<div class="live-4k-depth-ships"></div><div class="live-4k-lens-dust"></div>');
  return `<div class="${tags.join(' ')}" aria-hidden="true">${layers.join('')}</div>`;
}

function getGraphicLivelinessOverlay(sc, blob){
  const st = liveVoyageState || computeLiveVoyageState(sc || {});
  const profile = getSceneBackdropProfile(sc);
  const parts = [];
  const navLike = /radar|bridge|kopruustu|köprüüstü|ecdis|ais|arpa|chart|route|seyir|vhf|vts|pilot/.test(blob);
  const portLike = /harbor|liman|terminal|berth|rihtim|rıhtım|tug|pilot|mooring|all fast/.test(blob);
  const stormLike = /storm|firtina|swell|rain|yagmur|yağmur|sis|fog|mist/.test(blob) || profile === 'storm';
  const engineLike = /engine|makine|blackout|generator|pump|compressor|alarm/.test(blob);
  if(navLike){
    parts.push(`<div class="live-nav-telemetry">
      <span>SOG ${phoneSafe(st.sog || '--')}</span><span>COG ${phoneSafe(st.cog || '---')}</span><span>CPA ${phoneSafe(st.cpa || '--')}</span><span>TCPA ${phoneSafe(st.tcpa || '--')}</span><span>UKC ${phoneSafe(st.ukc || '--')}</span>
    </div>`);
    parts.push(`<div class="live-ais-list">
      <b>AIS / ARPA</b>
      <span class="${Number(st.cpa)<1.1?'warn':''}">M/V ORION · CPA ${phoneSafe(st.cpa || '--')}</span>
      <span>CHEM TANKER · TCPA ${phoneSafe(st.tcpa || '--')}m</span>
      <span>FISHING · COG ${phoneSafe(st.cog || '082')}</span>
    </div>`);
    parts.push('<div class="live-route-trail"><i></i><i></i><i></i><b></b></div>');
  }
  if(portLike){
    parts.push('<div class="live-yard-depth"><i></i><i></i><i></i><i></i></div><div class="live-tug-wake"></div><div class="live-line-tension-card"><b>LINE</b><span></span></div>');
  }
  if(stormLike){
    parts.push('<div class="live-window-beads"><i></i><i></i><i></i><i></i><i></i></div><div class="live-horizon-roll"></div>');
  }
  if(engineLike){
    parts.push('<div class="live-ecr-trend"><b>ECR TREND</b><span></span><span></span><span></span></div><div class="live-engine-vibration"></div>');
  }
  parts.push(`<div class="live-ai-nudge"><b>AI</b><span>${phoneSafe(st.alert ? 'Risk yuksek: cihaz + rapor' : 'Sahne baglami okunuyor')}</span></div>`);
  parts.push('<div class="live-crew-shadow s1"></div><div class="live-crew-shadow s2"></div>');
  parts.push('<div class="live-microtask-pulse"><i></i><span></span><span></span></div>');
  return `<div class="live-graphics-boost profile-${profile}" aria-hidden="true">${parts.join('')}</div>`;
}

function isModernBridgeScene(sc, blob=''){
  const hay = blob || `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const flags = getScene3DFeatureFlags(sc || {});
  return flags.bridgeConsole || flags.harborApproach || flags.routeTable || /bridge|kopruustu|köprüüstü|radar|arpa|ecdis|ais|vhf|dsc|gmdss|bnwas|gyro|telegraph|chart room|seyir|route|vts|pilot|tss|bogaz|boğaz/.test(hay);
}

function getModernBridgeOverlay(sc, blob=''){
  if(!isModernBridgeScene(sc, blob)) return '';
  const hay = blob || `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const st = liveVoyageState || computeLiveVoyageState(sc || {});
  const hot = /mayday|distress|mob|fire|yangin|yangın|blackout|korsan|pirate|alarm/.test(hay) || sc?.alert || Number(st.cpa) < 1.1;
  const isPilot = /pilot|tug|berth|liman|harbor|terminal|all fast/.test(hay);
  const isVts = /vts|tss|strait|bogaz|boğaz|reporting point/.test(hay);
  const vhf = /dsc|channel 70|ch70/.test(hay) ? '70' : hot ? '16' : isVts ? '12' : isPilot ? '14' : '13';
  return `<div class="modern-bridge-overlay ${hot?'warn':''}" aria-hidden="true">
    <div class="modern-bridge-window-grid"><i></i><i></i><i></i><i></i><i></i></div>
    <div class="modern-bridge-reflection"></div>
    <div class="modern-bridge-traffic-lights"><i></i><i></i><i></i><i></i><i></i></div>
    <div class="modern-bridge-console">
      <section class="modern-bridge-panel modern-bridge-ecdis">
        <b>ECDIS</b><em>ROUTE MON</em><span class="mb-route"></span><span class="mb-ship"></span><i class="wp1"></i><i class="wp2"></i><i class="wp3"></i>
      </section>
      <section class="modern-bridge-panel modern-bridge-radar">
        <b>RADAR / ARPA</b><em>CPA ${phoneSafe(st.cpa || '--')}</em><span class="mb-sweep"></span><i class="t1"></i><i class="t2"></i><i class="t3"></i>
      </section>
      <section class="modern-bridge-panel modern-bridge-ais">
        <b>AIS TARGETS</b><span>M/V ORION</span><span>TCPA ${phoneSafe(st.tcpa || '--')}m</span><span>COG ${phoneSafe(st.cog || '---')}</span>
      </section>
      <section class="modern-bridge-panel modern-bridge-vhf">
        <b>VHF DSC</b><strong>CH${phoneSafe(vhf)}</strong><em>${hot?'DISTRESS WATCH':isPilot?'PILOT / TUG':isVts?'VTS REPORT':'BRIDGE WATCH'}</em><span></span><span></span><span></span>
      </section>
      <section class="modern-bridge-panel modern-bridge-bnwas"><b>BNWAS</b><strong>OK</strong><span></span></section>
      <section class="modern-bridge-panel modern-bridge-telegraph"><b>TELEGRAPH</b><i></i><em>${isPilot?'D/SLOW':'STBY'}</em></section>
    </div>
  </div>`;
}

function getProfessionalGraphicsOverlay(sc, blob=''){
  const hay = blob || `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const flags = getScene3DFeatureFlags(sc || {});
  const nav = flags.bridgeConsole || flags.routeTable || /radar|arpa|ecdis|ais|vhf|dsc|chart|harita|route|seyir|vts|pilot/.test(hay);
  const atlas = flags.routeTable || /world atlas|atlas|dunya|dünya|bogaz|boğaz|canal|kanal|strait|passage plan|tss|pilot station|no anchoring/.test(hay);
  const ops = flags.mooring || flags.manifold || flags.survival || flags.fire || flags.engineRoom || flags.premiumOps || flags.helicopter || flags.cargoLift;
  const profile = getSceneBackdropProfile(sc || {});
  const st = liveVoyageState || computeLiveVoyageState(sc || {});
  const chips = [];
  if(nav){
    chips.push(`<span><b>RADAR</b><em>CPA ${phoneSafe(st.cpa || '--')}</em></span>`);
    chips.push(`<span><b>ECDIS</b><em>WP ${phoneSafe(st.nextWp || st.wp || 'NEXT')}</em></span>`);
    chips.push(`<span><b>VHF</b><em>${/pilot|tug|liman|harbor/.test(hay) ? 'CH14' : /vts|tss|strait|bogaz|boğaz/.test(hay) ? 'CH12' : 'CH16'}</em></span>`);
    chips.push(`<span><b>AIS</b><em>SOG ${phoneSafe(st.sog || '--')}</em></span>`);
  }
  const atlasHtml = atlas ? `<div class="pro-atlas-chip"><b>ATLAS / ECDIS</b><span>chart scale + route monitor + task hitbox</span><i></i><i></i><i></i></div>` : '';
  const presetHtml = `<div class="pro-preset-chip"><b>ROLE PRESET</b><span>gender + rank + uniform locked</span></div>`;
  const opsHtml = ops ? `<div class="pro-ops-depth ${flags.premiumOps?'premium':''}">
      <b>${flags.manifold?'MANIFOLD':flags.mooring?'MOORING':flags.survival?'LSA':flags.fire?'FIRE':flags.engineRoom?'ECR':'SPECIAL OPS'}</b>
      <span></span><span></span><span></span>
    </div>` : '';
  const cinemaHtml = sc?.cinematic ? `<div class="pro-cinema-bar"><span>CINEMATIC</span><b>${phoneSafe(sc.cinematicKey || sc.id || 'scene')}</b></div>` : '';
  return `<div class="pro-graphics-overlay profile-${profile} ${nav?'nav':''} ${atlas?'atlas':''} ${ops?'ops':''}" aria-hidden="true">
    <div class="pro-glass-stack"><i></i><i></i><i></i></div>
    ${chips.length ? `<div class="pro-device-row">${chips.join('')}</div>` : ''}
    ${atlasHtml}
    ${presetHtml}
    ${opsHtml}
    ${cinemaHtml}
  </div>`;
}

