function getSafeSceneMarkup(sc){
  const key = sc?.gfx || 'sea';
  const safeKey = GFX[key] ? key : 'sea';
  const base = GFX[safeKey] || GFX.sea;
  try{
    return base + getSceneOverlay(safeKey, sc);
  }catch(err){
    console.warn('Scene render fallback:', safeKey, err);
    return base;
  }
}
