function getPlayerPortraitConfig(){
  const uniformMap = {
    classic:{suitColor:'#1b2435', shirtColor:'#f2f0ea', tieColor:'#13171d', stripes:1},
    dress:{suitColor:'#141f2f', shirtColor:'#f6f4ef', tieColor:'#0f141b', stripes:2},
    duty:{suitColor:'#223244', shirtColor:'#eef1f4', tieColor:'#16202b', stripes:1},
    engine:{suitColor:'#263548', shirtColor:'#d5dee8', tieColor:'#17202a', stripes:0},
    deck:{suitColor:'#1d3142', shirtColor:'#e6edf3', tieColor:'#15202d', stripes:0},
    galley:{suitColor:'#f0f2ee', shirtColor:'#ffffff', tieColor:'#2c333b', stripes:0},
    cadet:{suitColor:'#162234', shirtColor:'#edf0f2', tieColor:'#11161d', stripes:1}
  };
  const uniform = uniformMap[playerAppearance.uniform] || uniformMap.classic;
  const modelMeta = (PLAYER_PHOTO_MODELS[playerAppearance.base] || {})[playerAppearance.model] || {};
  const portraitSheet = playerAppearance.age === 'young'
    ? PORTRAIT_SHEET_ASSETS.officerYoung
    : PORTRAIT_SHEET_ASSETS.officerMid;
  return {
    skin:playerAppearance.skin,
    base:playerAppearance.base,
    model:playerAppearance.model,
    face:playerAppearance.face,
    hair:playerAppearance.hair,
    beard:playerAppearance.beard,
    hairColor:playerAppearance.hairColor,
    eye:playerAppearance.eye,
    uniform:playerAppearance.uniform,
    height:playerAppearance.height || 175,
    weight:playerAppearance.weight || 72,
    age:playerAppearance.age,
    pose:playerAppearance.pose,
    scene:playerAppearance.scene,
    suitColor:uniform.suitColor,
    shirtColor:uniform.shirtColor,
    tieColor:uniform.tieColor,
    stripes:uniform.stripes,
    isPlayer:true,
    faceAsset:playerStyledFacePhoto || '',
    portraitSheet,
    sheetCols:4,
    sheetRows:2,
    sheetIndex:Number.isInteger(modelMeta.sheetIndex) ? modelMeta.sheetIndex : resolvePortraitIndexFromConfig(playerAppearance),
    bg:'bridge'
  };
}

