function summarizeDialogueText(text){
  const raw = String(text || '').replace(/\s+/g,' ').trim();
  return raw;
}

function renderDialogueLog(){
  const wrap = document.getElementById('dialogue-log');
  if(!wrap) return;
  const items = dialogueHistory.slice(-16);
  if(!items.length){
    wrap.innerHTML = '';
    return;
  }
  wrap.innerHTML = items.map(entry=>`
    <div class="dialogue-entry ${entry.side}">
      <div class="dialogue-avatar">${renderPortraitSprite(entry.portrait, 'avatar')}</div>
      <div class="dialogue-card">
        <div class="dialogue-name">${phoneSafe(translateGameText(entry.name))}</div>
        <div class="dialogue-body">${phoneSafe(translateGameText(summarizeDialogueText(entry.text)))}</div>
      </div>
    </div>
  `).join('');
  wrap.scrollTop = wrap.scrollHeight;
}

function pushDialogueEntry(side, portrait, name, text){
  dialogueHistory.push({
    side: side === 'right' ? 'right' : 'left',
    portrait: portrait || getPlayerPortraitConfig(),
    name: name || 'Stajyer',
    text: String(text || '')
  });
  if(dialogueHistory.length > 40) dialogueHistory = dialogueHistory.slice(-40);
  renderDialogueLog();
}

function maybePushDialogueInterjection(sc,c2){
  if(!sc || !c2) return;
  const blob = `${sc.gfx||''} ${sc.loc||''} ${sc.sub||''} ${sc.text||''} ${c2.text||''}`.toLowerCase();
  let key = '';
  let line = '';
  if(c2.tag === 'korkak' || c2.tag === 'hileli'){
    key = /engine|makine|pump|generator|alarm/.test(blob) ? 'carkci' : /deck|halat|mooring|tug|guverte/.test(blob) ? 'lostromo' : 'suvari';
    line = 'Bu cevap kayda girdi. Simdi bunu nasil toparlayacagini gormek istiyorum.';
  }else if(c2.tag === 'kritik'){
    key = /engine|makine|pump|generator|alarm/.test(blob) ? 'carkci' : /vhf|radar|ecdis|arpa|ais|bridge|kopruustu/.test(blob) ? 'z2' : 'suvari';
    line = 'Bu daha profesyonel oldu. Sebebini de logbook satirinda net yaz.';
  }else if(/pilot|vhf|radar|ecdis|engine|makine|fire|yangin|mooring|halat|survey|psc/.test(blob) && Math.random() < .72){
    key = /fire|yangin|psc|survey|permit|muster/.test(blob) ? 'z3' : /engine|makine/.test(blob) ? 'carkci' : /mooring|halat|deck|guverte/.test(blob) ? 'lostromo' : 'z1';
    line = 'Ben de bunu takip edecegim. Bir sonraki adimi atlamadan kapat.';
  }
  if(!key || !CREW_DEFS[key]) return;
  pushDialogueEntry('left', getCrewPortraitForKey(key), CREW_DEFS[key].name, line);
  addWatchFeed(`${CREW_DEFS[key].name}: ${line}`, c2.tag === 'korkak' || c2.tag === 'hileli' ? 'warn' : 'good');
}

function getSceneEmotion(sc, role='speaker'){
  const hay = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  if(/yangin|fire|mob|alarm|pirate|korsan|blackout|panic|acil/.test(hay)) return role === 'player' ? 'alert' : 'stern';
  if(/kavga|mobbing|itaatsizlik|sikayet|complaint|argue|tension/.test(hay)) return 'angry';
  if(/tesekkur|tebrik|rahatlama|sessizce|cay|coffee|cook|galley/.test(hay)) return 'warm';
  if(/yorgun|uykusuz|fatigue|yalnizlik|homesick|gece 04|03:|04:/.test(hay) || psyche.tukenme >= 68) return 'tired';
  if(mood <= 35) return role === 'player' ? 'tired' : 'stern';
  return 'calm';
}

function applySceneEmotions(sc){
  const speech = document.getElementById('speechportrait');
  const player = document.getElementById('playerstand');
  if(speech) speech.dataset.emotion = getSceneEmotion(sc, 'speaker');
  if(player) player.dataset.emotion = getSceneEmotion(sc, 'player');
}

