function renderCharacterCreator(){
  normalizePlayerAppearance();
  const modelPool = getPlayerModelPool(playerAppearance.base, playerAppearance.age).map(String);
  const hairPool = getCreatorHairPool(playerAppearance.base);
  renderCreatorRow('creator-skin', PLAYER_LOOK.skin, playerAppearance.skin, 'swatch');
  renderCreatorRow('creator-base', PLAYER_LOOK.base, playerAppearance.base, 'text');
  renderCreatorRow('creator-age', PLAYER_LOOK.age, playerAppearance.age, 'text');
  renderCreatorBodyControls();
  renderCreatorRow('creator-scene', PLAYER_LOOK.scene, playerAppearance.scene, 'text');
  renderCreatorRow('creator-model', modelPool, String(playerAppearance.model), 'text');
  renderCreatorRow('creator-hair', hairPool, playerAppearance.hair, 'text');
  const beardRow = document.getElementById('creator-beard');
  const beardLbl = beardRow ? beardRow.previousElementSibling : null;
  if(playerAppearance.base==='female'){
    if(beardLbl) beardLbl.style.display = 'none';
    if(beardRow) beardRow.innerHTML = '';
  }else{
    if(beardLbl) beardLbl.style.display = '';
    renderCreatorRow('creator-beard', PLAYER_LOOK.beard, playerAppearance.beard, 'text');
  }
  renderPortraitTargets();
  renderCreatorIntegrityNote();
  renderSetupOnboardingGuide();
}

function buildIntro(){
  refreshShipSpecs();
  ensureShipSelectScreen();
  refreshSaveEntryActions();
  renderPlayModeSelector();
  document.getElementById('yearsel').innerHTML='';
  document.getElementById('shiptype').innerHTML='';
  // Yıl seçimi
  const ys=document.getElementById('yearsel');
  YEARS.forEach(y=>{
    const d=document.createElement('div');
    d.className='ysel'+(y.year===selYear?' active':'');
    d.innerHTML=`<div class="ys-yr">${y.year}</div><div class="ys-era">${y.era}</div>`;
    d.onclick=()=>{selYear=y.year;document.querySelectorAll('.ysel').forEach(x=>x.classList.remove('active'));d.classList.add('active');};
    ys.appendChild(d);
  });
  // Gemi türü
  const st=document.getElementById('shiptype');
  STYPES.forEach(t=>{
    const konts=KONTRAT_DEFS[t.key]||[];
    const kontStr=konts.map(k=>`${k.ay}+1`).join(' / ');
    const spec=getShipSpec(t.key);
    const locked=t.premium && !premiumUnlocked;
    const d=document.createElement('div');
    d.className='selb'+(t.key===selType?' active':'')+(locked?' locked':'')+(t.premium?' premium':'');
    d.innerHTML=`<span class="sb-ico">${locked?'🔒':t.ico}</span><span class="sb-nm">${t.nm}</span><span class="sb-kont">${spec.tonLabel}<br>${locked?'Premium Paket':kontStr+' ay'}</span>${t.premium?'<span class="premium-chip">PREMIUM</span>':''}`;
    d.onclick=()=>{
      if(locked){
        requirePremiumAccess('Bu ozel gemi ve pro operasyon paketleri premium pakete dahildir.');
        return;
      }
      selType=t.key;document.querySelectorAll('.selb').forEach(x=>x.classList.remove('active'));d.classList.add('active');updateKontrat();updateSugs();selectedVoyageRouteKey='';renderVoyageRouteSelector();renderShipChoiceSummary();
    };
    st.appendChild(d);
  });
  const p=document.createElement('div');
  p.className='premium-pack-card'+(premiumUnlocked?' active':'');
  p.innerHTML=`<b>${premiumUnlocked?'Premium Paket Aktif':`Premium Paket · ${PREMIUM_PRICE_LABEL}`}</b><span>${PREMIUM_PACKAGE_CATALOG.join(' · ')}</span><div class="premium-pack-actions"><button type="button" onclick="openPremiumPurchase()">${premiumUnlocked?'Aktif':`${PREMIUM_PRICE_LABEL} Satin Al`}</button><button type="button" onclick="openAdsRemovalPurchase()">${adsRemoved?'Reklamsiz Aktif':`${ADS_REMOVAL_PRICE_LABEL} Reklam Kaldir`}</button></div>`;
  st.appendChild(p);
  updateKontrat();
  updateSugs();
  renderVoyageRouteSelector();
  renderCharacterCreator();
  renderShipChoiceSummary();
  renderSetupOnboardingGuide();
  renderAudioMixer();
  applyLanguageUI();
  setIntroMenuPage(introMenuPage);
}

function ensureShipSelectScreen(){
  const intro = document.getElementById('intro');
  ensureSetupOnboardingGuide();
  if(intro && !document.getElementById('ship-choice-summary')){
    const summaryCard = document.createElement('div');
    summaryCard.className = 'fcard ship-choice-summary-card';
    summaryCard.innerHTML = `
      <div class="fcard-t">SEFER / GEMI SECIMI</div>
      <div id="ship-choice-summary" class="ship-choice-summary"></div>
      <button type="button" class="ship-choice-open" onclick="openShipSelectScreen()">Gemi, kontrat ve rota sec</button>`;
    const creatorCard = document.getElementById('creator-wrap')?.closest('.fcard');
    intro.insertBefore(summaryCard, creatorCard?.nextSibling || document.getElementById('go-btn'));
  }

  const goBtn = document.getElementById('go-btn');
  const shipCard = document.getElementById('shiptype')?.closest('.fcard');
  const contractCard = document.getElementById('kontratsel')?.closest('.fcard');
  const routeCard = document.getElementById('route-select-grid')?.closest('.fcard');
  const nameCard = document.getElementById('shipnameinp')?.closest('.fcard');
  [shipCard, contractCard, routeCard, nameCard].forEach(card=>{
    if(card && intro && card.parentElement !== intro){
      card.classList.add('ship-tab-card');
      intro.insertBefore(card, goBtn || null);
    }
  });
  [shipCard, contractCard, routeCard, nameCard].forEach(card=>card?.classList.add('ship-tab-card'));
  const inp = document.getElementById('shipnameinp');
  if(inp && !inp.dataset.summaryBound){
    inp.dataset.summaryBound = '1';
    inp.addEventListener('input', renderShipChoiceSummary);
  }
}

