// ===== RASTGELE SENARYO SIRASI =====
function buildSceneQueue(pool, totalDays, yr=selYear){
  const extraRouteScenes = getExtraRouteScenesForYear(yr);
  const extraEquipmentScenes = getExtraEquipmentScenesForYear(yr);
  const route = getActiveVoyageRoute();
  const voyageScenes = buildVoyageScenesForRoute(route, totalDays);
  const delayedInputSceneIds = new Set(Object.keys(DOCUMENT_FORM_CONFIGS));
  // Zorunlu sahneler: s01 (başlangıç), FINAL (son)
  const mandatory_start = pool.filter(s=>s.id==='s01');
  const final = pool.filter(s=>s.id==='FINAL');
  const crisis_scenes = pool.filter(s=>s.id.startsWith('kriz'));
  const regular = pool.filter(s=>!s.id.startsWith('kriz')&&s.id!=='s01'&&s.id!=='FINAL'&&!DOCUMENT_CHAIN_SCENE_IDS.has(s.id));
  const documentChain = ['s309','s310','s311','s312','s313','s314'].map(id=>pool.find(s=>s.id===id)).filter(Boolean);

  // Kriz sahnelerini grupla
  const crisisGroups=[
    ['kriz01','kriz02','kriz03'], // makine arızası
    ['kriz04','kriz05','kriz05b','kriz06'], // fırtına
    ['kriz07','kriz08','kriz09'], // boğaz
    ['kriz10','kriz11','kriz12'], // korsan
  ];

  // Rastgele 2-3 kriz grubu seç
  const shuffledGroups=[...crisisGroups].sort(()=>Math.random()-0.5);
  const selectedCrisisGroups=shuffledGroups.slice(0,Math.min(2+Math.floor(Math.random()*2),shuffledGroups.length));
  const selectedCrisis=[];
  selectedCrisisGroups.forEach(g=>{
    g.forEach(id=>{
      const sc=pool.find(s=>s.id===id);
      if(sc) selectedCrisis.push(sc);
    });
  });

  // Düzenli sahneleri karıştır ve totalDays - (başlangıç+kriz+final) kadar seç
  const shuffledRegular=[...regular].sort(()=>Math.random()-0.5);
  const needed=Math.max(5, totalDays - selectedCrisis.length - 2 - extraRouteScenes.length - extraEquipmentScenes.length - documentChain.length - voyageScenes.length);
  let selectedRegular=shuffledRegular.slice(0,needed);

  // Dinclik toparlanma sahneleri kuyrukta gercekten yer bulsun.
  const minRecoveryCount = Math.min(6, Math.max(3, Math.floor(totalDays/7)));
  const currentRecoveryCount = selectedRegular.filter(s=>RECOVERY_SCENE_IDS.has(s.id)).length;
  if(currentRecoveryCount < minRecoveryCount){
    const recoveryPool = shuffledRegular.filter(s=>RECOVERY_SCENE_IDS.has(s.id) && !selectedRegular.some(x=>x.id===s.id));
    const needMore = minRecoveryCount - currentRecoveryCount;
    const extras = recoveryPool.slice(0, needMore);
    if(extras.length){
      selectedRegular = [
        ...selectedRegular.filter(s=>!RECOVERY_SCENE_IDS.has(s.id)).slice(0, Math.max(0, selectedRegular.length - extras.length)),
        ...selectedRegular.filter(s=>RECOVERY_SCENE_IDS.has(s.id)),
        ...extras
      ];
    }
  }

  if(!selectedRegular.some(s=>LOW_ENERGY_RECOVERY_SCENE_IDS.has(s.id))){
    const lowEnergyPick = shuffledRegular.find(s=>LOW_ENERGY_RECOVERY_SCENE_IDS.has(s.id) && !selectedRegular.some(x=>x.id===s.id));
    if(lowEnergyPick){
      selectedRegular = [
        ...selectedRegular.slice(0, Math.max(0, selectedRegular.length-1)),
        lowEnergyPick,
        ...selectedRegular.slice(Math.max(0, selectedRegular.length-1))
      ];
    }
  }

  const premiumPrefixes = {
    proje:'proje',
    kruvaziyer:'cruise',
    arastirma:'research',
    offshore:'offshore',
    buz:'ice',
    cable:'cable',
    pipe:'pipe',
    shuttle:'shuttle',
    tanker:'premium_tanker',
    lng:'premium_tanker'
  };
  const premiumPrefix = premiumUnlocked ? (premiumPrefixes[selType] || '') : '';
  if(premiumPrefix){
    const premiumScenes = regular.filter(s=>String(s.id||'').startsWith(premiumPrefix) && !selectedRegular.some(x=>x.id===s.id));
    const guaranteed = premiumScenes.sort(()=>Math.random()-0.5).slice(0, Math.min(5, premiumScenes.length));
    if(guaranteed.length){
      selectedRegular = [
        ...guaranteed,
        ...selectedRegular.filter(s=>!String(s.id||'').startsWith(premiumPrefix))
      ];
    }
  }

  // Yazı yazmalı belge/form sahneleri oyunun başına çok yük bindirmesin.
  const regularInputScenes = selectedRegular.filter(s=>delayedInputSceneIds.has(s.id));
  const regularCoreScenes = selectedRegular.filter(s=>!delayedInputSceneIds.has(s.id));

  // Sıralamayı oluştur: başlangıç + önce daha akışkan sahneler + sonra belge/form sahneleri + kriz + final
  const coreMiddle=[...regularCoreScenes,...selectedCrisis].sort(()=>Math.random()-0.5);
  const lateInputScenes=[...regularInputScenes].sort(()=>Math.random()-0.5);
  const splitPoint = Math.max(6, Math.floor(coreMiddle.length*0.55));
  const middle=[...coreMiddle.slice(0,splitPoint), ...lateInputScenes, ...coreMiddle.slice(splitPoint)];
  const routeSpacing = Math.max(3, Math.floor(Math.max(1, middle.length) / Math.max(1, voyageScenes.length)));
  voyageScenes.forEach((sc,i)=>{
    const pos = Math.min(middle.length, 2 + i*routeSpacing);
    middle.splice(pos,0,sc);
  });
  const portChainIds = ['s361','s362','s363','s364','s241','s432'];
  const portChainScenes = portChainIds.map(id=>pool.find(s=>s.id===id)).filter(Boolean);
  const injectAt = Math.min(middle.length, Math.max(5, Math.floor(middle.length*0.58)));
  middle.splice(injectAt, 0, ...portChainScenes);

  return filterPremiumLockedScenes([...mandatory_start, ...middle, ...documentChain, ...extraRouteScenes, ...extraEquipmentScenes, ...final]);
}

