function createCinematicScene(key){
  const def = CINEMATIC_SCENES[key];
  if(!def) return null;
  const premiumKeys = new Set(['cruiseMedevac','researchRov']);
  const narrative = key === 'contractEnd' && typeof buildContractEndCinematicNarrative === 'function'
    ? buildContractEndCinematicNarrative()
    : def.text;
  return {
    ...def,
    text:narrative,
    cinematic:true,
    cinematicType:def.type || key,
    cinematicKey:key,
    premium:!!def.premium || premiumKeys.has(key),
    cinematicBeats:def.beats || [],
    cinematicDurationMs:def.durationMs || 10000,
    choices:[{
      text:def.choice || 'Devam et',
      tag:'kritik',
      domain:'bridge',
      effect:def.effect || {}
    }]
  };
}

function insertCinematicScene(queue, key, ratio, opts={}){
  const scene = createCinematicScene(key);
  if(!scene || !Array.isArray(queue) || queue.some(s=>s && s.id===scene.id)) return;
  const finalIdx = queue.findIndex(s=>s && s.id==='FINAL');
  const endLimit = finalIdx >= 0 ? finalIdx : queue.length;
  const minIndex = opts.afterStart ? Math.min(1, endLimit) : 0;
  const target = opts.beforeFinal ? endLimit : Math.round(endLimit * ratio);
  const pos = Math.max(minIndex, Math.min(endLimit, target));
  queue.splice(pos, 0, scene);
}

function injectCinematicScenes(queue, opts={}){
  if(!Array.isArray(queue) || !queue.length) return queue;
  const includeJoin = opts.includeJoin !== false;
  if(includeJoin) insertCinematicScene(queue, 'joinShip', 0.02, {afterStart:true});
  insertCinematicScene(queue, 'firstStorm', 0.18, {afterStart:true});
  insertCinematicScene(queue, 'portDeparture', 0.26, {afterStart:true});
  insertCinematicScene(queue, 'nightWatch', 0.30, {afterStart:true});
  insertCinematicScene(queue, 'pilotBoarding', 0.34, {afterStart:true});
  insertCinematicScene(queue, 'suezConvoy', 0.40, {afterStart:true});
  insertCinematicScene(queue, 'panamaLock', 0.46, {afterStart:true});
  insertCinematicScene(queue, 'allFast', 0.50, {afterStart:true});
  insertCinematicScene(queue, 'mooringSnapback', 0.54, {afterStart:true});
  if(/tanker|lng|shuttle/.test(selType || '')) insertCinematicScene(queue, 'tankerManifold', 0.58, {afterStart:true});
  insertCinematicScene(queue, 'engineBlackout', 0.60, {afterStart:true});
  insertCinematicScene(queue, 'piracyZone', 0.72, {afterStart:true});
  insertCinematicScene(queue, 'pscInspection', 0.80, {afterStart:true});
  if(premiumUnlocked && selType === 'kruvaziyer') insertCinematicScene(queue, 'cruiseMedevac', 0.86, {afterStart:true});
  if(premiumUnlocked && /research|arastirma|araştırma/.test(selType || '')) insertCinematicScene(queue, 'researchRov', 0.88, {afterStart:true});
  insertCinematicScene(queue, 'emergency', 0.68, {afterStart:true});
  insertCinematicScene(queue, 'contractEnd', 0.92, {beforeFinal:true});
  return queue;
}

const RECOVERY_SCENE_IDS = new Set(['s146','s147','s148','s149','s150','s183','s184','s185','s186','s187','s187b','s187c','s187d','s187e','s187f','s187g','s187h','s187i','s187j','s187k','s187l']);
const HARBOR_RECOVERY_SCENE_IDS = new Set(['s147','s150','s186','s187c','s187e','s187h','s187j']);
const LOW_ENERGY_RECOVERY_SCENE_IDS = new Set(['s187k','s187l']);

function maybePrioritizeRecoveryScene(){
  if(currentIdx >= sceneQueue.length-1) return;
  if(stats.dinclik > 62) return;
  const nextScene = sceneQueue[currentIdx];
  if(nextScene && RECOVERY_SCENE_IDS.has(nextScene.id)) return;

  if(stats.dinclik <= 10){
    let lowIdx = -1;
    for(let i=currentIdx+1; i<sceneQueue.length-1; i++){
      const sc = sceneQueue[i];
      if(sc && LOW_ENERGY_RECOVERY_SCENE_IDS.has(sc.id)){
        lowIdx = i;
        break;
      }
    }
    if(lowIdx > currentIdx){
      const [energyScene] = sceneQueue.splice(lowIdx,1);
      sceneQueue.splice(currentIdx,0,energyScene);
      return;
    }
  }

  const prevScene = currentIdx > 0 ? sceneQueue[currentIdx-1] : null;
  const prevBlob = `${prevScene?.id||''} ${prevScene?.gfx||''} ${prevScene?.loc||''} ${prevScene?.sub||''}`.toLowerCase();
  const afterCrisis = !!(prevScene && (prevScene.alert || prevScene.id?.startsWith('kriz') || /firtina|storm|acil|yangin|korsan|suruklenme|alarm/.test(prevBlob)));
  const harborWindow = !!(nextScene && /harbor|port_arrival/.test(nextScene.gfx||'')) || /liman|iskele|rihtim|romorkor|pilot station|mooring/.test(prevBlob);

  let foundIdx = -1;
  const nearSpan = afterCrisis ? (stats.dinclik <= 25 ? 9 : 7) : (harborWindow ? 11 : (stats.dinclik <= 25 ? 18 : 14));
  const nearLimit = Math.min(sceneQueue.length - 2, currentIdx + nearSpan);

  for(let i=currentIdx+1; i<=nearLimit; i++){
    const sc = sceneQueue[i];
    if(sc && RECOVERY_SCENE_IDS.has(sc.id) && (!harborWindow || HARBOR_RECOVERY_SCENE_IDS.has(sc.id))){
      foundIdx = i;
      break;
    }
  }

  if(foundIdx === -1){
    for(let i=nearLimit+1; i<sceneQueue.length-1; i++){
      const sc = sceneQueue[i];
      if(sc && RECOVERY_SCENE_IDS.has(sc.id) && (!harborWindow || HARBOR_RECOVERY_SCENE_IDS.has(sc.id))){
        foundIdx = i;
        break;
      }
    }
  }

  if(foundIdx > currentIdx){
    const [recoveryScene] = sceneQueue.splice(foundIdx, 1);
    sceneQueue.splice(currentIdx, 0, recoveryScene);
  }
}

// ===== SAHNE RENDER =====
function getSceneBackdropProfile(sc){
  if(!sc) return 'opensea';
  const hay = `${sc.gfx||''} ${sc.loc||''} ${sc.sub||''}`.toLowerCase();
  if(/storm|firtina|squall|beaufort|swell/.test(hay)) return 'storm';
  if(/bogaz|boğaz|çanakkale|canakkale|istanbul boğazı|istanbul bogazi|dar gecit|tss/.test(hay)) return 'strait';
  if(/harbor|liman|terminal|rihtim|rıhtım|berth|gangway|pilot station|ambarlı|rotterdam|singapur|panama|samsun|trabzon/.test(hay)) return 'harbor';
  if(/night|gece|00:|01:|02:|03:|04:/.test(hay)) return 'night';
  return 'opensea';
}

const REALISTIC_BG = {
  opensea:'assets/bg/opensea.png?v=1',
  harbor:'assets/bg/harbor.png?v=1',
  night:'assets/bg/night.png?v=1',
  strait:'assets/bg/strait.png?v=1',
  storm:'assets/bg/storm.png?v=1'
};

function getDynamicSceneTrafficOverlay(sc){
  const profile = getSceneBackdropProfile(sc);
  const hay = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const storm = profile === 'storm';
  const harbor = profile === 'harbor';
  const strait = profile === 'strait';
  const night = profile === 'night';
  const ships = [];
  const addShip = (type, x, y, s, dur, delay, dir='right') => {
    ships.push(`<span class="traffic-ship traffic-${type} ${dir}" style="--x:${x}%;--y:${y}%;--s:${s};--dur:${dur}s;--delay:${delay}s"><i></i><b></b><em></em></span>`);
  };
  if(storm){
    addShip('tanker', 13, 66, .52, 23, -6, 'right');
    addShip('bulk', 74, 61, .42, 29, -14, 'left');
  }else if(harbor){
    addShip('container', 14, 67, .72, 26, -4, 'right');
    addShip('tug', 48, 72, .46, 12, -2, 'right');
    addShip('pilot', 67, 64, .34, 10, -7, 'left');
    addShip('tanker', 78, 69, .58, 31, -16, 'left');
    if(/roro|ro-ro|ferry|yolcu|cruise|kruvaziyer/.test(hay)) addShip('roro', 30, 65, .54, 19, -9, 'right');
  }else if(strait){
    addShip('ferry', 10, 64, .5, 15, -4, 'right');
    addShip('tanker', 34, 61, .56, 26, -10, 'left');
    addShip('container', 65, 66, .58, 25, -16, 'right');
    addShip('pilot', 84, 71, .3, 9, -1, 'left');
  }else{
    addShip('lng', 12, 63, .52, 28, -9, 'right');
    addShip('container', 38, 69, .66, 31, -19, 'left');
    addShip('bulk', 68, 61, .48, 34, -13, 'right');
    if(night) addShip('cruise', 82, 67, .52, 25, -3, 'left');
  }
  if(/offshore|platform|dp|research|survey|rov|cable|pipe|premium/.test(hay)){
    addShip('support', 57, 70, .42, 16, -5, 'right');
  }
  if(/research|survey|rov|hydrographic|arastirma|araştırma/.test(hay)){
    addShip('research', 43, 62, .46, 21, -11, 'left');
  }
  if(/roro|ro-ro|vehicle carrier|car carrier|arac tasiyici|araç taşıyıcı/.test(hay)){
    addShip('roro', 72, 64, .54, 24, -13, 'right');
  }
  const lights = Array.from({length: harbor ? 11 : strait ? 7 : 4}, (_,i)=>{
    const x = 7 + i * (harbor ? 8 : 12);
    const y = harbor ? 54 + (i % 3) * 4 : 50 + (i % 2) * 5;
    return `<span class="traffic-light" style="--x:${x}%;--y:${y}%;--delay:${-i*.35}s"></span>`;
  }).join('');
  const rain = storm ? Array.from({length:18}, (_,i)=>`<span class="traffic-rain" style="--x:${(i*7)%100}%;--delay:${-i*.08}s"></span>`).join('') : '';
  const cranes = harbor ? Array.from({length:5}, (_,i)=>`<span class="traffic-crane" style="--x:${12+i*17}%;--h:${34+(i%2)*10}px;--delay:${-i*.5}s"><i></i></span>`).join('') : '';
  const lane = strait ? `<span class="traffic-lane lane-a"></span><span class="traffic-lane lane-b"></span>` : '';
  return `<div class="scene-parallax-layer profile-${profile}" aria-hidden="true">${lights}${cranes}${lane}${rain}${ships.join('')}</div>`;
}

function getSceneMotionClass(sc){
  const hay = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  if(sc?.alert || /alarm|yangin|yangın|fire|mob|abandon|blackout|pirate|korsan|near-miss|ariza|arıza|man overboard|snap-back|distress|mayday|dp alarm|esd/.test(hay)) return 'scene-motion-alert';
  if(/storm|firtina|fırtına|swell|rough|crosswind|squall|icing|ice|buz/.test(hay)) return 'scene-motion-storm';
  if(/bogaz|boğaz|canakkale|çanakkale|tss|dar kanal|dar gecit|sahil guvenlik|vhf|vts|mrcc/.test(hay)) return 'scene-motion-strait';
  if(/engine|makine|carkci|çarkçı|exhaust|lo pressure|bilge|pump|generator|blackout|compressor|thruster|dp |dynamic positioning/.test(hay)) return 'scene-motion-engine';
  if(/harbor|liman|berth|terminal|rihtim|rıhtım|pilot|tug|römorkör|romorkor|all fast|gangway|platform|fpso/.test(hay)) return 'scene-motion-harbor';
  if(/bridge|radar|ecdis|ais|chart room|kopruustu|köprüüstü|bogaz|tss|compass|survey|rov|cable|pipe/.test(hay)) return 'scene-motion-bridge';
  return '';
}

function computeLiveVoyageState(sc){
  const route = getActiveVoyageRoute();
  const wp = getVoyageWaypoint();
  const next = getVoyageWaypoint(Math.min((activeVoyageProgress || 0) + 1, (route?.waypoints?.length || 1) - 1));
  const {hour, minute} = parseSceneClock(sc || {});
  const sceneNo = Math.max(0, contractDays || currentIdx || 0);
  const pressure = Math.max(0, Number(voyagePressure?.caution || 0));
  const progress = getVoyageLegProgress();
  const etaMin = 35 + ((sceneNo * 11 + pressure * 7) % 220);
  const etaTotal = (hour * 60 + minute + etaMin) % 1440;
  const eta = `${String(Math.floor(etaTotal/60)).padStart(2,'0')}:${String(etaTotal%60).padStart(2,'0')}`;
  const cpaVal = Math.max(0.25, 2.6 - pressure * 0.17 - ((sceneNo % 5) * 0.11));
  const ukcVal = Math.max(0.7, 5.4 - pressure * 0.28 - (/ukc|squat|shallow|pilot|berth/i.test(`${sc?.sub||''} ${sc?.text||''}`) ? 1.1 : 0));
  const sogVal = Math.max(3.5, 14.2 - pressure * 0.42 - (voyagePressure.speed === 'Speed azalt' ? 3.0 : voyagePressure.speed === 'Dead slow hazir' ? 8.4 : 0));
  const cogVal = (42 + sceneNo * 17 + pressure * 5 + (activeVoyageProgress || 0) * 23) % 360;
  liveVoyageState = {
    route:route?.name || 'Rota yok',
    progress,
    eta,
    cpa:cpaVal.toFixed(1),
    tcpa:String(Math.max(4, Math.round(etaMin / 7))),
    ukc:ukcVal.toFixed(1),
    sog:sogVal.toFixed(1),
    cog:String(Math.round(cogVal)).padStart(3,'0'),
    nextWp:next?.name || wp?.name || '--',
    chart:next?.chart || wp?.chart || selectedPortChart,
    alert:cpaVal < 1.0 || ukcVal < 1.5 || pressure >= 7
  };
  return liveVoyageState;
}

function updateLiveVoyageState(sc){
  const st = computeLiveVoyageState(sc);
  const chip = document.getElementById('route-chip');
  if(chip){
    chip.className = `ops-chip ${st.alert ? 'warn' : st.progress >= 60 ? 'hot' : ''}`.trim();
    chip.textContent = `${st.progress}% · ETA ${st.eta} · CPA ${st.cpa} · UKC ${st.ukc}`;
  }
  return st;
}

function getSceneAmbientClass(sc){
  const profile = getSceneBackdropProfile(sc);
  if(profile === 'storm') return 'scene-ambient-storm';
  if(profile === 'strait') return 'scene-ambient-strait';
  if(profile === 'harbor') return 'scene-ambient-harbor';
  if(profile === 'night') return 'scene-ambient-night';
  return 'scene-ambient-sea';
}

