function getSceneFlavorClasses(sc){
  const hay = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const classes = ['scene-real-grain','scene-cinematic'];
  if(/radar|ais|ecdis|arpa|bridge|kopruustu|köprüüstü/.test(hay)) classes.push('scene-live-nav','scene-glass-reflection','scene-modern-bridge');
  if(/galley|asci|cay|kahve|coffee/.test(hay)) classes.push('scene-human-cup');
  if(/engine|makine|rag|bez|oil|yagci|compressor/.test(hay)) classes.push('scene-human-rag');
  if(/deck|guverte|wet deck|rain stop|mooring|halat/.test(hay)) classes.push('scene-human-wetdeck');
  if(/harbor|terminal|liman|rihtim|rıhtım/.test(hay)) classes.push('scene-human-sodium','scene-light-bloom','scene-port-depth');
  if(/storm|firtina|salt|spray|swell|rain|yagmur|yağmur/.test(hay)) classes.push('scene-human-salt','scene-weather-heavy');
  if(/fog|mist|sis|restricted visibility|gorus kisitli|görüş kısıtlı/.test(hay)) classes.push('scene-fog-bank');
  if(/engine|makine|exhaust|egzoz|generator|compressor|pump/.test(hay)) classes.push('scene-engine-heat');
  if(/sea|acik deniz|açık deniz|open sea|offshore|sailing|seyir/.test(hay)) classes.push('scene-wake-layer');
  if(/bridge|kopruustu|köprüüstü|radar|ecdis|ais|arpa/.test(hay)) classes.push('scene-location-bridge');
  if(/engine|makine|control room|pump|compressor|generator/.test(hay)) classes.push('scene-location-engine');
  if(/deck|guverte|mooring|halat|lashing|manifold/.test(hay)) classes.push('scene-location-deck');
  if(/galley|asci|aşçı|yemekhane|cay|çay|coffee/.test(hay)) classes.push('scene-location-galley');
  if(/cabin|kamara|uyku|yalnizlik|yalnızlık/.test(hay)) classes.push('scene-location-cabin');
  return classes;
}

function getSceneTransitionClass(prevSc, sc){
  const prevProfile = getSceneBackdropProfile(prevSc);
  const nextProfile = getSceneBackdropProfile(sc);
  if(prevProfile === nextProfile) return '';
  if(prevProfile === 'night' && nextProfile === 'opensea') return 'scene-transition-dawn';
  if(prevProfile === 'harbor' && nextProfile === 'opensea') return 'scene-transition-offshore';
  if(/engine|makine/.test(`${sc?.gfx||''} ${sc?.loc||''}`.toLowerCase())) return 'scene-transition-enginebay';
  return 'scene-transition-generic';
}

function getSceneActorMode(sc){
  const hay = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  if(/storm|firtina|swell|rough|crosswind|squall/.test(hay)) return 'storm';
  if(/bogaz|boğaz|canakkale|çanakkale|tss|dar kanal|dar gecit|vhf/.test(hay)) return 'strait';
  if(/engine|makine|carkci|exhaust|lo pressure|bilge|pump|generator|blackout/.test(hay)) return 'engine';
  if(/harbor|liman|berth|terminal|rihtim|pilot|tug|all fast|gangway/.test(hay)) return 'harbor';
  if(/radar|ecdis|ais|arpa|gmdss|bnwas|gyro|compass|chart room|kopruustu/.test(hay)) return 'console';
  return 'bridge';
}

function renderSceneActor(sc, actorCfg){
  const actor = document.getElementById('gfx-actor');
  if(!actor) return;
  if(actorCfg === null){
    actor.classList.add('empty');
    actor.innerHTML = '';
    actor.removeAttribute('data-mode');
    return;
  }
  const cfg = actorCfg || getPlayerPortraitConfig();
  if(!cfg){
    actor.classList.add('empty');
    actor.innerHTML = '';
    actor.removeAttribute('data-mode');
    return;
  }
  actor.classList.remove('empty');
  actor.dataset.mode = getSceneActorMode(sc);
  actor.innerHTML = renderPortraitSprite(cfg, 'actor');
}

function triggerLiveScenePresentation(sc, choicesWrap){
  const sceneArea = document.getElementById('scene-area');
  const story = document.getElementById('story');
  if(sceneArea){
    sceneArea.classList.remove('scene-motion-bridge','scene-motion-engine','scene-motion-harbor','scene-motion-storm','scene-motion-strait','scene-motion-alert','scene-ambient-sea','scene-ambient-night','scene-ambient-harbor','scene-ambient-storm','scene-ambient-strait','scene-fade-once','scene-detail-radar','scene-detail-engine','scene-detail-harbor','scene-detail-deck','scene-detail-stormglass','scene-transition-dawn','scene-transition-offshore','scene-transition-enginebay','scene-transition-generic','scene-live-nav','scene-human-cup','scene-human-rag','scene-human-wetdeck','scene-human-sodium','scene-human-salt','scene-real-grain','scene-glass-reflection','scene-modern-bridge','scene-weather-heavy','scene-light-bloom','scene-fog-bank','scene-port-depth','scene-engine-heat','scene-wake-layer','scene-cinematic','scene-location-bridge','scene-location-engine','scene-location-deck','scene-location-galley','scene-location-cabin');
    Array.from(sceneArea.classList).filter(cls=>cls.startsWith('scene-cinematic-')).forEach(cls=>sceneArea.classList.remove(cls));
    void sceneArea.offsetWidth;
    sceneArea.classList.add('scene-fade-once');
    const motionClass = getSceneMotionClass(sc);
    if(motionClass) sceneArea.classList.add(motionClass);
    sceneArea.classList.add(getSceneAmbientClass(sc));
    const detailClass = getSceneDetailClass(sc);
    if(detailClass) sceneArea.classList.add(detailClass);
    getSceneFlavorClasses(sc).forEach(cls=>sceneArea.classList.add(cls));
    if(sc?.cinematic){
      sceneArea.classList.add('scene-cinematic', `scene-cinematic-${sc.cinematicType || sc.cinematicKey || 'scene'}`);
    }
  }
  if(story){
    story.classList.remove('story-live');
    void story.offsetWidth;
    story.classList.add('story-live');
  }
  if(choicesWrap){
    Array.from(choicesWrap.querySelectorAll('.cbtn')).forEach((btn, idx)=>{
      btn.classList.remove('scene-choice-enter');
      btn.style.animationDelay = `${Math.min(idx * 0.06, 0.24)}s`;
      void btn.offsetWidth;
      btn.classList.add('scene-choice-enter');
    });
  }
}

