function getOneShotSceneFx(sc){
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  if(sc?.id === 's124b' || /sling kopuyor|halat\/sling kopuyor|rope|snap-back/.test(blob)) return 'oneshot-rope-snap';
  if(sc?.id === 's237' || /mob|man overboard/.test(blob)) return 'oneshot-mob-flash';
  if(sc?.id === 's238' || sc?.id === 's251' || sc?.id === 's252' || /fire alarm|yangin|fire locker|galley girisi/.test(blob)) return 'oneshot-fire-pulse';
  if(sc?.gfx === 'storm' || /beaufort|firtina|storm|swell mendirek|sert hava/.test(blob)) return 'oneshot-storm-hit';
  if(sc?.gfx === 'engine_fault' || /blackout|lo pressure|egzoz sicakligi|bilge high level|yuk paylasimi/.test(blob)) return 'oneshot-engine-hit';
  if(sc?.id === 'kriz07' || sc?.id === 'kriz08' || sc?.id === 'kriz17' || sc?.id === 'kriz22' || /vhf|dsc alert|distress|sahil guvenlik|secu?rite|mayday|pan-pan/.test(blob)) return 'oneshot-vhf-burst';
  if(/radar|ecdis_panel|ais_panel|radar konsolu|ecdis|enc update|route check|arpa/.test(blob)) return 'oneshot-sensor-glow';
  return '';
}

let oneShotFxTimers = [];
function clearOneShotSceneFxClasses(doReflow=true){
  const sceneArea = document.getElementById('scene-area');
  const sceneGraphic = document.getElementById('scene-graphic');
  const gfxSvg = document.getElementById('gfx-svg');
  if(sceneArea){
    sceneArea.classList.remove('oneshot-mob-flash','oneshot-rope-snap','oneshot-fire-pulse','oneshot-storm-hit','oneshot-engine-hit','oneshot-vhf-burst','oneshot-sensor-glow');
    if(doReflow) void sceneArea.offsetWidth;
  }
  if(sceneGraphic){
    sceneGraphic.classList.remove('oneshot-rope-snap','oneshot-fire-pulse','oneshot-storm-hit','oneshot-engine-hit','oneshot-vhf-burst','oneshot-sensor-glow');
  }
  if(gfxSvg){
    gfxSvg.classList.remove('oneshot-sensor-glow');
  }
}

function clearOneShotSceneFx(){
  oneShotFxTimers.forEach(t=>clearTimeout(t));
  oneShotFxTimers = [];
  clearOneShotSceneFxClasses(true);
}

function applyOneShotSceneFx(fx, hold=950, keepSchedule=false){
  const sceneArea = document.getElementById('scene-area');
  const sceneGraphic = document.getElementById('scene-graphic');
  const gfxSvg = document.getElementById('gfx-svg');
  if(!fx) return;
  if(keepSchedule) clearOneShotSceneFxClasses(true);
  else clearOneShotSceneFx();
  if(sceneArea) sceneArea.classList.add(fx);
  if(sceneGraphic && /rope-snap|fire-pulse|storm-hit|engine-hit|vhf-burst|sensor-glow/.test(fx)) sceneGraphic.classList.add(fx);
  if(gfxSvg && fx === 'oneshot-sensor-glow') gfxSvg.classList.add(fx);
  vibrateDanger(fx, keepSchedule ? 1900 : 650);
  const cleaner = setTimeout(()=>{
    if(sceneArea) sceneArea.classList.remove(fx);
    if(sceneGraphic) sceneGraphic.classList.remove(fx);
    if(gfxSvg) gfxSvg.classList.remove(fx);
  }, hold);
  oneShotFxTimers.push(cleaner);
}

function triggerOneShotSceneFx(sc){
  applyOneShotSceneFx(getOneShotSceneFx(sc));
}

function scheduleSyncedSceneFx(sc){
  const fx = getOneShotSceneFx(sc);
  if(!fx){
    clearOneShotSceneFx();
    return;
  }
  const pulse = (delay, hold=950, repeatGap=0) => {
    const kickoff = ()=>{
      applyOneShotSceneFx(fx, hold, repeatGap > 0);
      if(repeatGap > 0){
        const looper = setInterval(()=>applyOneShotSceneFx(fx, hold, true), repeatGap);
        oneShotFxTimers.push(looper);
      }
    };
    const timer = setTimeout(kickoff, delay);
    oneShotFxTimers.push(timer);
  };
  clearOneShotSceneFx();
  if(fx === 'oneshot-rope-snap'){
    pulse(85, 520);
    pulse(245, 340);
    return;
  }
  if(fx === 'oneshot-fire-pulse'){
    pulse(90, 620);
    pulse(430, 520);
    return;
  }
  if(fx === 'oneshot-sensor-glow'){
    pulse(65, 880);
    return;
  }
  if(fx === 'oneshot-storm-hit'){
    pulse(120, 620, 2200);
    return;
  }
  if(fx === 'oneshot-engine-hit'){
    pulse(95, 560, 1650);
    return;
  }
  if(fx === 'oneshot-vhf-burst'){
    pulse(45, 360, 1900);
    return;
  }
  if(fx === 'oneshot-mob-flash'){
    pulse(55, 560);
    return;
  }
  pulse(0, 950);
}

function renderScene(idx){
  toggleMoreTools(false);
  if(idx>='end'||currentIdx>=sceneQueue.length){showEnd();return;}
  maybePrioritizeRecoveryScene();
  enforcePremiumAccessGuards('render_scene');
  const sc=sceneQueue[currentIdx];
  const prevSc = currentIdx>0 ? sceneQueue[currentIdx-1] : null;
  if(!sc){showEnd();return;}
  const delayedCrisis=resolveDelayedConsequences(sc);
  if(delayedCrisis){showCrisis(delayedCrisis);return;}
  if(sc.id==='FINAL'&&currentIdx<sceneQueue.length-1){
    // Henüz son değilse atla, yoksa göster
  }

  const c=getCrewDisplay(sc.who);
  document.getElementById('dbd').textContent=translateGameText(sc.day);
  document.getElementById('tbd').textContent=sc.time;
  document.getElementById('lbd').textContent=getLocalizedSceneLocation(sc);
  updateWatchState(sc);
  updateVoyagePressure(sc);
  updateLiveVoyageState(sc);
  updatePortOpsChain(sc);
  document.getElementById('scene-sub').textContent=gameLanguage==='tr' ? personalizeSceneSpeakerText(sc.sub || '', sc) : getLocalizedScenarioCue(sc, getSceneLanguageKind(sc, sc.text || ''));
  const speakerPortraitCfg = getSceneSpeakerPortrait(sc);
  document.getElementById('spkico').innerHTML = renderPortraitSprite(speakerPortraitCfg, 'speaker');
  renderSpeechPortrait(speakerPortraitCfg);
  document.getElementById('spknm').textContent=getLocalizedSpeakerName(c);
  const memoryLine = getCrewMemoryLine(sc);
  document.getElementById('spktl').textContent = [translateGameText(c.title), gameLanguage==='tr' ? translateGameText(memoryLine) : ''].filter(Boolean).join(' · ');
  hideReplyBubble();
  runSpeechTyping(typeof sc.text==='function'?sc.text(pn,sn):sc.text, sc);
  renderDialogueLog();
  applySceneEmotions(sc);
  document.getElementById('charname').textContent=pn;
  document.getElementById('charrole').textContent=t('role.cadet','GÜV. STAJYERİ')+' · '+translateGameText(sc.day).toUpperCase();
  renderPortraitTargets();
  const stObj=STYPES.find(x=>x.key===selType);
  const shipSpec=getShipSpec(selType);
  document.getElementById('shipinfo').textContent=sn+' · '+(shipSpec.tonLabel||stObj.ton)+' · '+stObj.nm+' · '+selYear+' · '+watchState.code;
  document.getElementById('contract-type').textContent=translateGameText(stObj.nm)+' '+getContractTotalMonths()+' ay · '+contractTotal+' '+translateGameText('sahne');
  updateOpsHud(sc);
  updateFeatureVisibility(sc);
  updateGuidanceStrip(sc);
  updateMissionDirector(sc);
  renderSavePanel();
  updateLivingWatch(sc);
  if(document.getElementById('sim-panel')?.classList.contains('show')) renderSimCenter();
  renderPhone();

  const pct=Math.round((currentIdx/sceneQueue.length)*100);
  document.getElementById('progbar').style.width=pct+'%';
  document.getElementById('chaplbl').textContent=translateGameText('SAHNE')+' '+(currentIdx+1)+'/'+sceneQueue.length;

  const ab=document.getElementById('alert-banner');
  if(sc.alert){ab.style.display='block';ab.textContent='⚠ '+translateGameText('ACİL DURUM')+' — '+translateGameText(sc.sub);ab.style.color='#ffcccc';}
  else ab.style.display='none';

  const svg=document.getElementById('gfx-svg');
  const photo=document.getElementById('gfx-photo');
  const parallax=document.getElementById('gfx-parallax');
  const foreground=document.getElementById('gfx-foreground');
  const bridge3d=document.getElementById('gfx-3d');
  window.__bgBackdropProfile = getSceneBackdropProfile(sc);
  window.__bgSceneId = sc?.id || String(currentIdx);
  if(photo){
    const profile = window.__bgBackdropProfile || 'opensea';
    photo.style.backgroundImage = `url('${REALISTIC_BG[profile] || REALISTIC_BG.opensea}')`;
    photo.style.opacity = profile==='storm' ? '.5' : profile==='night' ? '.36' : profile==='harbor' ? '.46' : '.42';
  }
  if(parallax){
    parallax.innerHTML = isPerformanceModeActive() ? '' : getDynamicSceneTrafficOverlay(sc);
  }
  if(bridge3d){
    const bridge3dMarkup = getScene3DBridgeOverlay(sc);
    const renderHeavy3d = !!bridge3dMarkup && !isPerformanceModeActive();
    bridge3d.innerHTML = bridge3dMarkup ? `${renderHeavy3d ? '<canvas class="three-bridge-canvas"></canvas>' : ''}${bridge3dMarkup}` : '';
    bridge3d.classList.toggle('active', !!bridge3dMarkup);
    bridge3d.classList.toggle('lite', !!bridge3dMarkup && !renderHeavy3d);
    if(renderHeavy3d) renderThreeBridgeScene(sc);
    else stopThreeBridgeScene();
  }
  if(foreground) foreground.innerHTML = getLiveSceneOverlay(sc);
  svg.innerHTML=getSafeSceneMarkup(sc);
  renderSceneActor(sc, null);
  renderMainSceneControlOverlay(sc);

  playSceneAudio(sc);
  updateSceneNoteHints(sc);
  onSceneRender(sc);
  scheduleSyncedSceneFx(sc);

  const ch=document.getElementById('choices');ch.innerHTML='';
  ch.classList.remove('cinematic-controls');
  renderCalcPanel(sc, ch);
  const hasTacticalPanel = renderTacticalPanel(sc, ch);
  const hasInspectionPanel = renderInspectionPanel(sc, ch);
  const hasInteractionPanel = renderInteractionPanel(sc, ch);
  const hasDocPanel = renderDocumentPanel(sc, ch);
  const hasStowagePanel = renderStowagePanel(sc, ch);
  const hasMooringPanel = renderMooringPanel(sc, ch);
  const hasEmergencyPanel = renderEmergencyPanel(sc, ch);
  getSceneRenderChoices(sc).forEach(c2=>{
    const b=document.createElement('button');b.className='cbtn';
    if(stats.dinclik <= 35 && !['kritik','akilli'].includes(c2.tag||'')) b.classList.add('fatigue-decoy');
    b.innerHTML='<span class="ctag tag-'+(c2.tag||'akilli')+'">'+phoneSafe(getChoiceTagLabel(c2.tag||'akilli'))+'</span>'+phoneSafe(localizeChoiceText(c2));
    b.onclick=()=>handleSceneChoice(sc,c2,ch);
    ch.appendChild(b);
  });
  const cinematicFlowActive = setupCinematicSceneFlow(sc, ch);
  if(cinematicFlowActive){
    ch.style.display='';
  }else if(sc.calc || hasTacticalPanel || hasInspectionPanel || hasInteractionPanel || hasDocPanel || hasStowagePanel || hasMooringPanel || hasEmergencyPanel){
    ch.style.display='none';
  }else{
    ch.style.display='';
  }
  triggerLiveScenePresentation(sc, ch);
  normalizeClickableSurface('#choices button,#toolbar button,#guidance-strip button');
  const sceneArea=document.getElementById('scene-area');
  if(sceneArea){
    const transitionClass = getSceneTransitionClass(prevSc, sc);
    if(transitionClass) sceneArea.classList.add(transitionClass);
  }
  startSceneChoiceTimer(sc, ch);
  applyLanguageUI();
  saveGameState(false);
}

// ===== KRİZ =====
function showCrisis(key){
  clearSceneChoiceTimer();
  stopAllMusic();sfxFail();
  vibrateDanger('crisis', 300);
  document.getElementById('game').style.display='none';
  const cs=document.getElementById('crisis');cs.style.display='flex';
  const c=CRISIS_ENDS[key];
  if(!c){showEnd();return;}
  document.getElementById('crise').textContent=c.emoji;
  document.getElementById('crist').textContent=c.title;
  document.getElementById('crisx').textContent=typeof c.text==='function'?c.text(pn,sn):c.text;
  document.getElementById('criss').textContent=c.stat;
}

// ===== SON =====
function getCareerSpecialization(){
  const scores={seyir:0,yuk:0,emniyet:0,insanyonetimi:0,tanker:0};
  choicesMade.forEach(c=>{
    if(c.domain==='bridge') scores.seyir += c.tag==='kritik'?3:c.tag==='akilli'?2:1;
    if(c.domain==='deck') scores.yuk += c.tag==='kritik'?3:c.tag==='akilli'?2:1;
    if(c.domain==='engine') scores.tanker += c.tag==='kritik'?2:c.tag==='akilli'?1:0;
    if(c.domain==='compliance') scores.emniyet += c.tag==='kritik'?3:c.tag==='akilli'?2:1;
    if(c.tag==='sosyal' || c.tag==='kritik') scores.insanyonetimi += /sosyal|kritik/.test(c.tag)?2:1;
  });
  if(playerFlags.securityBreach===0) scores.emniyet += 4;
  if(careerMemory.investigations>0) scores.insanyonetimi += 2;
  if(playerFlags.nearMiss===0) scores.yuk += 2;
  if(playerFlags.sextantGood>0) scores.seyir += 3;
  if(psyche.uyum>=70) scores.insanyonetimi += 4;
  if(psyche.moral>=70) scores.insanyonetimi += 2;
  if(/tanker|lng/.test(selType)) scores.tanker += 3;
  const ranked=Object.entries(scores).sort((a,b)=>b[1]-a[1]);
  const labels={
    seyir:'Seyirci',
    yuk:'Yuk Operasyoncusu',
    emniyet:'Emniyet Disiplini Guclu',
    insanyonetimi:'Insan Yonetimi Guclu',
    tanker:'Tanker / Teknik Disiplin Guclu'
  };
  return {top:labels[ranked[0][0]], second:labels[ranked[1][0]], raw:scores};
}

function getRankName(){
  return CAREER_RANKS[Math.max(0, Math.min(CAREER_RANKS.length-1, careerState.rankIndex||0))];
}

function updateSpecialtyFromContract(){
  const domains = choicesMade.map(c=>c.domain || '');
  domains.forEach(d=>{
    if(/bridge|seyir|radar|ecdis|colreg/.test(d)) specialtyXP.navigation += 1;
    if(/deck|yuk|cargo|lashing|stowage/.test(d)) specialtyXP.container += selType==='kont' ? 2 : 1;
    if(/engine|tanker|lng|manifold|cargo/.test(d)){
      if(selType==='lng') specialtyXP.lng += 2;
      else specialtyXP.tanker += 1;
    }
    if(/compliance|emniyet|fire|mob|permit|psc/.test(d)) specialtyXP.safety += 1;
    if(/crew|murettebat|psikoloji|conflict/.test(d)) specialtyXP.people += 1;
  });
  if(selType==='bulk') specialtyXP.bulk += 3;
  if(selType==='roro') specialtyXP.roro += 3;
}

function calculatePromotionReport(){
  const avg = (stats.cesaret+stats.bilgi+stats.sayginlik)/3;
  const rank = careerState.rankIndex || 0;
  const required = [52,58,66,74,999][rank] || 999;
  const eligible = avg >= required && stats.sayginlik >= 45 && careerState.companyOpinion >= 38 && playerFlags.securityBreach < 3;
  const nextRank = CAREER_RANKS[Math.min(CAREER_RANKS.length-1, rank+1)];
  return {eligible, avg:Math.round(avg), required, nextRank};
}

function buildContractEndReport(){
  const promo = calculatePromotionReport();
  const route = getActiveVoyageRoute ? getActiveVoyageRoute() : null;
  const bondScore = typeof getPlayerBondScore === 'function' ? getPlayerBondScore() : 0;
  const strongArea = typeof getTopSpecialtyLabel === 'function' ? getTopSpecialtyLabel() : getCareerSpecialization().top;
  const weakChoices = choicesMade.filter(c=>c.tag === 'korkak' || c.tag === 'hileli' || c.tag === 'itaatkar').length;
  const strongChoices = choicesMade.filter(c=>c.tag === 'kritik' || c.tag === 'akilli').length;
  const trustAvg = Math.round(Object.values(crewTrust || {}).reduce((a,b)=>a+b,0) / Math.max(1,Object.values(crewTrust || {}).length));
  const moneyDue = Math.round((careerState.salary || 1200) * Math.max(1, getContractTotalMonths()));
  const offerPreview = (shipOffers.length ? shipOffers : buildShipOffers()).slice(0,3).map(o=>o.label).join(' / ');
  const captainTone = promo.eligible
    ? `${promo.nextRank} icin dosyan guclu. Yine de cihaz ve logbook disiplinini birakma.`
    : weakChoices > strongChoices / 2
      ? 'Gelistirme alani net: hata zincirini erken kes, raporu geciktirme, tekrar pratiklerini kapat.'
      : 'Kontrat kabul edilebilir. Bir sonraki gemide daha net sorumluluk alman bekleniyor.';
  const familyLine = stats.dinclik < 35
    ? 'Aile: Sesin yorgun geliyor, limanda kendine zaman ayir.'
    : 'Aile: Donus tarihini bekliyoruz, bir fotograf daha atmayi unutma.';
  return {
    contract:careerState.contracts + (careerState.lastContractClosed ? 0 : 1),
    route:route?.name || 'Aktif rota',
    ship:sn,
    rank:getRankName(),
    strongArea,
    weakChoices,
    strongChoices,
    trustAvg,
    bondScore,
    moneyDue,
    offerPreview,
    captainTone,
    familyLine,
    photos:photos.length,
    routeProgress:getVoyageLegProgress ? getVoyageLegProgress() : 0,
    ts:Date.now()
  };
}

function ensureContractEndReport(reason='manual'){
  const contractNo = careerState.contracts + (careerState.lastContractClosed ? 0 : 1);
  if(contractReportState.lastContract === contractNo && contractReportState.reports?.length) return contractReportState.reports[0];
  const report = buildContractEndReport();
  report.reason = reason;
  contractReportState.lastContract = contractNo;
  contractReportState.reports = [report, ...(contractReportState.reports || [])].slice(0,6);
  return report;
}

function buildContractEndCinematicNarrative(){
  const report = buildContractEndReport();
  return `Telefon albumunde ${report.photos} hatira karti birikti. ${report.ship} uzerindeki bu kontrat sadece sahne sayisi degil; rota, ekip, aile ve yaptigin kararlarin izi.

Kaptan dosyayi kapatmadan once son yorumu yaziyor:
"${report.captainTone}"

Sirket teklifleri hazir: ${report.offerPreview || 'ayni gemide devam'}.
Guclu alanin: ${report.strongArea}. Ekip guveni: ${report.trustAvg}/100. Rota ilerleyisi: %${report.routeProgress}.

Simdi rapor ekrani acilacak: kaptan yorumu, aile mesaji, album, maas ve yeni rota/gemi secimi ayni akista gorunecek.`;
}

function getContractCinematicReportPanel(){
  const report = (contractReportState.reports || [])[0] || buildContractEndReport();
  return `<div class="contract-cinematic-report">
    <div class="contract-report-hero">
      <div><b>KONTRAT SONU SINEMATIK RAPOR</b><small>${phoneSafe(report.ship)} · ${phoneSafe(report.route)} · ${phoneSafe(report.rank)}</small></div>
      <span>${phoneSafe(String(report.bondScore))}/100</span>
    </div>
    <div class="contract-report-grid">
      <div><b>Kaptan yorumu</b><small>${phoneSafe(report.captainTone)}</small></div>
      <div><b>Guclu alan</b><small>${phoneSafe(report.strongArea)}</small></div>
      <div><b>Ekip guveni</b><small>${phoneSafe(String(report.trustAvg))}/100</small></div>
      <div><b>Album</b><small>${phoneSafe(String(report.photos))} hatira karti</small></div>
      <div><b>Maas / bakiye</b><small>$${phoneSafe(String(report.moneyDue))} kontrat tahmini · bakiye $${phoneSafe(String(careerState.money || 0))}</small></div>
      <div><b>Sirket teklifi</b><small>${phoneSafe(report.offerPreview || 'Ayni gemide devam / yeni rota')}</small></div>
    </div>
    <div class="contract-report-family">${phoneSafe(report.familyLine)}</div>
    <div class="sim-actions compact">
      <button onclick="openAlbum()">Albumu ac</button>
      <button onclick="openCareer()">Gemi teklifleri</button>
      <button onclick="buildPassageDebrief(); renderSimCenter()">Passage debrief</button>
    </div>
  </div>`;
}

function closeContractCareerBooks(){
  if(careerState.lastContractClosed) return;
  updateSpecialtyFromContract();
  careerState.contracts += 1;
  careerState.seaMonths += getContractTotalMonths();
  careerState.leaveDays += Math.max(5, Math.round(getContractTotalMonths()*3));
  const paidMonths = careerState.paidMonths || 0;
  careerState.money += Math.round((careerState.salary || 1200) * Math.max(0, getContractTotalMonths() - paidMonths));
  careerState.paidMonths = 0;
  careerState.companyOpinion = clamp((careerState.companyOpinion || 50) + Math.round((stats.sayginlik-50)/8) + (playerFlags.nearMiss ? -4 : 3) + (playerFlags.securityBreach ? -5 : 2));
  const promo = calculatePromotionReport();
  if(promo.eligible && careerState.rankIndex < CAREER_RANKS.length-1){
    careerState.rankIndex += 1;
    careerState.salary = Math.round((careerState.salary || 1200) * 1.32);
    careerState.referenceLetters.push(`${selYear} ${sn}: ${promo.nextRank} terfi referansi`);
    pushPhoneMessage('Şirket','Kontrat raporun olumlu. Terfi dosyan acildi: '+promo.nextRank+'.', {open:false});
  }else{
    careerState.referenceLetters.push(`${selYear} ${sn}: kontrat performans mektubu`);
    pushPhoneMessage('Şirket','Kontrat performans raporun dosyalandi. Bir sonraki teklif icin disiplinli kapanis bekliyoruz.', {open:false});
  }
  pushFamilyGroupMessage('Anne','Kontrat bitiyorsa ne zaman doneceksin? Evde herkes tarih soruyor.');
  pushPhoneMessage('Crew Chat','Lostromo: Gemide kalirsan yine forward stationda gorusuruz. Inersen yolun acik olsun.', {open:false});
  tryAddMomentPhoto(`contract-${careerState.contracts+1}-memory`,'Kontrat Hatirasi',`${sn} uzerinde ${getContractTotalMonths()} ayin ozeti: ${getTopSpecialtyLabel()}, ${choicesMade.length} karar, ${photos.length} hatira.`, 'bridge');
  phonePhotoShares.unshift({title:'Kontrat Sonu Albumu', caption:`${getContractTotalMonths()} ay · ${photos.length} fotograf · ${getTopSpecialtyLabel()} · aile/crew mesajlari kaydedildi.`, gfx:'bridge', scene:currentIdx+1, sent:false});
  addCompanyMailThread('Kontrat kapanis raporu', `Guclu alan: ${getTopSpecialtyLabel()}. Zayif alanlar, cihaz tekrar gorevleri ve aile/crew moral etkisi kontrat dosyasina eklendi.`, 'info');
  const boardScore = recordLeaderboardScore('contract');
  awardMetaXp(260, `Kontrat kapandi · skor ${boardScore}`, 'contract');
  progressRetentionMission('contract', {shipType:selType, score:boardScore});
  careerState.lastContractClosed = true;
  shipOffers = buildShipOffers();
  ensureContractEndReport('contract_close');
}

function buildShipOffers(){
  const basePay = careerState.salary || 1200;
  const offers = [
    {key:'same', label:'Ayni Gemide Kal', type:selType, ship:sn, pay:basePay, note:'Ekip hafizasi aynen korunur.'},
    {key:'container', label:'Konteyner Teklifi', type:'kont', ship:'M/V Atlas Express', pay:Math.round(basePay*1.08), note:'Bay-row-tier, reefer ve lashing agir basar.'},
    {key:'tanker', label:'Tanker Teklifi', type:'tanker', ship:'M/T Marmara Star', pay:Math.round(basePay*1.18), note:'Manifold, ESD, inert gas ve cargo watch agirlasir.'},
    {key:'lng', label:'LNG Teklifi', type:'lng', ship:'LNG Anatolia', pay:Math.round(basePay*1.28), note:'Reliquefaction, gas freeing ve compressor disiplini.'}
  ];
  if(premiumUnlocked){
    offers.push(
      {key:'project', label:'Proje Gemisi Teklifi', type:'proje', ship:'M/V Atlas Heavy Lift', pay:Math.round(basePay*1.34), note:'Heavy lift, sea fastening ve COG disiplini.'},
      {key:'cruise', label:'Kruvaziyer Teklifi', type:'kruvaziyer', ship:'M/V Ege Dream', pay:Math.round(basePay*1.26), note:'Passenger safety, hotel load ve crowd management.'},
      {key:'research', label:'Araştırma Gemisi Teklifi', type:'arastirma', ship:'R/V Piri Reis', pay:Math.round(basePay*1.30), note:'Survey line, ROV, DP ve bilim ekibi koordinasyonu.'},
      {key:'offshore', label:'Offshore Support Teklifi', type:'offshore', ship:'AHTS Kaptan Bora', pay:Math.round(basePay*1.32), note:'Platform approach, DP ve anchor handling.'},
      {key:'ice', label:'Buz Sınıfı Teklifi', type:'buz', ship:'M/V Polar Anatolia', pay:Math.round(basePay*1.36), note:'Ice chart, icing ve icebreaker convoy.'},
      {key:'cable', label:'Cable Layer Teklifi', type:'cable', ship:'C/S Marmara Link', pay:Math.round(basePay*1.31), note:'Cable lay corridor ve subsea crossing.'},
      {key:'pipe', label:'Pipe Layer Teklifi', type:'pipe', ship:'P/L Blue Stinger', pay:Math.round(basePay*1.33), note:'Pipe tension, stinger angle ve A&R.'},
      {key:'shuttle', label:'Shuttle Tanker Teklifi', type:'shuttle', ship:'ST Black Sea Shuttle', pay:Math.round(basePay*1.35), note:'FPSO tandem offload ve DP bow loading.'}
    );
  }
  return offers;
}

