function doFreeTimeAction(key){
  const actions={
    study:{effect:{bilgi:6,dinclik:-3},mood:2,msg:'Kamarada not calistin; ECDIS/Radar kafanda biraz daha oturdu.'},
    sleep:{effect:{dinclik:12},mood:3,msg:'Kamarada kisa uyku yakaladin; vardiya oncesi gozlerin biraz acildi.'},
    deck:{effect:{cesaret:4,bilgi:2,dinclik:-4},mood:1,msg:'Güverte turunda halat, iskele ve emniyet noktalarini tekrar gordun.'},
    engine:{effect:{bilgi:5,dinclik:-5},mood:1,msg:'Makineye indin; alarm mantigi ve pompa hatlari daha netlesti.'},
    cook:{effect:{sayginlik:3,dinclik:4},mood:5,msg:'Aşçıyla çay içtin; gemi biraz daha ev gibi hissettirdi.'},
    sport:{effect:{dinclik:6,cesaret:2},mood:3,msg:'Kisa spor yaptin; beden toparlaninca kafa da toparlandi.'},
    family:{effect:{dinclik:2},mood:8,msg:'Aileyi aradin; yalnizlik biraz azaldi.'},
    logbook:{effect:{bilgi:4,sayginlik:2,dinclik:-2},mood:1,msg:'Logbook, hava ve trafik notlarini temiz girdin; vardiya devri daha profesyonel oldu.'},
    weather:{effect:{bilgi:5,dinclik:-1},mood:1,msg:'Hava raporu, barometre trendi ve swell yonunu kontrol ettin.'},
    gmdss:{effect:{bilgi:5,sayginlik:2,dinclik:-2},mood:1,msg:'GMDSS test, DSC log ve NAVTEX filtrelerini rutin olarak kontrol ettin.'},
    safety:{effect:{sayginlik:4,bilgi:2,dinclik:-3},mood:1,msg:'Fire patrol ve safety round yaptin; eksikleri buyumeden yakaladin.'},
    sounding:{effect:{bilgi:4,sayginlik:2,dinclik:-3},mood:1,msg:'Tank sounding ve sludge/fresh water notlarini kontrol ettin.'}
  };
  const a=actions[key]; if(!a) return;
  applyEffect(a.effect,{skipContractTick:true});
  adjustMood(a.mood,a.msg);
  if(key==='family'){
    pushPhoneMessage('Anne','Sesini duymak iyi geldi. Kendine dikkat et.', {open:false});
    familyUnread=0;
    unlockAchievement('family_anchor');
  }
  if(['logbook','weather','gmdss','safety','sounding'].includes(key)){
    pushPhoneMessage('Kaptan','Rutin gorevi kayda aldım. Boyle devam edersen vardiya devri temiz kalir.', {open:false});
  }
  addJournalEntry('[SERBEST ZAMAN] '+a.msg);
  awardMetaXp(key === 'family' ? 16 : 10, `Serbest zaman: ${key}`, 'routine');
  progressRetentionMission('free_time', {action:key});
  renderCareerPanel();
}

function buyCareerCourse(key){
  const courses={
    gmdss:{name:'GMDSS Refresher',cost:450,effect:{bilgi:8},xp:'safety'},
    ecdis:{name:'ECDIS Refresh',cost:550,effect:{bilgi:10},xp:'navigation'},
    tanker:{name:'Tanker Familiarization',cost:700,effect:{bilgi:7,sayginlik:2},xp:'tanker'},
    brm:{name:'BRM / Bridge Resource Management',cost:500,effect:{bilgi:6,sayginlik:4},xp:'people'}
  };
  const c=courses[key]; if(!c) return;
  if((careerState.money||0) < c.cost){ showNotif('!','Para Yetmedi',c.name+' icin yeterli bakiyen yok.'); return; }
  careerState.money -= c.cost;
  specialtyXP[c.xp] = (specialtyXP[c.xp]||0)+6;
  applyEffect(c.effect,{skipContractTick:true});
  addJournalEntry('[KURS] '+c.name+' tamamlandi.');
  showNotif('✓','Kurs Tamamlandi',c.name+' bilgi ve kariyer dosyana eklendi.');
  renderCareerPanel();
}

function runExamMode(key){
  const exams={
    colreg:{name:'COLREG Gorsel Sinav',gain:{bilgi:5,sayginlik:2},xp:'navigation'},
    gmdss:{name:'GMDSS Cihaz Sinavi',gain:{bilgi:5},xp:'safety'},
    ecdis:{name:'ECDIS Route Check Sinavi',gain:{bilgi:6},xp:'navigation'},
    radar:{name:'Radar / ARPA Sinavi',gain:{bilgi:6},xp:'navigation'},
    meteo:{name:'Meteoroloji Sinavi',gain:{bilgi:4},xp:'navigation'},
    stability:{name:'Stabilite Sinavi',gain:{bilgi:5},xp:'bulk'},
    ship:{name:'Gemi Yapisi Sinavi',gain:{bilgi:4},xp:'safety'}
  };
  const e=exams[key]; if(!e) return;
  const pass = (stats.bilgi + Math.random()*45) > 48;
  if(pass){
    applyEffect(e.gain,{skipContractTick:true});
    specialtyXP[e.xp]=(specialtyXP[e.xp]||0)+3;
    showNotif('✓','Sinav Gecti',e.name+' kariyer dosyana islendi.');
    addJournalEntry('[SINAV] '+e.name+' basarili.');
  }else{
    applyEffect({dinclik:-3},{skipContractTick:true});
    showNotif('~','Sinav Zor Geldi',e.name+' tekrar calisma istiyor.');
    addJournalEntry('[SINAV] '+e.name+' tekrar gerektiriyor.');
  }
  renderCareerPanel();
}

function getTopSpecialtyLabel(){
  const labels={container:'Konteynerci',tanker:'Tankerci',bulk:'Bulkci',lng:'LNGci',offshore:'Offshore',roro:'Ro-Ro',safety:'Emniyetci',navigation:'Seyirci',people:'Insan Yoneten'};
  const top=Object.entries(specialtyXP).sort((a,b)=>b[1]-a[1])[0] || ['navigation',0];
  return `${labels[top[0]]||top[0]} (${top[1]})`;
}

function getSpecialtyMeta(){
  return {
    navigation:{label:'Seyirci', icon:'ECDIS', desc:'Route monitoring, CPA/TCPA, UKC, TSS ve passage plan disiplini.'},
    safety:{label:'Emniyetci', icon:'SAFE', desc:'Fire, MOB, permit, PSC/class, near miss ve corrective action.'},
    people:{label:'Insan Yoneten', icon:'CREW', desc:'Murettebat gerilimi, vardiya yorgunlugu, iletisim ve guven hafizasi.'},
    tanker:{label:'Tankerci', icon:'TNK', desc:'Manifold, line-up, ESD, inert gas, COW ve cargo watch.'},
    lng:{label:'LNGci', icon:'LNG', desc:'Reliquefaction, cargo compressor, gas detection ve low-temperature risk.'},
    container:{label:'Konteynerci', icon:'BOX', desc:'Bay-row-tier, lashing, reefer alarm ve terminal operasyonu.'},
    bulk:{label:'Bulkci', icon:'BLK', desc:'Loading sequence, trim, draft survey, hold cleanliness ve grab operasyonu.'},
    offshore:{label:'Offshore', icon:'DP', desc:'Platform 500 m zone, DP alarm, ROV, cable/pipe lay ve supply run.'},
    roro:{label:'Ro-Ro', icon:'RORO', desc:'Ramp, lashings, fire watch, vehicle deck ventilation ve stability.'}
  };
}

function awardSpecialtyXpFromChoice(sc,c2){
  if(!sc || !c2) return;
  const blob = `${sc.id||''} ${sc.gfx||''} ${sc.loc||''} ${sc.sub||''} ${sc.text||''} ${c2.text||''}`.toLowerCase();
  const quality = c2.tag === 'kritik' ? 3 : c2.tag === 'akilli' ? 2 : c2.tag === 'cesur' || c2.tag === 'sosyal' ? 1 : 0;
  const add = (key, base=1)=>{ specialtyXP[key] = (specialtyXP[key]||0) + base + quality; };
  if(/radar|ecdis|route|waypoint|cpa|tcpa|ukc|tss|pilot station|chart|harita|seyir/.test(blob)) add('navigation',1);
  if(/fire|yangin|mob|abandon|permit|psc|survey|class|deficiency|near.?miss|risk|safety/.test(blob)) add('safety',1);
  if(/crew|murettebat|kavga|complaint|yorgun|itaatsizlik|moral|aile|psikoloji|lostromo|asci|zabit/.test(blob)) add('people',1);
  if(/tanker|manifold|line-up|esd|inert|cow|purging|gas freeing|slop|cargo control/.test(blob)) add('tanker',1);
  if(/lng|reliquefaction|compressor|cryogenic|low temperature/.test(blob)) add('lng',2);
  if(/container|bay|row|tier|lashing|reefer|terminal|gantry/.test(blob)) add('container',1);
  if(/bulk|hold|grab|draft survey|trim|hatch|coal|grain/.test(blob)) add('bulk',1);
  if(/offshore|platform|dp|rov|cable|pipe|anchor handling|ahts|psv|research|survey line/.test(blob)) add('offshore',1);
  if(/roro|ramp|vehicle deck|car carrier/.test(blob)) add('roro',1);
}

function createTeacherFeedbackForChoice(sc,c2){
  if(!sc || !c2) return;
  const weak = c2.tag === 'korkak' || c2.tag === 'hileli' || c2.tag === 'itaatkar';
  if(!weak) return;
  const blob = `${sc.id||''} ${sc.gfx||''} ${sc.loc||''} ${sc.sub||''} ${sc.text||''} ${c2.text||''}`.toLowerCase();
  let tip = 'Bu secimde eksik kalan nokta prosedur zinciriydi: once riski oku, sonra veriyi teyit et, sonra kisa rapor ve logbook.';
  if(/pilot|pilot station|boarding|ladder|berth/.test(blob)) tip = 'Pilot gorevinde berth ile pilot boarding point karistirma. Once dis yaklasmadaki pilot station, sonra VHF/pilot ladder/speed zinciri gelir.';
  else if(/radar|arpa|cpa|tcpa|ais/.test(blob)) tip = 'Radar kararinda AIS etiketi tek basina yetmez. Raw echo, ARPA CPA/TCPA, EBL/VRM ve ECDIS rota beraber okunur.';
  else if(/ecdis|chart|route|waypoint|tss|ukc|squat/.test(blob)) tip = 'ECDIS kararinda sadece rota cizgisine bakma. Safety contour, XTD, no-go area, UKC ve next waypoint birlikte kontrol edilir.';
  else if(/vhf|dsc|mayday|pan-pan|vts|smcp/.test(blob)) tip = 'VHF kararinda kanal, cagrinin turu ve mesaj sirasi kritik. CH16 nobet, working channel, DSC ve radio log ayrimini koru.';
  else if(/fire|yangin|mob|abandon|emergency/.test(blob)) tip = 'Acil durumda kahramanlik degil zincir onemli: alarm, mevki/mahal, ekip gorevi, cihaz/panel, rapor ve logbook.';
  else if(/crew|kavga|complaint|mobbing|itaatsizlik/.test(blob)) tip = 'Insan yonetiminde taraf tutmadan guvenli alan kur, tanik/olay kaydi al ve gerekiyorsa kaptana resmi kanaldan bildir.';
  else if(/charter|laycan|nor|sof|laytime|demurrage|despatch/.test(blob)) tip = 'Charter saatlerinde tahminle gitme. NOR tender/accepted, notice time, SOF ve laytime baslangicini ayrica ayir.';
  addWatchFeed(`Ogretmen notu: ${tip}`, 'warn');
  pushPhoneMessage('AI Mate', `Ogretmen notu: ${tip}`, {open:false});
  if(phoneAiState?.messages){
    phoneAiState.messages.push({from:'AI Mate', text:`Ogretmen notu: ${tip}`, me:false});
    phoneAiState.messages = phoneAiState.messages.slice(-30);
  }
}

