function getCrewNamePoolForLanguage(lang){
  const safeLang = CREW_NAME_POOLS_BY_LANG[lang] ? lang : 'tr';
  return {...CREW_NAME_POOLS, ...(CREW_NAME_POOLS_BY_LANG[safeLang] || {})};
}

