function getSpecialistCrewKeysForShipType(type){
  const activeType = type || (typeof selType !== 'undefined' ? selType : 'kuru');
  return [...new Set(SHIP_TYPE_SPECIALIST_KEYS[activeType] || SHIP_TYPE_SPECIALIST_KEYS.kuru || [])].filter(k=>CREW_DEFS[k]);
}

function getActiveCrewKeysForShipType(type){
  const activeType = type || (typeof selType !== 'undefined' ? selType : 'kuru');
  const profile = SHIP_TYPE_ACTIVE_CREW_KEYS[activeType] || STANDARD_TRADING_CREW_KEYS;
  return [...new Set(profile)].filter(k=>CREW_DEFS[k]);
}

function getActiveSpecialistCrewKeysForShipType(type){
  const active = new Set(getActiveCrewKeysForShipType(type));
  const standard = new Set(STANDARD_TRADING_CREW_KEYS);
  return [...active].filter(k=>!standard.has(k));
}

function getCrewRosterNote(type){
  const activeType = type || (typeof selType !== 'undefined' ? selType : 'kuru');
  const activeCount = getActiveCrewKeysForShipType(activeType).length;
  const note = SHIP_TYPE_CREW_COUNT_NOTES[activeType] || `${activeCount} aktif`;
  const specialistPool = getSpecialistCrewKeysForShipType(activeType).length;
  return `${note} · ${specialistPool} rol havuzu`;
}

function isSpecialistCrewActive(key,type){
  return getActiveSpecialistCrewKeysForShipType(type).includes(key);
}

function applyActiveSpecialistCrewToPhone(type){
  const keys = getActiveSpecialistCrewKeysForShipType(type);
  const specialists = keys.map(k=>CREW_DEFS[k]).filter(Boolean);
  if(!specialists.length || typeof phoneContacts === 'undefined') return;
  specialists.slice(0,6).forEach(def=>{
    if(!phoneContacts.some(c=>c.name === def.name)){
      phoneContacts.push({name:def.name, number:'Crew', role:def.title || 'Specialist'});
    }
  });
  if(typeof ensurePhoneGroup === 'function'){
    ensurePhoneGroup('Crew Chat', specialists.slice(0,6).map(def=>def.name));
  }
  if(Array.isArray(phoneMessages)){
    const label = SPECIALIST_CREW_SHIP_LABELS[type] || 'bu gemide';
    const roster = specialists.slice(0,5).map(def=>def.name.replace(/\s+/g,' ')).join(', ');
    phoneMessages.push({from:'Crew Chat', chat:'Crew Chat', text:`Aktif gemi kadrosu ${label}: ${getCrewRosterNote(type)}. Uzman kişiler: ${roster || 'rutin kadro'}.`, me:false});
  }
}

function pickRandom(list){
  return list[Math.floor(Math.random()*list.length)];
}

function makeCrewPortrait(key, def){
  const stripeBias = portraitStripeCount(def.title);
  const roleBlob = normalizeTrAscii(`${key} ${def.title||''} ${def.name||''}`);
  const base = inferPortraitBase(def);
  const supportSheet = base==='female' ? PORTRAIT_SHEET_ASSETS.supportFemale : PORTRAIT_SHEET_ASSETS.supportMale;
  const supportPool = {
    engine:[0,1,2],
    deck:[3,4],
    cook:[5]
  };
  let supportIdx = null;
  if(/(^| )(carkci|bas2|yagci|motormanintl|pumpman|fitter|welder|rovtech|motorcu|ucmuhendis|yagcibasi|elektrisyen|ruscarkci|hindliyagci)( |$)|muhendis|makine|motorman|engine rating|pompa|pumpman|fitter|kaynak|welder|rov|subsea|hot work|oiler|electrician|chief engineer/.test(roleBlob)) supportIdx = pickRandom(supportPool.engine);
  else if(/(^| )(lostromo|lostromo2|hasan|musa|abintl|gemicibasi|gemici|latinab)( |$)|guverte|silici|tayfa|able seafarer|deck|deck foreman|deck rating/.test(roleBlob)) supportIdx = pickRandom(supportPool.deck);
  else if(/(^| )(asci|steward|kambuz|garson|filipinliasci)( |$)|yemekhane|galley|hotel|guest services|kamarot|service steward|chief cook/.test(roleBlob)) supportIdx = pickRandom(supportPool.cook);
  if(supportIdx!==null){
    return {
      __portraitVersion:CREW_PORTRAIT_VERSION,
      __roleKey:key,
      __base:base,
      __name:def.name || '',
      base,
      portraitSheet:supportSheet,
      sheetCols:3,
      sheetRows:2,
      sheetIndex:supportIdx,
      bg:'portrait'
    };
  }
  const hairPool = base==='female'
    ? ['bob','bun','waves','parted','curly','slick']
    : ['short','swept','crop','parted','slick','quiff','waves','curly'];
  const age = pickRandom(['young','mid']);
  const officerSheet = age==='young' ? PORTRAIT_SHEET_ASSETS.officerYoung : PORTRAIT_SHEET_ASSETS.officerMid;
  const officerIndexPool = OFFICER_SHEET_POOLS[age]?.[base] || OFFICER_SHEET_POOLS.young.male;
  return {
    __portraitVersion:CREW_PORTRAIT_VERSION,
    __roleKey:key,
    __base:base,
    __name:def.name || '',
    roleTitle:def.title || '',
    uniformRole:getPortraitUniformRole({base,__roleKey:key,roleTitle:def.title,__name:def.name}),
    skin: pickRandom(PLAYER_LOOK.skin),
    base,
    age,
    pose: pickRandom(['front','angled','command']),
    face: pickRandom(PLAYER_LOOK.face),
    hair: pickRandom(hairPool),
    hairColor: pickRandom(PLAYER_LOOK.hairColor),
    eye: pickRandom(PLAYER_LOOK.eye),
    uniform: pickRandom(PLAYER_LOOK.uniform),
    suitColor: /mühendis|cark/i.test(def.title) ? '#202d3a' : '#1b2435',
    shirtColor:'#f1efe8',
    tieColor:'#13171d',
    stripes: stripeBias,
    bg: /köprü|seyir|süvari|zabit/i.test(def.title) ? 'bridge' : 'portrait',
    portraitSheet: officerSheet,
    sheetCols:4,
    sheetRows:2,
    sheetIndex: pickRandom(officerIndexPool)
  };
}

function getCrewPortraitForKey(key){
  if(!CREW_DEFS[key]) return null;
  const def = CREW_DEFS[key];
  const current = crewPortraits[key];
  const nextBase = inferPortraitBase(def);
  if(
    !current ||
    current.__portraitVersion !== CREW_PORTRAIT_VERSION ||
    current.__roleKey !== key ||
    current.__base !== nextBase ||
    current.__name !== (def.name || '')
  ){
    crewPortraits[key] = makeCrewPortrait(key, def);
  }
  return crewPortraits[key];
}

function sanitizeCrewPortraitRoster(context='runtime'){
  let fixed = 0;
  Object.keys(CREW_DEFS).forEach(key=>{
    const def = CREW_DEFS[key];
    const expectedBase = inferPortraitBase(def);
    const current = crewPortraits[key];
    const sheet = String(current?.portraitSheet || '');
    const wrongGenderSheet = expectedBase === 'female'
      ? /support-style-male|support-male/i.test(sheet)
      : /support-style-female|support-female/i.test(sheet);
    const stale = !current
      || current.__portraitVersion !== CREW_PORTRAIT_VERSION
      || current.__roleKey !== key
      || current.__base !== expectedBase
      || current.__name !== (def.name || '')
      || wrongGenderSheet;
    if(stale){
      crewPortraits[key] = makeCrewPortrait(key, def);
      fixed += 1;
    }
    if(expectedBase === 'female' && crewPortraits[key]){
      crewPortraits[key].beard = 'clean';
    }
  });
  if(fixed && typeof recordReleaseDiagnostic === 'function'){
    recordReleaseDiagnostic('crew_portrait_roster_sanitized', '', {context, fixed});
  }
  return fixed;
}

function randomizeCrewRoster(lang){
  const activeLang = lang || (typeof gameLanguage !== 'undefined' ? gameLanguage : 'tr');
  const pools = getCrewNamePoolForLanguage(activeLang);
  Object.keys(pools).forEach(key=>{
    if(CREW_DEFS[key]) CREW_DEFS[key].name = pickRandom(pools[key]);
    if(CREW_DEFS[key]) crewPortraits[key] = makeCrewPortrait(key, CREW_DEFS[key]);
  });
}

let crewTrust = {};
let crewUnlocked = {};

function initCrewSystem(){
  sanitizeCrewPortraitRoster('init');
  Object.keys(CREW_DEFS).forEach(k => {
    crewTrust[k] = CREW_DEFS[k].trust;
    crewUnlocked[k] = 0;
  });
  renderCrewCards();
}

function updateCrewTrust(crewKey, delta){
  if(!crewKey || !CREW_DEFS[crewKey]) return;
  crewTrust[crewKey] = Math.min(100, Math.max(0, (crewTrust[crewKey]||50) + delta));
  // Unlock secrets at 60, 75, 90
  const unlockThresholds = [60,75,90];
  unlockThresholds.forEach((t,i) => {
    if(crewTrust[crewKey] >= t && (crewUnlocked[crewKey]||0) <= i){
      crewUnlocked[crewKey] = i+1;
      const def = CREW_DEFS[crewKey];
      if(def.secrets[i]){
        showNotif('🔓', def.name + ' — Güven Kazanıldı', def.secrets[i]);
        addJournalEntry(`${def.name} hakkında yeni bir şey öğrendim: ${def.secrets[i]}`);
      }
    }
  });
  renderCrewCards();
}

function getCrewKeyFromWho(who){
  if(who && CREW_DEFS[who]) return who;
  const map = {
    lostromo:'lostromo', silici:'lostromo2', yagci:'yagci', asci:'asci',
    hasan:'hasan', musa:'musa', suvari:'suvari', z1:'z1', z2:'z2',
    z3:'z3', carkci:'carkci', bascarkci:'carkci', bas2:'bas2', mateintl:'mateintl',
    abintl:'abintl', motormanintl:'motormanintl', gazsubay:'gazsubay'
  };
  return map[who] || null;
}

function getCrewDisplay(who){
  const key = getCrewKeyFromWho(who);
  if(key && CREW_DEFS[key]){
    const def = CREW_DEFS[key];
    return {name:def.name, icon:def.icon, title:def.title};
  }
  return CREW[who] || CREW.anlatici;
}

function getCrewNameParts(fullName=''){
  const clean = String(fullName || '').replace(/\s+/g,' ').trim();
  const prefixes = [
    'Gaz Kontrol Subayı','Navigasyon Subayı','Telsiz Subayı','Elektrik Zabiti',
    'Çevresel İşler Subayı','Bunkering Zabiti','Konteyner Zabiti','Dökme Yük Zabiti',
    'Hidrografik Araştırmacı','Deniz Biyoloğu','ROV Teknisyeni','Hotel Müdürü',
    'Güvenlik Zabiti','Makine Reisi Fitter','Kaynakçı Usta','Gemi Hekimi',
    'Baş Mühendis','2. Mühendis','3. Mühendis','1. Zabit','2. Zabit','3. Zabit',
    'Chief Engineer','Chief Cook','Motorman','Pumpman','Stewardess','Steward',
    'Lostromo','Silici','Yağcıbaşı','Yağcı','Aşçı','Tayfa','Kaptan','AB'
  ].sort((a,b)=>b.length-a.length);
  const prefix = prefixes.find(p=>clean.toLocaleLowerCase('tr-TR').startsWith(p.toLocaleLowerCase('tr-TR') + ' '));
  if(!prefix) return {full:clean, role:'', personal:clean};
  return {full:clean, role:prefix, personal:clean.slice(prefix.length).trim() || clean};
}

function addCrewNameReplacement(map, source, target, allowShort=false){
  const from = String(source || '').replace(/\s+/g,' ').trim();
  const to = String(target || '').replace(/\s+/g,' ').trim();
  if(!from || !to) return;
  if(!allowShort && from.length < 4) return;
  map.set(from, to);
  const lower = from.toLocaleLowerCase('tr-TR');
  if(lower !== from) map.set(lower, to.toLocaleLowerCase('tr-TR'));
}

function replaceCrewNameToken(text, source, target){
  const letters = '0-9A-Za-zÇĞİÖŞÜçğıöşüÂâÎîÛû';
  const suffix = `[A-Za-zÇĞİÖŞÜçğıöşüÂâÎîÛû']{0,10}`;
  const re = new RegExp(`(^|[^${letters}])(${escapeRegExp(source)})(${suffix})(?=$|[^${letters}])`, 'g');
  return String(text || '').replace(re, (_all, boundary, _name, ending)=>`${boundary}${target}${ending || ''}`);
}

function sanitizeSceneCrewNames(text, sc=null){
  let out = String(text ?? '');
  const key = getCrewKeyFromWho(sc?.who);
  if(!key || !CREW_DEFS[key] || !out) return out;
  const active = getCrewNameParts(getCrewDisplay(sc?.who).name || CREW_DEFS[key].name);
  const replacements = new Map();
  const localizedPools = typeof getCrewNamePoolForLanguage === 'function' ? getCrewNamePoolForLanguage(gameLanguage) : CREW_NAME_POOLS;
  const pool = Array.isArray(localizedPools?.[key]) ? localizedPools[key] : [];
  const basePool = Array.isArray(CREW_NAME_POOLS?.[key]) ? CREW_NAME_POOLS[key] : [];
  const legacy = [CREW_DEFS[key]?.name, CREW?.[key]?.name, ...(pool || []), ...(basePool || [])].filter(Boolean);
  legacy.forEach(name=>{
    const parts = getCrewNameParts(name);
    addCrewNameReplacement(replacements, parts.full, active.full, true);
    addCrewNameReplacement(replacements, parts.personal, active.personal, false);
  });
  [...replacements.entries()]
    .filter(([from,to])=>from && to && from !== to)
    .sort((a,b)=>b[0].length-a[0].length)
    .forEach(([from,to])=>{ out = replaceCrewNameToken(out, from, to); });
  return out;
}

function personalizeSceneSpeakerText(text, sc=null){
  let out = sanitizeSceneCrewNames(text, sc);
  const key = getCrewKeyFromWho(sc?.who);
  if(!key || !CREW_DEFS[key] || !out) return out;
  const active = getCrewNameParts(getCrewDisplay(sc?.who).name || CREW_DEFS[key].name);
  const role = normalizeTrAscii(active.role || '');
  if(!role || !active.personal) return out;
  const replacementMap = new Map();
  const sameRoleNames = Object.values(CREW_DEFS || {})
    .map(def=>def?.name)
    .filter(Boolean)
    .filter(name=>normalizeTrAscii(getCrewNameParts(name).role || '') === role);
  sameRoleNames.forEach(name=>{
    const parts = getCrewNameParts(name);
    addCrewNameReplacement(replacementMap, parts.full, active.full, true);
    addCrewNameReplacement(replacementMap, parts.personal, active.personal, false);
  });
  [...replacementMap.entries()]
    .filter(([from,to])=>from && to && from !== to)
    .sort((a,b)=>b[0].length-a[0].length)
    .forEach(([from,to])=>{ out = replaceCrewNameToken(out, from, to); });
  return out;
}

function getCrewRoleAtlasPanel(type=selType, opts={}){
  const active = new Set(getActiveCrewKeysForShipType(type));
  const compact = !!opts.compact;
  const shipLabel = STYPES.find(x=>x.key===type)?.nm || type || 'Gemi';
  const groups = CREW_ROLE_ATLAS_GROUPS.map(group=>{
    const roles = compact ? group.roles.filter(role=>active.has(role.key)) : group.roles;
    if(compact && !roles.length) return '';
    const cards = roles.map(role=>{
      const def = CREW_DEFS[role.key];
      const isActive = active.has(role.key);
      const portrait = def ? renderPortraitSprite(getCrewPortraitForKey(role.key) || makeCrewPortrait(role.key, def), compact ? 'crew' : 'avatar') : '';
      const title = def?.title || role.label;
      const name = def?.name || role.label;
      return `<div class="crew-atlas-card ${isActive?'active':'locked'}">
        <span class="crew-atlas-portrait">${portrait || '<i></i>'}</span>
        <b>${phoneSafe(role.label)}</b>
        <small>${phoneSafe(name)}</small>
        <em>${phoneSafe(title)}</em>
        <p>${phoneSafe(role.note)}</p>
        <strong>${isActive?'AKTIF':'BU GEMIDE YOK'}</strong>
      </div>`;
    }).join('');
    return `<section class="crew-atlas-group ${phoneSafe(group.tone)}">
      <div class="crew-atlas-title"><span>${phoneSafe(group.icon)}</span><b>${phoneSafe(group.title)}</b></div>
      <div class="crew-atlas-cards">${cards}</div>
    </section>`;
  }).join('');
  return `<div class="crew-atlas ${compact?'compact':''}">
    <div class="crew-atlas-head">
      <div><b>${compact?'AKTIF GEMI KADROSU':'PERSONEL ATLASI'}</b><small>${phoneSafe(shipLabel)} · ${compact?'bu gemide bulunan ekip':'aktif ekip ve eğitim amaçlı rol havuzu'}</small></div>
      <span>${phoneSafe(getCrewRosterNote(type))}</span>
    </div>
    ${groups}
  </div>`;
}

function renderCrewCards(){
  const c = document.getElementById('crew-cards');
  if(!c) return;
  sanitizeCrewPortraitRoster('render');
  c.innerHTML = getCrewRoleAtlasPanel(typeof selType !== 'undefined' ? selType : 'kuru', {compact:true});
  getActiveCrewKeysForShipType(typeof selType !== 'undefined' ? selType : 'kuru').forEach(key => {
    const def = CREW_DEFS[key];
    if(!def) return;
    const trust = crewTrust[key] || def.trust;
    const unlocked = crewUnlocked[key] || 0;
    const color = trust>=70?'#5dbf8a':trust>=50?'#d4a017':'#c97070';
    const relation = trust>=75?'Guveniyor ama gozunu uzerinde tutuyor':trust>=55?'Seni tartiyor':trust>=40?'Mesafeyi koruyor':'Henuz kolay acilmiyor';
    const fatigueKey = /lostromo|musa|hasan|abintl/.test(key) ? 'deck' : /carkci|bas2|yagci|motormanintl/.test(key) ? 'engine' : key==='asci' ? 'galley' : 'bridge';
    const fatigue = Math.round(crewFatigueState[fatigueKey] || 20);
    const distance = Math.max(0, 100 - trust);
    const hurt = Math.max(0, (crewMemoryNotes[key]?.bad || 0) * 18 - (crewMemoryNotes[key]?.good || 0) * 8);
    const div = document.createElement('div');
    div.className = 'crew-card';
    const portrait = renderPortraitSprite(getCrewPortraitForKey(key) || makeCrewPortrait(key, def), 'crew');
    div.innerHTML = `<div class="crew-card-top">
      <span class="crew-ico portrait-chip small">${portrait}</span>
      <div><div class="crew-name">${def.name}</div><div class="crew-title-small">${def.title}</div></div>
      <span style="margin-left:auto;font-size:11px;font-family:'Share Tech Mono',monospace;color:${color};">${trust}</span>
    </div>
    <div class="crew-title-small" style="margin-bottom:6px;color:var(--text2);line-height:1.45;">${def.style||''}</div>
    <div class="crew-title-small" style="margin-bottom:6px;color:${color};line-height:1.35;">${relation}</div>
    <div class="crew-trust-bar"><div class="crew-trust-fill" style="width:${trust}%;background:${color};"></div></div>
    <div class="crew-trust-lbl"><span>${trust>=70?'Güveniyor':trust>=50?'Tanışıyor':'Mesafeli'}</span><span>🔓 ${unlocked}/3</span></div>
    <div class="crew-title-small" style="margin-top:6px;color:var(--text3);line-height:1.45;">Yorgunluk ${fatigue}/100 · Mesafe ${distance}/100 · Kirginlik ${Math.min(100,hurt)}/100</div>
    ${unlocked>0?`<div class="crew-unlocked">💬 "${def.secrets[unlocked-1]?.substring(0,50)}..."</div>`:''}`;
    c.appendChild(div);
  });
}

function toggleCrew(){
  const p = document.getElementById('crew-panel');
  p.classList.toggle('open');
}

// Apply crew trust changes based on scene choices
function applyCrewEffect(who, tag){
  const key = getCrewKeyFromWho(who);
  if(!key) return;
  let delta = tag==='sosyal'?5:tag==='akilli'?3:tag==='cesur'?2:tag==='korkak'?-5:tag==='itaatkar'?2:-2;
  const pref = CREW_DEFS[key]?.prefs?.[tag];
  if(typeof pref === 'number') delta += pref;
  if(key==='suvari' && (tag==='kritik' || tag==='akilli')) delta += 2;
  if(key==='suvari' && tag==='korkak') delta -= 2;
  if(key==='z1' && (tag==='kritik' || tag==='itaatkar')) delta += 1;
  if(key==='z2' && (tag==='akilli' || tag==='kritik')) delta += 2;
  if(key==='z3' && tag==='korkak') delta -= 2;
  if(key==='lostromo' && tag==='cesur') delta += 1;
  if(key==='carkci' && (tag==='akilli' || tag==='kritik')) delta += 1;
  updateCrewTrust(key, delta);
}

