function setIntroMenuPage(page='play'){
  introMenuPage = ['play','ship','options','premium'].includes(page) ? page : 'play';
  document.querySelectorAll('.intro-menu-tab').forEach(btn=>{
    const active = btn.dataset.introTab === introMenuPage;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  document.querySelectorAll('.intro-page').forEach(panel=>{
    panel.classList.toggle('active', panel.dataset.introPage === introMenuPage);
  });
  const cards = Array.from(document.querySelectorAll('#intro > .fcard'));
  cards.forEach(card=>{
    const isPremium = card.classList.contains('intro-premium-card');
    const isShip = card.classList.contains('ship-tab-card');
    const isShipSummary = card.classList.contains('ship-choice-summary-card');
    const isOptions = !!card.querySelector('#play-mode-select,#intro-language-select,#sound-btn');
    const show = introMenuPage === 'premium' ? isPremium
      : introMenuPage === 'options' ? isOptions
      : introMenuPage === 'ship' ? isShip
      : (!isOptions && !isPremium && !isShip) || isShipSummary;
    card.hidden = !show;
  });
  const launch = document.getElementById('go-btn');
  const saveActions = document.getElementById('save-entry-actions');
  if(launch) launch.style.display = introMenuPage === 'play' || introMenuPage === 'ship' ? 'block' : 'none';
  if(saveActions) saveActions.style.display = introMenuPage === 'play' || introMenuPage === 'ship' ? 'flex' : 'none';
  renderSetupOnboardingGuide();
  renderAudioMixer();
  syncCleanHudControls();
}

function renderPlayModeSelector(){
  const html = Object.entries(PLAY_MODE_DEFS).map(([key,def])=>`
    <button type="button" class="mode-card ${gameplayMode===key?'active':''}" onclick="setGameplayMode('${key}')">
      <b>${phoneSafe(getModeLabel(key))}</b><span>${phoneSafe(getModeDesc(key))}</span>
    </button>`).join('');
  document.querySelectorAll('#play-mode-select,#home-play-mode-select,#game-settings-play-mode-select').forEach(box=>{
    if(box) box.innerHTML = html;
  });
}

function getFeatureUnlocks(sc){
  const sceneNo = Math.max(1, currentIdx + 1, contractDays || 0);
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const mode = getGameplayModeDef();
  const doingWell = (stats.bilgi || 0) + (stats.sayginlik || 0) > 145 && (SYSTEM_STATE.totalMistakes || 0) < 3;
  const assist = (SYSTEM_STATE.consecutiveMistakes || 0) >= 2 || (stats.dinclik || 0) < 24;
  const bonus = doingWell ? 2 : 0;
  const forced = {
    vhf:/vhf|dsc|mayday|pan-pan|distress|vts|pilot/.test(blob),
    map:/map|chart|ecdis|route|pilot station|waypoint|tss|harita|seyir/.test(blob),
    devices:/radar|arpa|ecdis|ais|vhf|gmdss|gyro|echo|bnwas|device|cihaz/.test(blob),
    logbook:/logbook|defter|handover|teslim|all fast|pilot boarding|watch/.test(blob)
  };
  const simple = mode.level === 0;
  return {
    phone: !simple || sceneNo >= 5,
    map: !simple,
    devices: !simple && (sceneNo >= 9 - bonus || forced.devices || forced.vhf),
    logbook: !simple && (sceneNo >= 10 - bonus || forced.logbook || assist),
    cabin: !simple && sceneNo >= 12 - bonus,
    shipwalk: true,
    sim: mode.level >= 1 && sceneNo >= 16 - bonus,
    career: sceneNo >= 10,
    album: sceneNo >= 8,
    assist,
    advanced: mode.level >= 1,
    expert: mode.level >= 2
  };
}

function featureLockedMessage(feature){
  const names = {
    phone:'Telefon', map:'Harita', devices:'Cihaz egitimi', logbook:'Vardiya defteri',
    cabin:'Kamara', shipwalk:'Gemi ici harita', sim:'Simulasyon merkezi',
    career:'Kariyer', album:'Album', expert:'Uzman detay'
  };
  return `${names[feature] || 'Bu bolum'} henuz acilmadi. Oyuncuyu yormamak icin sistemler kontrat ilerledikce aciliyor.`;
}

function canUseFeature(feature, sc=sceneQueue[currentIdx] || null, notify=true){
  if(feature === 'shipwalk') return true;
  const u = getFeatureUnlocks(sc);
  const ok = !!u[feature];
  if(!ok && notify) showNotif('KILIT', 'Yavas Aciliyor', featureLockedMessage(feature));
  return ok;
}

function getSceneGuidance(sc){
  const blob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  const firstWatchSteps = [
    'Sahneyi oku: kim konusuyor, nerede ve senden ne istiyor?',
    'Secenek etiketine degil, emniyetli ve prosedurel davranisa odaklan.',
    'Ust bardaki Kaydet ile ilerlemeni istedigin an koruyabilirsin.',
    'Harita acildiginda once rota, gemi mevkii ve sonraki waypointi bul.',
    'Cihaz gorevinde ekrani buyut; alarm, hedef ve degerleri birlikte oku.',
    'Vardiya akisi artik sende: karar, rapor ve kayit birbirini takip eder.'
  ];
  if((careerState?.contracts || 0) === 0 && currentIdx < firstWatchSteps.length && !/fire|yangin|mob|abandon|distress|blackout/.test(blob)){
    return `[Baslangic ${currentIdx+1}/${firstWatchSteps.length}] ${translateGameText(firstWatchSteps[currentIdx])}`;
  }
  if((SYSTEM_STATE.consecutiveMistakes || 0) >= 2) return t('guide.support','Destek modu: acele etme, prosedure en yakin ve kanitli karari sec.');
  if((stats.dinclik || 0) < 24) return t('guide.tired','Dinclik dusuk: riskli kahramanlik yerine sakin ve prosedurel karar ver.');
  if(/vhf|dsc|mayday|pan-pan|vts|pilot exchange/.test(blob)) return t('guide.vhf','VHF kanalini ve cagri tipini netlestir.');
  if(/radar|arpa|cpa|tcpa|ais/.test(blob)) return t('guide.radar','Hedefi oku: CPA/TCPA, niyet ve rapor.');
  if(/ecdis|route|waypoint|chart|tss|ukc|squat/.test(blob)) return t('guide.ecdis','Haritada rota, emniyet konturu ve sonraki noktayi kontrol et.');
  if(/engine|makine|blackout|alarm|generator|pump/.test(blob)) return t('guide.engine','Makine bilgisini al, kaptana kisa rapor ver.');
  if(/pilot|tug|berth|mooring|all fast|halat/.test(blob)) return t('guide.port','Speed-heading, halat sirasi ve snap-back riskini izle.');
  if(/fire|yangin|mob|abandon|distress/.test(blob)) return t('guide.emergency','Once emniyet zinciri: alarm, mevki, ekip, rapor.');
  if(/psc|survey|class|inspection|deficiency/.test(blob)) return t('guide.inspection','Belgeyi, ekipmani ve eksik riskini sakin kontrol et.');
  return t('guide.default','Sahneyi oku, kimin ne istedigini anla ve tek net karar ver.');
}

function updateFeatureVisibility(sc){
  const game = document.getElementById('game');
  if(game){
    game.classList.toggle('simple-mode', gameplayMode === 'simple');
    game.classList.toggle('realistic-mode', gameplayMode === 'realistic');
    game.classList.toggle('expert-mode', gameplayMode === 'expert');
    game.classList.toggle('new-player', Math.max(currentIdx+1, contractDays || 0) < 12);
  }
  const map = [
    ['openMap()','map'], ['openDevices()','devices'], ['openSimCenter()','sim'], ['openCareer()','career'],
    ['openShipWalk()','shipwalk'], ['openCabin()','cabin'], ['openLiveLogbook()','logbook'],
    ['togglePhone()','phone'], ['openAlbum()','album']
  ];
  const unlocks = getFeatureUnlocks(sc);
  map.forEach(([onclick,feature])=>{
    document.querySelectorAll(`#toolbar button[onclick="${onclick}"]`).forEach(btn=>{
      btn.classList.toggle('locked-tool', !unlocks[feature]);
      btn.classList.toggle('advanced-tool', ['map','devices','sim','shipwalk','cabin','logbook'].includes(feature));
      btn.classList.toggle('expert-tool', ['sim'].includes(feature));
      btn.title = unlocks[feature] ? '' : featureLockedMessage(feature);
    });
  });
}

function getGamePolishStatus(sc){
  const route = getActiveVoyageRoute ? getActiveVoyageRoute() : null;
  const voyage = liveVoyageState || computeLiveVoyageState(sc || {});
  const openDevices = Object.entries(devicePracticeProgress || {})
    .filter(([,progress])=>progress===0)
    .map(([key])=>getDeviceDef(key)?.name || key.toUpperCase());
  const mapTask = typeof getCurrentMapTask === 'function' ? getCurrentMapTask() : null;
  const month = Math.max(1, Math.floor((contractDays || currentIdx || 0) / CONTRACT_SCENES_PER_MONTH) + 1);
  const totalMonths = Math.max(1, getContractTotalMonths());
  const routeLine = route ? `${route.name} ${voyage.progress || 0}%` : 'Sefer secili degil';
  const deviceLine = openDevices.length ? `${openDevices.slice(0,2).join(', ')} tekrari` : 'Cihaz tekrari yok';
  const mapLine = mapTask ? `${mapTask.title}` : 'Harita gorevi hazir';
  const premiumLine = premiumUnlocked ? 'Premium acik' : 'Premium kilitli';
  return {
    routeLine,
    deviceLine,
    mapLine,
    premiumLine,
    short:`${routeLine} · ${deviceLine} · Ay ${month}/${totalMonths}`,
    detailed:`${routeLine} · ${mapLine} · ${deviceLine} · ${premiumLine}`
  };
}

function updateGuidanceStrip(sc){
  const modeEl = document.getElementById('guidance-mode');
  const textEl = document.getElementById('guidance-text');
  const unlockEl = document.getElementById('guidance-unlocks');
  if(modeEl) modeEl.textContent = `${t('ui.mode','Mod')}: ${getModeLabel(gameplayMode)}`;
  if(textEl) textEl.textContent = getSceneGuidance(sc);
  if(unlockEl){
    const u = getFeatureUnlocks(sc);
    const open = [
      u.phone?'Telefon':'',
      u.map?'Harita':'',
      u.devices?'Cihaz':'',
      u.logbook?'Defter':'',
      u.sim?'Sim':''
    ].filter(Boolean).join(' · ');
    const polish = getGamePolishStatus(sc);
    unlockEl.textContent = u.assist
      ? t('ui.assist','Destek modu acik: rehber daha ogretici.')
      : open ? `${t('ui.unlocked','Acik')}: ${translateGameText(open)} · ${phoneSafe(polish.short)}`
      : `${t('ui.basicStory','Sadece hikaye ve temel secimler.')} · ${phoneSafe(polish.short)}`;
    unlockEl.title = polish.detailed;
  }
}

function sceneMissionBlob(sc){
  return `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
}

function makeMissionStep(id, label){
  return {id, label};
}

