function updateMissionDirector(sc){
  const box = document.getElementById('mission-director');
  const titleEl = document.getElementById('mission-title');
  const stepsEl = document.getElementById('mission-steps');
  if(!box || !titleEl || !stepsEl) return;
  const plan = getMissionDirectorPlan(sc);
  if(missionDirectorState.sceneId !== sc?.id){
    missionDirectorState = {sceneId:sc?.id || '', title:plan.title, steps:plan.steps, completed:[]};
  }else{
    missionDirectorState.title = plan.title;
    missionDirectorState.steps = plan.steps;
  }
  const show = gameplayMode !== 'simple' || (missionDirectorState.completed || []).length > 0 || sc?.alert;
  box.classList.toggle('show', !!show);
  titleEl.textContent = translateGameText(missionDirectorState.title);
  const done = new Set(missionDirectorState.completed || []);
  const firstOpen = missionDirectorState.steps.find(s=>!done.has(s.id))?.id;
  stepsEl.innerHTML = missionDirectorState.steps.map(s=>{
    const cls = done.has(s.id) ? 'done' : s.id === firstOpen ? 'active' : 'locked';
    return `<div class="mission-step ${cls}">${phoneSafe(translateGameText(s.label))}</div>`;
  }).join('');
}

function completeMissionStep(id, note=''){
  if(!id || !missionDirectorState?.steps?.length) return;
  if(!missionDirectorState.steps.some(s=>s.id === id)) return;
  if(!missionDirectorState.completed.includes(id)){
    missionDirectorState.completed.push(id);
    if(note) addWatchFeed(note, 'good');
  }
  updateMissionDirector(sceneQueue[currentIdx] || null);
}

function completeMissionFromFeature(feature){
  const map = {map:'map', devices:'device', logbook:'logbook', phone:'followup', sim:'device', career:'followup'};
  completeMissionStep(map[feature] || feature, `${feature.toUpperCase()} gorev adimi tamamlandi`);
}

function completeMissionFromChoice(sc,c2){
  const blob = `${sceneMissionBlob(sc)} ${c2?.text||''}`.toLowerCase();
  completeMissionStep('report');
  if(/vhf|ch16|dsc|vts|pilot channel|kanal/.test(blob)) completeMissionStep('vhf');
  if(/radar|arpa|cpa|tcpa|ais|target/.test(blob)) completeMissionStep('radar');
  if(/ecdis|chart|harita|route|waypoint|safety contour|xtd|ukc|tss/.test(blob)) completeMissionStep('ecdis');
  if(/logbook|radio log|kayit|defter/.test(blob)) completeMissionStep('logbook');
  if(/weather|hava|swell|barometre|gorus|görüş/.test(blob)) completeMissionStep('weather');
  if(/handover|teslim|vardiya/.test(blob)) completeMissionStep('handover');
  if(/halat|snap-back|deck|guverte|mooring/.test(blob)) completeMissionStep('deck');
  if(/alarm|muster|fire|yangin|mob|abandon/.test(blob)) completeMissionStep('alarm');
  if(/makine|engine|generator|pump|compressor/.test(blob)) completeMissionStep('engine');
  if(/belge|document|permit|psc|survey|class/.test(blob)) completeMissionStep('document');
}

function hasSavedGame(){
  try{return !!(localStorage.getItem(SAVE_KEY) || localStorage.getItem(SAVE_BACKUP_KEY) || localStorage.getItem(SAVE_RECOVERY_KEY));}catch(e){return false;}
}

function refreshSaveEntryActions(){
  const continueBtn = document.getElementById('continue-btn');
  const deleteBtn = document.getElementById('delete-save-btn');
  const homeContinueBtn = document.getElementById('home-continue-btn');
  const homeDeleteBtn = document.getElementById('home-delete-save-btn');
  const exists = hasSavedGame();
  if(continueBtn) continueBtn.style.display = exists ? 'block' : 'none';
  if(deleteBtn) deleteBtn.style.display = exists ? 'block' : 'none';
  if(homeContinueBtn) homeContinueBtn.style.display = exists ? 'block' : 'none';
  if(homeDeleteBtn) homeDeleteBtn.style.display = exists ? 'block' : 'none';
}

function getSavedGameMeta(){
  return readSavedGamePayload(SAVE_KEY);
}

function readSavedGamePayload(key=SAVE_KEY){
  let raw = null;
  try{ raw = localStorage.getItem(key); }catch(e){}
  if(!raw) return null;
  try{ return JSON.parse(raw); }catch(e){ return null; }
}

function isValidSavedGamePayload(data){
  return !!(data && typeof data === 'object' && Array.isArray(data.sceneQueue) && data.sceneQueue.length && data.stats && typeof data.stats === 'object');
}

function getRecoverySavePayload(){
  const backup = readSavedGamePayload(SAVE_BACKUP_KEY);
  if(isValidSavedGamePayload(backup)) return {data:backup, source:SAVE_BACKUP_KEY};
  const recovery = readSavedGamePayload(SAVE_RECOVERY_KEY);
  if(isValidSavedGamePayload(recovery)) return {data:recovery, source:SAVE_RECOVERY_KEY};
  return null;
}

function recoverSavedGame(showToast=true){
  const candidate = getRecoverySavePayload();
  if(!candidate){
    if(showToast) showNotif('!','Kurtarma Kaydi Yok','Gecerli bir otomatik yedek bulunamadi.');
    return false;
  }
  try{
    localStorage.setItem(SAVE_KEY, JSON.stringify(candidate.data));
    refreshSaveEntryActions();
    renderSavePanel();
    if(showToast) showNotif('KURTAR','Kayit Kurtarildi',`Otomatik yedek geri getirildi: ${formatSaveTime(candidate.data.savedAt)}`);
    return true;
  }catch(e){
    if(typeof recordReleaseDiagnostic === 'function') recordReleaseDiagnostic('save_recovery_error', e);
    if(showToast) showNotif('!','Kurtarma Basarisiz','Yedek geri yuklenemedi.');
    return false;
  }
}

function formatSaveTime(iso){
  if(!iso) return t('save.noSave','Kayit yok');
  try{
    const locales={tr:'tr-TR',en:'en-US',es:'es-ES',de:'de-DE',fr:'fr-FR',ru:'ru-RU',zh:'zh-CN'};
    return new Date(iso).toLocaleString(locales[gameLanguage] || 'tr-TR', {dateStyle:'short', timeStyle:'short'});
  }catch(e){
    return iso;
  }
}

function toggleSavePanel(force){
  savePanelOpen = typeof force === 'boolean' ? force : !savePanelOpen;
  if(savePanelOpen) toggleGameSettings(false);
  const panel = document.getElementById('save-panel');
  if(panel) panel.classList.toggle('show', savePanelOpen);
  renderSavePanel();
}

function toggleGameSettings(force){
  gameSettingsOpen = typeof force === 'boolean' ? force : !gameSettingsOpen;
  if(gameSettingsOpen) savePanelOpen = false;
  const panel = document.getElementById('game-settings-panel');
  const savePanel = document.getElementById('save-panel');
  if(savePanel) savePanel.classList.toggle('show', false);
  if(panel) panel.classList.toggle('show', gameSettingsOpen);
  if(gameSettingsOpen){
    moreToolsOpen = false;
    document.getElementById('more-tools-panel')?.classList.remove('show');
    renderPlayModeSelector();
    renderAudioMixer();
    applyLanguageUI();
    syncCleanHudControls();
  }
}

function exitToHomeFromGame(){
  const saved = saveGameState(false);
  clearSceneChoiceTimer();
  clearSceneAudioLoops();
  stopAllMusic();
  toggleGameSettings(false);
  toggleSavePanel(false);
  openHomeScreen();
  showNotif('MENU','Ana Menu', saved ? 'Oyun kaydedildi; ana menuye dondun.' : 'Ana menuye dondun.');
}

function renderSavePanel(){
  const grid = document.getElementById('save-panel-grid');
  const summary = document.getElementById('save-panel-summary');
  if(!grid) return;
  const meta = getSavedGameMeta();
  const recovery = getRecoverySavePayload();
  if(summary){
    summary.textContent = meta
      ? `${translateGameText('Son kayit')}: ${formatSaveTime(meta.savedAt)} · ${translateGameText('Sahne')} ${(meta.currentIdx||0)+1}`
      : t('save.noSave','Henuz kayit alinmadi');
  }
  const currentScene = sceneQueue?.length ? `${currentIdx+1}/${sceneQueue.length}` : t('save.notStarted','Baslamadi');
  const modeLabel = getModeLabel(gameplayMode);
  const savedMode = meta?.gameplayMode && PLAY_MODE_DEFS[meta.gameplayMode] ? getModeLabel(meta.gameplayMode) : translateGameText('Yok');
  grid.innerHTML = `
    <div class="save-card"><b>${t('save.current','Mevcut Oyun')}</b><small>${phoneSafe(pn || t('role.cadet','Stajyer'))} · ${phoneSafe(sn || translateGameText('Gemi'))}<br>${translateGameText('Sahne')} ${currentScene}<br>${phoneSafe(modeLabel)} ${translateGameText('mod')}</small></div>
    <div class="save-card"><b>${t('save.contract','Kontrat')}</b><small>${contractDays || 0}/${contractTotal || 0} ${translateGameText('sahne')}<br>${phoneSafe(translateGameText(getRankName ? getRankName() : 'Stajyer'))}<br>${phoneSafe(selYear)} · ${phoneSafe(selType)}</small></div>
    <div class="save-card"><b>${t('save.last','Son Kayit')}</b><small>${formatSaveTime(meta?.savedAt)}<br>${meta ? phoneSafe(meta.sn || translateGameText('Kayitli gemi')) : translateGameText('Kayit yok')}<br>${t('ui.mode','Mod')}: ${phoneSafe(savedMode)}</small></div>
    <div class="save-card save-actions"><b>${t('save.actions','Islemler')}</b><button class="save-action-btn primary" onclick="saveGameState(true)">${t('save.saveGame','Oyunu Kaydet')}</button><button class="save-action-btn" onclick="loadSavedGame()">${t('save.loadGame','Kayittan Devam')}</button><button class="save-action-btn" onclick="recoverSavedGame()">${translateGameText('Otomatik Yedegi Kurtar')}${recovery ? ` · ${formatSaveTime(recovery.data.savedAt)}` : ''}</button><button class="save-action-btn" onclick="exportSaveBackup()">${translateGameText('Kaydi Disa Aktar')}</button><button class="save-action-btn" onclick="triggerSaveImport()">${translateGameText('Kaydi Ice Aktar')}</button><button class="save-action-btn danger" onclick="deleteSavedGame()">${t('save.deleteGame','Kaydi Sil')}</button></div>`;
}

