function openMap(){
  if(!canUseFeature('map')) return;
  completeMissionFromFeature('map');
  document.getElementById('map-panel').classList.add('show');
  renderMap();
}
function closeMap(){ document.getElementById('map-panel').classList.remove('show'); }
function setMapView(view){
  mapView = view;
  renderMap();
}
function selectPortChart(name){
  selectedPortChart = name;
  mapRouteDraftPoints = [];
  portChartZoom = Math.max(portChartZoom || 1, 1.18);
  if(mapView !== 'library') mapView = 'library';
  invalidateMapRenderCache('port');
  renderMap();
}
function adjustPortChartZoom(delta){
  const beforeBucket = getPortChartDetailBucket();
  portChartZoom = Math.max(1, Math.min(6, +(portChartZoom + delta).toFixed(2)));
  const afterBucket = getPortChartDetailBucket();
  if(mapView === 'library'){
    if(beforeBucket === afterBucket){
      fastUpdatePortChartViewport();
    }else{
      invalidateMapRenderCache('port');
      renderMapLibrary();
    }
  }
}

function autoOpenVoyageChart(sc){
  if(!sc?.voyageRouteKey) return;
  if(!canUseFeature('map', sc, false)) return;
  const route = getActiveVoyageRoute();
  const wp = route?.waypoints?.[sc.voyageWpIndex || 0];
  if(!wp) return;
  selectedPortChart = wp.chart || route.chart || selectedPortChart;
  mapView = 'library';
  portChartZoom = Math.max(portChartZoom || 1, 1.18);
  const sceneKey = `${sc.id}-${selectedPortChart}`;
  if(lastAutoVoyageChartScene !== sceneKey){
    lastAutoVoyageChartScene = sceneKey;
    document.getElementById('map-panel')?.classList.add('show');
    showNotif('ECDIS','Chart otomatik yuklendi',`${selectedPortChart} · ${wp.name}`);
  }
  renderMap();
}

function getActivePortChart(){
  return getPortChartByName(selectedPortChart);
}

function getPortChartEffectiveZoom(){
  const active = getActivePortChart();
  if(!active) return Math.max(1, portChartZoom || 1);
  const profile = getPortChartProfile(active);
  const baseZoom = profile.template === 'oceanroute' ? 0.72 : /strait|canal/.test(profile.template) ? 0.82 : 0.92;
  return Math.max(baseZoom, +(baseZoom * Math.max(1, portChartZoom || 1)).toFixed(3));
}

function getPortChartDetailLabel(){
  const zoom = getPortChartEffectiveZoom();
  return zoom >= 3.2 ? 'Close Detail'
    : zoom >= 1.7 ? 'Approach Detail'
    : 'ECDIS Overview';
}

const MAP_ECDIS_DETAIL_POLICY = {
  overview:{label:'ECDIS Overview', objects:'route line, coastline, TSS and main hazards', hint:'Uzak zoomda chart sade kalir; once rota ve genel emniyet alanini oku.'},
  approach:{label:'Approach Detail', objects:'pilot station, berth approach, reporting point, soundings', hint:'Yaklasma zoomunda pilot/VTS/UKC ve approach channel ayrintisi acilir.'},
  close:{label:'Close Detail', objects:'soundings, buoys, notes, cables, no anchoring, sector lights', hint:'Yakin zoomda sounding, buoy, note ve no-go ayrintilari gorunur; gorev tiklamasi burada daha net olur.'}
};

function getPortChartDetailBucket(){
  const zoom = getPortChartEffectiveZoom();
  return zoom >= 3.2 ? 'close' : zoom >= 1.7 ? 'approach' : 'overview';
}

function getMapEcdisPerformanceProfile(){
  const bucket = getPortChartDetailBucket();
  const policy = MAP_ECDIS_DETAIL_POLICY[bucket] || MAP_ECDIS_DETAIL_POLICY.overview;
  return {
    bucket,
    label:policy.label,
    objects:policy.objects,
    hint:policy.hint,
    zoom:getPortChartEffectiveZoom(),
    renderMode:bucket === 'close' ? 'full-detail' : bucket === 'approach' ? 'approach-layered' : 'overview-fast'
  };
}

function getWorldMapDetailBucket(){
  return worldMapZoom >= 2.15 ? 'close' : worldMapZoom >= 1.45 ? 'approach' : 'overview';
}

function invalidateMapRenderCache(scope='all'){
  if(scope === 'all' || scope === 'world'){
    mapRenderCache.worldKey = '';
    mapRenderCache.worldHtml = '';
  }
  if(scope === 'all' || scope === 'port'){
    mapRenderCache.portKey = '';
    mapRenderCache.portHtml = '';
    mapRenderCache.portMetaKey = '';
    mapRenderCache.portMetaHtml = '';
  }
  if(scope === 'all' || scope === 'files'){
    mapRenderCache.filesKey = '';
    mapRenderCache.filesHtml = '';
  }
}

function fastUpdatePortChartViewport(){
  const chartSvg = document.getElementById('port-chart-svg');
  const chartZoomLabel = document.getElementById('port-chart-zoom-label');
  const chartDetailLabel = document.getElementById('port-chart-detail-label');
  if(chartSvg){
    chartSvg.setAttribute('preserveAspectRatio', 'xMidYMid slice');
    chartSvg.setAttribute('viewBox', getPortChartViewBox());
  }
  if(chartZoomLabel) chartZoomLabel.textContent = `${Math.round(portChartZoom*100)}%`;
  if(chartDetailLabel) chartDetailLabel.textContent = getPortChartDetailLabel();
}

function fastUpdateWorldMapViewport(){
  const svg = document.getElementById('map-svg');
  if(svg){
    svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    svg.setAttribute('viewBox', getWorldMapViewBox());
  }
  updateWorldMapZoomLabel();
}

function getPortChartTaskGeometry(port){
  const region = getMapRegionByPosition(port);
  const hay = `${port.name} ${region}`.toLowerCase();
  const coastLeft = port.x < 110;
  const southFacing = port.y > 170;
  const berthX = coastLeft ? 244 : 194;
  const channelStartX = coastLeft ? 410 : 30;
  const channelEndX = coastLeft ? 238 : 202;
  const channelY = southFacing ? 150 : 126;
  const turningBasinX = coastLeft ? 206 : 234;
  const profile = getPortChartProfile(port);
  return {region,hay,coastLeft,southFacing,berthX,channelStartX,channelEndX,channelY,turningBasinX,profile};
}

function isMapTaskAllowedForPort(task, port){
  return isMapTaskKindMatch(task, port);
}

function getCurrentMapTask(){
  return MAP_TASKS[activeMapTaskIndex % MAP_TASKS.length];
}

function getMapMissionChain(){
  return MAP_MISSION_CHAINS[mapMissionChainState?.name] || MAP_MISSION_CHAINS.pilotArrival;
}

function syncMapTaskToMissionChain(){
  const chain = getMapMissionChain();
  const step = chain.steps[Math.max(0, Math.min(chain.steps.length-1, mapMissionChainState.step || 0))];
  const idx = MAP_TASKS.findIndex(task=>task.id === step?.task);
  if(idx >= 0) activeMapTaskIndex = idx;
}

function progressMapMissionChain(task, ok){
  const chain = getMapMissionChain();
  const currentStep = chain.steps[Math.max(0, Math.min(chain.steps.length-1, mapMissionChainState.step || 0))];
  if(ok && currentStep?.task === task?.id){
    mapMissionChainState.step = Math.min(chain.steps.length-1, (mapMissionChainState.step || 0) + 1);
    mapMissionChainState.last = `${task.title}: tamam`;
    syncMapTaskToMissionChain();
    addWatchFeed(`Harita zinciri: ${currentStep.label} tamamlandi. Siradaki adim: ${chain.steps[mapMissionChainState.step]?.label || 'debrief'}.`, 'good');
  }else if(!ok){
    mapMissionChainState.last = `${task?.title || 'Harita'}: tekrar`;
  }
}

function runMapTaskReplay(task, training, opts={}){
  const lines = [
    `Harita replay: ${task?.title || 'gorev'} hedefi tekrar okunuyor.`,
    opts.near ? 'Replay: hedefe yaklastin; sembol/etiket ve rota baglamina tekrar bak.' : 'Replay: yanlis bolge secildi; chart sembolu ve gorev tipi ayrildi.',
    opts.penaltyNow ? 'Replay: uc uzak deneme sonrasi kucuk egitim cezasi uygulandi.' : `Replay: ${training?.wrong || 'Neden yanlis oldugunu not et ve yeniden dene.'}`
  ];
  lines.forEach((line,i)=>sceneLiveSequenceTimers.push(setTimeout(()=>addWatchFeed(line, i===2?'warn':''), 250+i*520)));
  addLiveLogbook('HARITA REPLAY', `${task?.title || 'Harita'}: ${training?.wrong || 'tekrar egitim replayi'}`, true);
}

function renderMapMissionChainPanel(){
  const chain = getMapMissionChain();
  const stepIndex = Math.max(0, Math.min(chain.steps.length-1, mapMissionChainState.step || 0));
  const steps = chain.steps.map((step,i)=>{
    const cls = i < stepIndex ? 'done' : i === stepIndex ? 'active' : '';
    return `<span class="${cls}">${i+1}. ${phoneSafe(step.label)}</span>`;
  }).join('');
  return `<div class="map-chain-panel">
    <div class="map-chain-head">${phoneSafe(chain.title)} · ${stepIndex+1}/${chain.steps.length}</div>
    <div class="map-chain-steps">${steps}</div>
    <div class="map-chain-note">Gorevler artik tek tik degil: rota kontrolu, VHF/pilot, hiz, UKC, tug ve berth zinciri olarak ilerler.</div>
  </div>`;
}

function getMapTaskRequiredKind(task){
  if(!task) return 'port';
  if(task.chartKind === 'route') return 'route';
  if(task.chartKind === 'transit') return 'transit';
  return 'port';
}

function isMapTaskKindMatch(task, port){
  const kind = getMapTaskRequiredKind(task);
  if(!port) return false;
  if(kind === 'route') return port.kind === 'route';
  if(kind === 'transit') return port.kind !== 'port';
  return port.kind === 'port';
}

function getSheetDrilldownChartName(sheetNo, port){
  const hay = `${sheetNo || ''} ${port?.name || ''}`.toLowerCase();
  if(/293/.test(hay)) return 'Dardanel - Marmara - Bosphorus Zinciri';
  if(/294|295|canakkale|çanakkale/.test(hay)) return 'Çanakkale Bogazi';
  if(/296|adalar|gemlik/.test(hay)) return 'Gemlik';
  if(/292|291|istanbul|izmit/.test(hay)) return 'İstanbul Bogazi';
  if(/suez|sc1|sc2|sc3|rs1/.test(hay)) return 'Suveys';
  if(/pan|pc1|pc2|pc3/.test(hay)) return 'Panama Kanali';
  if(/mal|ms1|ms2|ms3|ms4|singapur|singapore/.test(hay)) return 'Singapore Strait TSS';
  if(/hom|hurmuz|hormuz/.test(hay)) return 'Hurmuz Bogazi';
  if(/dov|dover/.test(hay)) return 'Dover Bogazi';
  if(/atl/.test(hay)) return 'Kuzey Atlantik Ana Hatti';
  if(/fe/.test(hay)) return 'Malakka - Guney Cin Denizi - Japonya Hatti';
  return port?.name || selectedPortChart;
}

function getClickedChartIndexSheet(port, x, y){
  const profile = getPortChartProfile(port);
  const data = getShodbChartIndexData(port, profile);
  return (data.sheets || []).find(sheet=>{
    const inside = x >= sheet.x && x <= sheet.x + sheet.w && y >= sheet.y && y <= sheet.y + sheet.h;
    if(!inside) return false;
    const edge = Math.min(Math.abs(x-sheet.x), Math.abs(x-(sheet.x+sheet.w)), Math.abs(y-sheet.y), Math.abs(y-(sheet.y+sheet.h)));
    const nearNumber = x <= sheet.x + 30 && y <= sheet.y + 18;
    return edge <= 7 || nearNumber;
  }) || null;
}

function openChartIndexSheet(sheet, sourcePort){
  const targetName = getSheetDrilldownChartName(sheet.no, sourcePort);
  const target = getPortChartByName(targetName) || sourcePort;
  selectedPortChart = target.name;
  mapView = 'library';
  visitedPorts.add(target.name);
  portChartZoom = Math.max(portChartZoom || 1, 1.18);
  showNotif('CHART FOLIO', `${sheet.no} paftasi acildi`, `${target.name} detay chart yuklendi.`);
  addLiveLogbook('CHART FOLIO', `${sourcePort?.name || 'Atlas'} ${sheet.no} paftasindan ${target.name} chartina gecildi.`, true);
  renderMap();
}

function ensureTaskPort(task){
  const active = getPortChartByName(selectedPortChart);
  if(task?.preferredPort){
    const preferred = getPortChartByName(task.preferredPort);
    if(preferred && (!active || !isMapTaskKindMatch(task, active))){
      selectedPortChart = preferred.name;
      return;
    }
  }
  if(active && isMapTaskKindMatch(task, active)) return;
  const routeCharts = getActiveVoyageChartSet();
  const candidates = getPortChartEntries();
  const voyageMatch = candidates.find(p=>routeCharts.has(p.name) && isMapTaskKindMatch(task, p));
  const globalMatch = candidates.find(p=>isMapTaskKindMatch(task, p));
  const next = voyageMatch || globalMatch;
  if(next) selectedPortChart = next.name;
}

function nextMapTask(){
  activeMapTaskIndex = (activeMapTaskIndex + 1) % MAP_TASKS.length;
  mapRouteDraftPoints = [];
  ensureTaskPort(getCurrentMapTask());
  if(mapView !== 'library') mapView = 'library';
  renderMap();
}

function selectMapTask(index){
  activeMapTaskIndex = Math.max(0, Math.min(MAP_TASKS.length-1, Number(index) || 0));
  mapRouteDraftPoints = [];
  ensureTaskPort(getCurrentMapTask());
  if(mapView !== 'library') mapView = 'library';
  renderMap();
}

function getMapTaskAttemptKey(task, port){
  return `${task?.id || 'task'}::${port?.name || selectedPortChart || 'chart'}`;
}

function getMapTaskShortLabel(task){
  const labels = {
    pilot:'PILOT',
    anchorage:'ANCH',
    tss:'TSS',
    berth:'BERTH',
    reporting:'VTS',
    noanchoring:'NO ANC',
    alternateroute:'ALT RTE',
    waypoint:'WP',
    cpa:'CPA',
    ukc:'UKC',
    eca:'ECA',
    weatheravoid:'WX',
    cablecrossing:'CABLE',
    offshorezone:'500M'
  };
  return labels[task?.id] || (task?.title || 'TASK').slice(0,8).toUpperCase();
}

function getMapTaskChartSymbol(task){
  const symbols = {
    pilot:{code:'PILOT STN', cls:'pilot', glyph:'P'},
    anchorage:{code:'ANCHORAGE', cls:'anchor', glyph:'⚓'},
    tss:{code:'TSS FLOW', cls:'traffic', glyph:'↗'},
    berth:{code:'TURN BASIN', cls:'berth', glyph:'TB'},
    reporting:{code:'VTS REPORT', cls:'report', glyph:'R'},
    noanchoring:{code:'NO ANCH', cls:'noanchor', glyph:'⊘'},
    alternateroute:{code:'ALT ROUTE', cls:'route', glyph:'ALT'},
    waypoint:{code:'NEXT WP', cls:'waypoint', glyph:'WP'},
    cpa:{code:'CPA RISK', cls:'cpa', glyph:'CPA'},
    ukc:{code:'UKC CHECK', cls:'ukc', glyph:'UKC'},
    eca:{code:'ECA LINE', cls:'eca', glyph:'ECA'},
    weatheravoid:{code:'WX AVOID', cls:'weather', glyph:'WX'},
    cablecrossing:{code:'CABLE XING', cls:'cable', glyph:'CBL'},
    offshorezone:{code:'500 m ZONE', cls:'offshore', glyph:'500'}
  };
  return symbols[task?.id] || {code:'CHART FIX', cls:'fix', glyph:'FIX'};
}

function renderMapTaskChips(activePort){
  const holder = document.getElementById('port-chart-tasklist');
  if(!holder) return;
  const port = activePort || getPortChartByName(selectedPortChart);
  holder.innerHTML = MAP_TASKS.map((task,i)=>{
    const allowed = isMapTaskAllowedForPort(task, port);
    const cls = [
      'map-task-chip',
      i === activeMapTaskIndex ? 'active' : '',
      completedMapTasks.has(task.id) ? 'done' : '',
      allowed ? '' : 'disabled'
    ].filter(Boolean).join(' ');
    const kind = getMapTaskRequiredKind(task);
    return `<button class="${cls}" onclick="selectMapTask(${i})" title="${task.title}">${getMapTaskShortLabel(task)}<small>${kind}</small></button>`;
  }).join('');
}

function getMapTaskTarget(task, port){
  const geo = getPortChartTaskGeometry(port);
  if(task.id === 'reporting') return {x: geo.coastLeft ? 356 : 88, y: geo.channelY - 46, tol: 48, label:'REPORTING / VTS'};
  if(task.id === 'noanchoring') return {x: geo.coastLeft ? 282 : 158, y: geo.southFacing ? 196 : 194, tol: 50, label:'NO ANCHORING'};
  if(task.id === 'alternateroute') return {x: 256, y: 158, tol: 62, label:'ALTERNATE ROUTE'};
  if(task.id === 'waypoint') return {x: 274, y: 136, tol: 48, label:'NEXT WAYPOINT / WOP'};
  if(task.id === 'cpa') return {x: 302, y: 104, tol: 48, label:'CPA / CROSSING TARGET'};
  if(task.id === 'ukc') return {x: geo.coastLeft ? 292 : 148, y: geo.channelY + 34, tol: 46, label:'UKC / SQUAT CHECK'};
  if(task.id === 'eca') return {x: 226, y: 88, tol: 54, label:'ECA / CHANGE-OVER'};
  if(task.id === 'weatheravoid') return {x: 224, y: 174, tol: 62, label:'WEATHER AVOIDANCE'};
  if(task.id === 'cablecrossing') return {x: geo.coastLeft ? 286 : 154, y: 184, tol: 48, label:'CABLE / PIPELINE'};
  if(task.id === 'offshorezone') return {x: 300, y: 142, tol: 56, label:'500 m SAFETY ZONE'};
  if(task.id === 'pilot') return {x: geo.coastLeft ? 330 : 112, y: geo.southFacing ? 92 : 178, tol: 52, label:'PILOT BOARDING'};
  if(task.id === 'anchorage') return {x: geo.coastLeft ? 180 : 260, y: 210, tol: 50, label:'ANCHORAGE'};
  if(task.id === 'tss') return {x: geo.coastLeft ? 356 : 88, y: geo.channelY - 46, tol: 52, label:'TSS / TRAFFIC FLOW'};
  if(task.id === 'berth') return {x: geo.turningBasinX, y: geo.channelY, tol: 48, label:'TURN / BERTH APPROACH'};
  return {x: geo.channelEndX, y: geo.channelY, tol: 42, label:'TARGET'};
}

function getMapTaskEffectiveTolerance(task, target){
  const base = Number(target?.tol || 44);
  const typeBoost = task?.id === 'alternateroute' || task?.id === 'weatheravoid' ? 6 : 0;
  const zoom = Math.max(1, getPortChartEffectiveZoom?.() || 1);
  const overviewBoost = zoom < 1.45 ? 8 : zoom < 2 ? 4 : 0;
  return Math.max(44, Math.min(72, base + typeBoost + overviewBoost));
}

function getSvgClickPoint(svg, ev){
  if(svg?.createSVGPoint && svg.getScreenCTM()){
    const pt = svg.createSVGPoint();
    pt.x = ev.clientX;
    pt.y = ev.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }
  const rect = svg.getBoundingClientRect();
  const vb = svg.viewBox.baseVal;
  return {
    x: vb.x + ((ev.clientX - rect.left) / rect.width) * vb.width,
    y: vb.y + ((ev.clientY - rect.top) / rect.height) * vb.height
  };
}

function buildMapTaskTargetOverlay(port){
  const task = getCurrentMapTask();
  if(!isMapTaskAllowedForPort(task, port)) return '';
  const target = getMapTaskTarget(task, port);
  const tx = Math.max(34, Math.min(406, target.x));
  const ty = Math.max(34, Math.min(226, target.y));
  const labelW = 132;
  const labelX = Math.max(18, Math.min(440 - labelW - 8, tx > 260 ? tx - labelW - 22 : tx + 22));
  const labelY = Math.max(24, Math.min(238, ty < 58 ? ty + 42 : ty - 28));
  const rayStartX = tx > labelX ? labelX + labelW : labelX;
  const rayEndX = tx > labelX ? tx - 12 : tx + 12;
  const symbol = getMapTaskChartSymbol(task);
  const touchTol = getMapTaskEffectiveTolerance(task, target);
  const tol = Math.min(54, Math.max(28, touchTol * .78));
  return `
    <g class="map-task-target chart-task-${symbol.cls}" data-task="${task.id}" data-x="${target.x}" data-y="${target.y}">
      <circle class="map-task-touch-area" cx="${tx}" cy="${ty}" r="${touchTol}"/>
      <circle class="map-task-cursor" cx="${tx}" cy="${ty}" r="${tol}" fill="rgba(255,205,79,.06)" stroke="#ffc94d" stroke-width="1.45" stroke-dasharray="2.6,3.2"/>
      <circle class="map-task-bearing" cx="${tx}" cy="${ty}" r="${Math.max(10, tol*.42)}" fill="none" stroke="rgba(129,247,184,.78)" stroke-width=".9" stroke-dasharray="1.5,2.2"/>
      <path class="map-task-crosshair" d="M${tx-12} ${ty} H${tx+12} M${tx} ${ty-12} V${ty+12}" stroke="#e8f6fb" stroke-width=".95"/>
      <rect class="map-task-symbol-plate" x="${tx-12}" y="${ty-9}" width="24" height="18" rx="4"/>
      <text class="map-task-symbol-text" x="${tx}" y="${ty+3.5}" text-anchor="middle">${symbol.glyph}</text>
      <path class="map-task-leader" d="M${rayStartX} ${labelY-6} L${rayEndX} ${ty}" />
      <rect class="map-task-callout" x="${labelX}" y="${labelY-25}" width="${labelW}" height="35" rx="6"/>
      <text class="map-task-code" x="${labelX+8}" y="${labelY-11}">${symbol.code}</text>
      <text class="map-task-name" x="${labelX+8}" y="${labelY+2}">${target.label || task.title}</text>
    </g>`;
}

function getMapTaskTargetLabelBox(target){
  const tx = Math.max(34, Math.min(406, target.x));
  const ty = Math.max(34, Math.min(226, target.y));
  const labelW = 132;
  const labelX = Math.max(18, Math.min(440 - labelW - 8, tx > 260 ? tx - labelW - 22 : tx + 22));
  const labelY = Math.max(24, Math.min(238, ty < 58 ? ty + 42 : ty - 28));
  return {
    x: labelX - 8,
    y: labelY - 31,
    w: labelW + 16,
    h: 47
  };
}

function isInsideMapTaskTargetLabel(x, y, target){
  const box = getMapTaskTargetLabelBox(target);
  return x >= box.x && x <= box.x + box.w && y >= box.y && y <= box.y + box.h;
}

function isInsideVisibleHitbox(x, y, boxes){
  return (boxes || []).some(box => x >= box.x && x <= box.x + box.w && y >= box.y && y <= box.y + box.h);
}

function getMapTaskVisibleHitboxes(target){
  const tx = Math.max(34, Math.min(406, target.x));
  const ty = Math.max(34, Math.min(226, target.y));
  const r = getMapTaskEffectiveTolerance(getCurrentMapTask(), target);
  return [
    {x:tx-r, y:ty-r, w:r*2, h:r*2, type:'target-ring'},
    {...getMapTaskTargetLabelBox(target), type:'target-label'}
  ];
}

function normalizeClickableSurface(selector='button,[role="button"],.interaction-hotspot,.map-task-target,.device-key,.device-tab,.document-practice-tabs button,.charter-options button'){
  document.querySelectorAll(selector).forEach(el=>{
    el.classList.add('hitbox-standard');
    if(!el.getAttribute('aria-label') && el.textContent?.trim()) el.setAttribute('aria-label', el.textContent.trim().replace(/\s+/g,' '));
  });
}

function showMapTapFeedback(svg, x, y, state='near', label='SECIM ALINDI'){
  if(!svg) return;
  lastMapTapFeedbackId += 1;
  const id = lastMapTapFeedbackId;
  const fx = Math.max(28, Math.min(412, Number(x) || 220));
  const fy = Math.max(28, Math.min(232, Number(y) || 130));
  const safeLabel = phoneSafe(String(label || 'SECIM ALINDI').slice(0, 28));
  svg.querySelectorAll('.map-touch-feedback').forEach(el=>el.remove());
  const labelX = Math.max(10, Math.min(326, fx + 12));
  const labelY = Math.max(20, Math.min(246, fy - 12));
  const markup = `<g class="map-touch-feedback ${state}" data-id="${id}" style="transform-box:fill-box;transform-origin:center;">
    <circle cx="${fx}" cy="${fy}" r="13" fill="rgba(255,255,255,.025)" stroke-width="1.4"/>
    <circle cx="${fx}" cy="${fy}" r="24" fill="none" stroke-width="1"/>
    <rect x="${labelX}" y="${labelY-13}" width="104" height="20" rx="5"/>
    <text x="${labelX+8}" y="${labelY}">${safeLabel}</text>
  </g>`;
  svg.insertAdjacentHTML('beforeend', markup);
  window.setTimeout(()=>{
    const el = svg.querySelector(`.map-touch-feedback[data-id="${id}"]`);
    if(el) el.remove();
  }, 1350);
}

function focusCurrentMapTask(){
  mapView = 'library';
  let task = getCurrentMapTask();
  ensureTaskPort(task);
  const port = ensureSelectedPortChart();
  task = getCurrentMapTask();
  if(!task || !port) return;
  if(!isMapTaskAllowedForPort(task, port)){
    ensureTaskPort(task);
    renderMap();
    return;
  }
  const target = getMapTaskTarget(task, port);
  const beforeBucket = getPortChartDetailBucket();
  portChartZoom = Math.max(portChartZoom || 1, 2.1);
  const zoom = getPortChartEffectiveZoom();
  const width = 440 / zoom;
  const height = 260 / zoom;
  const next = clampPortChartPan(target.x - width / 2, target.y - height / 2);
  portChartPanX = +next.x.toFixed(2);
  portChartPanY = +next.y.toFixed(2);
  if(beforeBucket !== getPortChartDetailBucket()) invalidateMapRenderCache('port');
  renderMap();
  const svg = document.getElementById('port-chart-svg');
  showMapTapFeedback(svg, target.x, target.y, 'near', 'GOREV BOLGESI');
  const status = document.getElementById('port-chart-taskstatus');
  if(status){
    status.className = 'warn';
    status.textContent = `${target.label || task.title} bolgesi merkeze alindi. Sembol, rota ve derinlik iliskisini kontrol ederek sec.`;
  }
}

function getMapTaskReadingCue(task, port){
  const training = getMapTaskTraining(task?.id);
  const target = task && port ? getMapTaskTarget(task, port) : null;
  const cueByTask = {
    pilot:'Pilot boarding point genelde fairway disinda, pilot ladder/speed azaltma zincirinden once aranir.',
    anchorage:'Demir yeri icin derinlik, no-anchoring notu, trafik ayrim duzeni ve lee/swell etkisini birlikte oku.',
    tss:'TSS icin trafik yon oklarini, separation zone sinirini ve crossing acisini kontrol et.',
    berth:'Berth approach icin turning basin, tug plan ve final heading noktasini birlikte oku.',
    reporting:'Reporting/VTS noktasi kanal bilgisiyle birlikte rota uzerinde veya gecit girisinde aranir.',
    waypoint:'Next waypoint icin rota bacagi, XTD limiti ve wheel-over noktasini kontrol et.',
    cpa:'CPA gorevinde hedef sembolu, vektor yonu ve kendi gemi rotasi ayni anda okunur.',
    ukc:'UKC gorevinde safety contour, draft, squat ve en dusuk derinlik ayni karara baglanir.',
    eca:'ECA/change-over cizgisi yakit gecis plani ve logbook notuyla birlikte okunur.',
    weatheravoid:'Weather routing icin rota bacaklarini swell/low pressure alanindan uzak tut.',
    cablecrossing:'Kablo/boru gecisi demirleme yasagi, izin ve chart notlariyla birlikte okunur.',
    offshorezone:'Offshore 500 m zone platform etrafindaki izin/abort point halkasidir.'
  };
  const cue = cueByTask[task?.id] || training.focus;
  const targetLabel = target?.label || task?.title || 'chart target';
  return `<div class="map-reading-cue"><i>ENC</i><span><b>${phoneSafe(targetLabel)}</b><br>${phoneSafe(cue)} ${phoneSafe(training.focus)}</span></div>`;
}

function updateMapTaskBox(port){
  const task = getCurrentMapTask();
  ensureTaskPort(task);
  const title = document.getElementById('port-chart-tasktitle');
  const desc = document.getElementById('port-chart-taskdesc');
  const status = document.getElementById('port-chart-taskstatus');
  const btn = document.getElementById('port-task-next');
  if(!title || !desc || !status) return;
  const effectivePort = getPortChartByName(selectedPortChart) || port;
  renderMapTaskChips(effectivePort);
  const taskAllowed = isMapTaskAllowedForPort(task, effectivePort);
  if(!taskAllowed){
    title.textContent = `${effectivePort?.name || 'Chart'} · Stratejik Gecit`;
    desc.textContent = effectivePort?.kind === 'port'
      ? 'Bu gorev transit veya okyanus rota charti ister. Liman gorevleri icin pilot, anchorage veya berth gorevini sec.'
      : 'Bu gorev liman plani ister. Stratejik chartlarda reporting point, no anchoring veya alternatif rota gorevlerini kullan.';
    status.className = 'warn';
    status.textContent = 'Bu gorev farkli chart ister. Oyun uygun haritayi otomatik acmaya calisir; gerekirse soldaki chart listesinden ayni tip bir harita sec.';
    if(btn) btn.textContent = activeMapTaskIndex === MAP_TASKS.length-1 ? 'Basa Don' : 'Sonraki';
    return;
  }
  title.textContent = `${task.title} · ${effectivePort?.name || ''}`;
  const training = getMapTaskTraining(task.id);
  desc.innerHTML = `${renderMapMissionChainPanel()}${getMapTaskReadingCue(task, effectivePort)}<div>${phoneSafe(task.desc)} Egitim odagi: ${phoneSafe(training.focus)}${task.preferredPort && effectivePort?.name===task.preferredPort ? ` Bu tur ${phoneSafe(effectivePort.name)} charti uzerindesin.` : ''}</div>`;
  status.className = '';
  const target = getMapTaskTarget(task, effectivePort);
  status.textContent = completedMapTasks.has(task.id) ? 'Tamamlandi. Istersen sonraki goreve gecebilirsin.' : `${target.label || task.title} halkasini haritada bul ve isaretle.`;
  if(btn) btn.textContent = activeMapTaskIndex === MAP_TASKS.length-1 ? 'Basa Don' : 'Sonraki';
}

function handlePortChartTaskClick(svg, ev, port){
  const task = getCurrentMapTask();
  if(!task || !port) return;
  if(portChartDidPan){
    portChartDidPan = false;
    return;
  }
  const {x, y} = getSvgClickPoint(svg, ev);
  const sheet = getClickedChartIndexSheet(port, x, y);
  if(sheet){
    showMapTapFeedback(svg, x, y, 'near', 'PAFTA ACILIYOR');
    openChartIndexSheet(sheet, port);
    return;
  }
  const allowed = isMapTaskAllowedForPort(task, port);
  if(!allowed){
    showMapTapFeedback(svg, x, y, 'near', 'CHART DEGISIYOR');
    const status = document.getElementById('port-chart-taskstatus');
    const before = selectedPortChart;
    ensureTaskPort(task);
    if(status){
      status.className = 'warn';
      status.textContent = before !== selectedPortChart
        ? `${task.title} icin uygun chart aciliyor: ${selectedPortChart}.`
        : 'Bu gorev farkli chart ister. Soldaki listeden gorev tipine uygun chart sec veya Sonraki goreve gec.';
    }
    if(before !== selectedPortChart) renderMap();
    return;
  }
  const target = getMapTaskTarget(task, port);
  const status = document.getElementById('port-chart-taskstatus');
  if(task.id === 'alternateroute'){
    mapRouteDraftPoints.push({x:+x.toFixed(1), y:+y.toFixed(1)});
    showMapTapFeedback(svg, x, y, 'near', `ROTA NOKTASI ${mapRouteDraftPoints.length}`);
    renderMapRouteDraftOverlay(svg);
    if(mapRouteDraftPoints.length >= 3 || Math.hypot(x-target.x, y-target.y) <= getMapTaskEffectiveTolerance(task, target)){
      const alreadyDone = completedMapTasks.has(task.id);
      completedMapTasks.add(task.id);
      progressMapMissionChain(task, true);
      if(!alreadyDone){
        awardMetaXp(14, `Harita gorevi: ${task.title}`, 'map');
        progressRetentionMission('map', {taskId:task.id});
        progressFirstFiveStep('map');
      }
      if(status){
        status.className = '';
        status.textContent = 'Alternatif rota cizildi. Hava routing / ECA / risk alanini dikkate alan hat kabul edildi.';
      }
      addJournalEntry(`[HARITA GOREVI] Alternatif rota cizildi (${port.name}).`, 'Harita', '--:--');
    }else if(status){
      status.className = 'warn';
      status.textContent = `${mapRouteDraftPoints.length}. rota noktasi alindi. En az 3 nokta veya uygun alternatif hat bolgesi sec.`;
    }
    return;
  }
  if(['waypoint','cpa','eca','weatheravoid','offshorezone'].includes(task.id) && task.chartKind === 'route'){
    mapRouteDraftPoints.push({x:+x.toFixed(1), y:+y.toFixed(1)});
    renderMapRouteDraftOverlay(svg);
  }
  const dist = Math.hypot(x-target.x, y-target.y);
  const labelHit = isInsideMapTaskTargetLabel(x, y, target);
  const visibleHit = isInsideVisibleHitbox(x, y, getMapTaskVisibleHitboxes(target));
  const touchTol = getMapTaskEffectiveTolerance(task, target);
  if(dist <= touchTol || labelHit || visibleHit){
    showMapTapFeedback(svg, x, y, 'good', 'SECIM OK');
    const alreadyDone = completedMapTasks.has(task.id);
    completedMapTasks.add(task.id);
    mapTaskWrongAttempts[getMapTaskAttemptKey(task, port)] = 0;
    progressMapMissionChain(task, true);
    const training = getMapTaskTraining(task.id);
    if(status){
      status.className = '';
      status.textContent = `Dogru secim. ${training.correct}`;
    }
    completeMissionStep('map', 'Harita gorevi tamamlandi');
    queueWalkMission('map', `Harita gorevi tamamlandi: ${task.title}`);
    applyEffect({bilgi:2,sayginlik:1},{skipContractTick:true});
    if(!alreadyDone){
      awardMetaXp(14, `Harita gorevi: ${task.title}`, 'map');
      progressRetentionMission('map', {taskId:task.id});
      progressFirstFiveStep('map');
    }
    addJournalEntry(`[HARITA GOREVI] ${task.title} basariyla tamamlandi (${port.name}).`, 'Harita', '--:--');
    addLiveLogbook('HARITA EGITIMI', `${task.title}: ${training.correct}`, true);
  }else if(status){
    const near = dist <= touchTol * 1.85;
    showMapTapFeedback(svg, x, y, near ? 'near' : 'bad', near ? 'YAKLASTIN' : 'YANLIS BOLGE');
    const training = getMapTaskTraining(task.id);
    const attemptKey = getMapTaskAttemptKey(task, port);
    const wrongCount = near ? 0 : ((mapTaskWrongAttempts[attemptKey] || 0) + 1);
    mapTaskWrongAttempts[attemptKey] = wrongCount;
    const penaltyNow = !near && wrongCount >= 3 && wrongCount % 3 === 0;
    status.className = near ? 'warn' : 'bad';
    const retryText = near
      ? `Yaklastin. ${training.focus} Bilgi cezasi yok; sembol/derinlik/rota iliskisini tekrar kontrol et.`
      : penaltyNow
        ? `Hedef bu degil. ${training.wrong} Uc uzak denemeden sonra sadece -1 bilgi egitim cezasi uygulandi.`
        : `Hedef bu degil. ${training.wrong} Ceza yok; ${Math.max(0, 3-wrongCount)} uzak deneme sonra kucuk egitim cezasi gelir.`;
    status.innerHTML = `${phoneSafe(retryText)} <button class="map-retry-btn" onclick="ensureTaskPort(getCurrentMapTask()); renderMap();">Dogru charti ac / tekrar dene</button>`;
    addWatchFeed(`Harita egitimi: ${near?'yaklastin':'yanlis bolge'} - ${training.focus || training.wrong}`, near?'warn':'');
    queueWalkMission('map', `Harita tekrar: ${task.title}`);
    if(penaltyNow){
      applyEffect({bilgi:-1},{skipContractTick:true});
      addLiveLogbook('HARITA HATASI', `${task.title}: ${training.wrong}`, true);
    }
    progressMapMissionChain(task, false);
    runMapTaskReplay(task, training, {near, penaltyNow});
  }
}

function clampPortChartPan(panX, panY){
  const baseW = 440, baseH = 260;
  const zoom = getPortChartEffectiveZoom();
  const width = baseW / zoom;
  const height = baseH / zoom;
  const maxX = Math.max(0, baseW - width);
  const maxY = Math.max(0, baseH - height);
  return {
    x: Math.max(0, Math.min(maxX, panX)),
    y: Math.max(0, Math.min(maxY, panY))
  };
}

function getPortChartViewBox(){
  const baseW = 440, baseH = 260;
  const zoom = getPortChartEffectiveZoom();
  const width = +(baseW / zoom).toFixed(2);
  const height = +(baseH / zoom).toFixed(2);
  const centeredX = (baseW - width) / 2;
  const centeredY = (baseH - height) / 2;
  const safePan = clampPortChartPan(
    portChartPanX == null ? centeredX : portChartPanX,
    portChartPanY == null ? centeredY : portChartPanY
  );
  portChartPanX = +safePan.x.toFixed(2);
  portChartPanY = +safePan.y.toFixed(2);
  const x = portChartPanX;
  const y = portChartPanY;
  return `${x} ${y} ${width} ${height}`;
}

function initPortChartInteractions(svg){
  if(!svg || svg.dataset.panBound === '1') return;
  svg.dataset.panBound = '1';
  const stopDrag = ()=>{
    portChartDragState = null;
    svg.classList.remove('dragging');
  };
  svg.addEventListener('pointerdown',ev=>{
    if((portChartZoom||1) <= 1) return;
    portChartDidPan = false;
    const rect = svg.getBoundingClientRect();
    const vb = svg.viewBox.baseVal;
    portChartDragState = {
      startX: ev.clientX,
      startY: ev.clientY,
      startPanX: portChartPanX == null ? vb.x : portChartPanX,
      startPanY: portChartPanY == null ? vb.y : portChartPanY,
      scaleX: vb.width / rect.width,
      scaleY: vb.height / rect.height
    };
    svg.classList.add('dragging');
    if(svg.setPointerCapture) svg.setPointerCapture(ev.pointerId);
  });
  svg.addEventListener('pointermove',ev=>{
    if(!portChartDragState) return;
    if(Math.abs(ev.clientX - portChartDragState.startX) > 3 || Math.abs(ev.clientY - portChartDragState.startY) > 3) portChartDidPan = true;
    const dx = (ev.clientX - portChartDragState.startX) * portChartDragState.scaleX;
    const dy = (ev.clientY - portChartDragState.startY) * portChartDragState.scaleY;
    const next = clampPortChartPan(
      portChartDragState.startPanX - dx,
      portChartDragState.startPanY - dy
    );
    portChartPanX = +next.x.toFixed(2);
    portChartPanY = +next.y.toFixed(2);
    svg.setAttribute('viewBox', getPortChartViewBox());
  });
  svg.addEventListener('pointerup',stopDrag);
  svg.addEventListener('pointercancel',stopDrag);
  svg.addEventListener('pointerleave',ev=>{
    if(portChartDragState && ev.buttons === 0) stopDrag();
  });
}

function getMapRegionByPosition(pos){
  return pos.x >= 405 ? 'KUZEY PASIFIK / JAPONYA'
    : pos.x >= 372 ? 'DOGU ASYA'
    : pos.x >= 330 && pos.y < 190 ? 'GUNEYDOGU ASYA'
    : pos.x >= 320 ? 'BASRA KORFEZI / ARAP DENIZI'
    : pos.x >= 245 ? 'KIZILDENIZ / HINT OKYANUSU GIRISI'
    : pos.x < 70 && pos.y > 220 ? 'GUNEY AMERIKA'
    : pos.x < 70 && pos.y > 120 ? 'AMERIKA / KARAYIPLER'
    : pos.x < 70 && pos.y <= 120 ? 'ATLANTIK / BATI AVRUPA'
    : (pos.y <= 22 || (pos.x < 95 && pos.y < 30)) ? 'KUZEY DENIZI / BALTIK'
    : pos.y < 62 && pos.x >= 180 ? 'KARADENIZ / AZAK'
    : pos.y < 88 && pos.x >= 120 ? 'TURK BOGAZLARI / ADRIYATIK'
    : pos.x < 150 ? 'ORTA AKDENIZ'
    : 'DOGU AKDENIZ';
}

function getPortChartEntries(){
  const route = getActiveVoyageRoute();
  const activeCharts = new Set([route?.chart, ...(route?.charts || []), ...(route?.waypoints || []).map(w=>w.chart)].filter(Boolean));
  const known = new Set(ROUTE_PORTS.map(p=>p.name));
  const synthetic = getSyntheticVoyageChartEntries().filter(p=>!known.has(p.name));
  const atlas = getWorldAtlasChartEntries().filter(p=>!known.has(p.name) && !synthetic.some(s=>s.name===p.name));
  return ROUTE_PORTS.concat(synthetic, atlas)
    .filter(p=>['port','waterway','route'].includes(p.kind))
    .slice()
    .sort((a,b)=>{
      const av = activeCharts.has(a.name) ? 0 : visitedPorts.has(a.name) ? 1 : 2;
      const bv = activeCharts.has(b.name) ? 0 : visitedPorts.has(b.name) ? 1 : 2;
      if(av !== bv) return av - bv;
      const order = kind => kind==='port' ? 0 : kind==='waterway' ? 1 : 2;
      const ak = order(a.kind);
      const bk = order(b.kind);
      if(ak !== bk) return ak - bk;
      return a.name.localeCompare(b.name,'tr');
    });
}

function getSyntheticVoyageChartEntries(){
  const out = new Map();
  (TRADE_VOYAGE_ROUTES || []).forEach((route, routeIndex)=>{
    const names = [route.chart, ...(route.charts || []), ...(route.waypoints || []).map(w=>w.chart)].filter(Boolean);
    names.forEach((name, nameIndex)=>{
      if(out.has(name) || ROUTE_PORTS.some(p=>p.name===name)) return;
      const pts = (route.waypoints || []).filter(w=>w.chart === name || name === route.chart || (route.charts || []).includes(name));
      const sourcePts = pts.length ? pts : (route.waypoints || []);
      const avg = sourcePts.reduce((acc,p)=>({x:acc.x+(Number(p.x)||220), y:acc.y+(Number(p.y)||130)}), {x:0,y:0});
      const div = Math.max(1, sourcePts.length);
      out.set(name, {
        name,
        x:+Math.max(8, Math.min(432, avg.x / div + (nameIndex%3-1)*7)).toFixed(1),
        y:+Math.max(12, Math.min(248, avg.y / div + (routeIndex%4-1.5)*5)).toFixed(1),
        visited:false,
        kind:'route',
        synthetic:true,
        routeKey:route.key
      });
    });
  });
  return [...out.values()];
}

