    {no:'DOV', x:176, y:74, w:32, h:22, label:'Dover'},
    {no:'ATL', x:72, y:58, w:92, h:54, label:'N. Atlantic'},
    {no:'FE', x:362, y:82, w:62, h:48, label:'Far East'}
