function renderMapLibrary(){
  const files = document.getElementById('map-files');
  const chartSvg = document.getElementById('port-chart-svg');
  const chartTitle = document.getElementById('port-chart-title');
  const chartMeta = document.getElementById('port-chart-meta');
  const chartZoomLabel = document.getElementById('port-chart-zoom-label');
  const chartDetailLabel = document.getElementById('port-chart-detail-label');
  if(!files || !chartSvg || !chartTitle || !chartMeta) return;
  ensureTaskPort(getCurrentMapTask());
  const active = ensureSelectedPortChart();
  const entries = getPortChartEntries();
  const activeRoute = getActiveVoyageRoute();
  const activeCharts = new Set([activeRoute?.chart, ...(activeRoute?.charts || []), ...(activeRoute?.waypoints || []).map(w=>w.chart)].filter(Boolean));
  const filesKey = [
    entries.length,
    selectedPortChart,
    activeRoute?.key || selectedVoyageRouteKey || '',
    [...visitedPorts].sort().join('|')
  ].join('::');
  if(mapRenderCache.filesKey !== filesKey){
    mapRenderCache.filesKey = filesKey;
    mapRenderCache.filesHtml = entries.map(port=>`
      <button class="map-file ${port.name===selectedPortChart?'active':''}" onclick="selectPortChart('${port.name.replace(/'/g,"\\'")}')">
      <span class="map-file-main">
        <span class="map-file-ico">🗂</span>
        <span class="map-file-text">
          <span class="map-file-name">${port.name}</span>
          <span class="map-file-sub">${getMapRegionByPosition(port)} · ${getPortChartTypeLabel(port.kind)}</span>
        </span>
      </span>
      <span class="map-file-tag">${activeCharts.has(port.name)?'sefer':visitedPorts.has(port.name)?'ugrandi':'arsiv'}</span>
    </button>
    `).join('');
  }
  if(files.innerHTML !== mapRenderCache.filesHtml) files.innerHTML = mapRenderCache.filesHtml;
  if(!active){
    chartSvg.innerHTML = '';
    chartTitle.textContent = 'Liman Haritasi';
    chartMeta.textContent = 'Harita arsivi hazir degil.';
    return;
  }
  const profile = getPortChartProfile(active);
  const region = profile.region;
  chartSvg.classList.add('shodb-style');
  chartSvg.setAttribute('preserveAspectRatio', 'xMidYMid slice');
  chartTitle.textContent = `${active.name} · ${getPortChartTitleLabel(active.kind)}`;
  const portKey = [
    active.name,
    getPortChartDetailBucket(),
    getActiveVoyageRoute()?.key || selectedVoyageRouteKey || '',
    activeVoyageProgress,
    JSON.stringify(deviceChartOverlayState || {}),
    getCurrentMapTask()?.id || '',
    completedMapTasks.has(getCurrentMapTask()?.id || '') ? 'done' : 'open'
  ].join('::');
  if(mapRenderCache.portKey !== portKey){
    mapRenderCache.portKey = portKey;
    mapRenderCache.portHtml = buildPortChartSvg(active);
  }
  if(chartSvg.dataset.cacheKey !== portKey){
    chartSvg.innerHTML = mapRenderCache.portHtml;
    chartSvg.dataset.cacheKey = portKey;
  }
  initPortChartInteractions(chartSvg);
  chartSvg.onclick = (ev)=>handlePortChartTaskClick(chartSvg, ev, active);
  chartSvg.setAttribute('viewBox', getPortChartViewBox());
  renderMapRouteDraftOverlay(chartSvg);
  if(chartZoomLabel) chartZoomLabel.textContent = `${Math.round(portChartZoom*100)}%`;
  if(chartDetailLabel) chartDetailLabel.textContent = getPortChartDetailLabel();
  const metaKey = [
    active.name,
    active.kind,
    activeRoute?.key || selectedVoyageRouteKey || '',
    visitedPorts.has(active.name) ? 'visited' : 'archive',
    activeCharts.has(active.name) ? 'active' : 'off'
  ].join('::');
  if(mapRenderCache.portMetaKey !== metaKey){
    mapRenderCache.portMetaKey = metaKey;
    mapRenderCache.portMetaHtml = `
    <div class="chart-meta-card">
      <div class="chart-meta-label">Dosya / Yayin</div>
      <div class="chart-meta-value">DOSYA: ${active.name.replace(/ /g,'_').toUpperCase()}.chart<br>YAYIN: ${profile.publication}<br>CHART NO: ${profile.chartNo} · ${profile.edition}</div>
    </div>
    <div class="chart-meta-card">
      <div class="chart-meta-label">Olcek / Bolge</div>
      <div class="chart-meta-value">TIP: ${active.kind==='port'?'LIMAN YAKLASMA PLANI':active.kind==='route'?'OCEAN PASSAGE / TRADE ROUTE CHARTI':'TRANSIT / GECIT CHARTI'}<br>BOLGE: ${region}<br>OLCEK: ${profile.scale}</div>
    </div>
    <div class="chart-meta-card">
      <div class="chart-meta-label">Yaklasma</div>
      <div class="chart-meta-value">YAKLASMA: ${profile.approach}<br>PILOT / REPORT: ${profile.pilot}<br>TEHLIKE ODAK: ${profile.hazard}</div>
    </div>
    <div class="chart-meta-card">
      <div class="chart-meta-label">Draft / Datum</div>
      <div class="chart-meta-value">MAKS DRAFT: ${profile.maxDraft}<br>DATUM: ${profile.soundDatum}<br>MAG VAR: ${profile.magVar}</div>
    </div>
    <div class="chart-meta-card">
      <div class="chart-meta-label">Operasyon</div>
      <div class="chart-meta-value">BERTH / LANE: ${profile.berth}<br>GELGIT / AKINTI: ${profile.tides}<br>DURUM: ${visitedPorts.has(active.name)?'UGRANAN CHART':'ARSIV CHARTI'}</div>
    </div>
    <div class="chart-meta-card">
      <div class="chart-meta-label">Chart Notu</div>
      <div class="chart-meta-value">${profile.notes}<br>${activeCharts.has(active.name)?`AKTIF SEFER DOSYASI: ${activeRoute.name} icin gerekli chart.`:'Arsiv chart; sefer rota dosyasina dahil degil.'}</div>
    </div>`;
  }
  if(chartMeta.innerHTML !== mapRenderCache.portMetaHtml) chartMeta.innerHTML = mapRenderCache.portMetaHtml;
  updateMapTaskBox(active);
  normalizeClickableSurface('#map-panel button,.map-task-target,.world-click-zone');
}

function getWorldMapPoint(p, i=0, total=1){
  const atlas = getWorldAtlasCoordinate(p);
  if(atlas) return atlas;
  const x = Math.max(8, Math.min(432, Number(p?.x || 0)));
  const rawY = Math.max(10, Math.min(250, Number(p?.y || 0)));
  const t = total > 1 ? i / (total - 1) : .5;
  const routeBias = 126 + Math.sin(t * Math.PI * 1.12) * 18 + Math.sin((x / 440) * Math.PI * 2) * 6;
  const isRoutePoint = p && (p.chart || p.risk || p.note || p.name?.startsWith?.('WP'));
  const y = isRoutePoint ? Math.max(76, Math.min(176, rawY * .28 + routeBias * .72)) : rawY;
  return {x:+x.toFixed(1), y:+y.toFixed(1)};
}

function normalizeAtlasKey(value){
  return String(value || '')
    .toLowerCase()
    .replace(/ı/g,'i')
    .replace(/ğ/g,'g')
    .replace(/ü/g,'u')
    .replace(/ş/g,'s')
    .replace(/ö/g,'o')
    .replace(/ç/g,'c')
    .replace(/[^\w\s/-]/g,'')
    .trim();
}

function getWorldAtlasCoordinate(p){
  const candidates = [p?.name, p?.chart, p?.start, p?.end].filter(Boolean);
  for(const raw of candidates){
    const key = normalizeAtlasKey(raw);
    if(WORLD_MAP_POINT_LOOKUP[key]){
      const [x,y] = WORLD_MAP_POINT_LOOKUP[key];
      return {x, y};
    }
    const partial = Object.keys(WORLD_MAP_POINT_LOOKUP).find(k=>key.includes(k) || k.includes(key));
    if(partial && key.length > 5){
      const [x,y] = WORLD_MAP_POINT_LOOKUP[partial];
      return {x, y};
    }
  }
  return null;
}

function clampWorldMapPan(){
  const w = 440 / worldMapZoom;
  const h = 260 / worldMapZoom;
  worldMapPanX = Math.max(0, Math.min(440 - w, worldMapPanX));
  worldMapPanY = Math.max(0, Math.min(260 - h, worldMapPanY));
}

function getWorldMapViewBox(){
  clampWorldMapPan();
  const w = 440 / worldMapZoom;
  const h = 260 / worldMapZoom;
  return `${worldMapPanX.toFixed(1)} ${worldMapPanY.toFixed(1)} ${w.toFixed(1)} ${h.toFixed(1)}`;
}

function updateWorldMapZoomLabel(){
  const label = document.getElementById('world-map-scale-label');
  if(!label) return;
  const detail = worldMapZoom >= 2.2 ? 'Close Detail' : worldMapZoom >= 1.45 ? 'Approach' : 'Overview';
  label.textContent = `Dunya Atlasi · ${Math.round(worldMapZoom * 100)}% · ${detail}`;
}

function adjustWorldMapZoom(delta){
  const prev = worldMapZoom;
  const beforeBucket = getWorldMapDetailBucket();
  worldMapZoom = Math.max(1, Math.min(3.2, +(worldMapZoom + delta).toFixed(2)));
  if(worldMapZoom !== prev){
    const centerX = worldMapPanX + (440 / prev) / 2;
    const centerY = worldMapPanY + (260 / prev) / 2;
    worldMapPanX = centerX - (440 / worldMapZoom) / 2;
    worldMapPanY = centerY - (260 / worldMapZoom) / 2;
  }
  if(beforeBucket === getWorldMapDetailBucket()){
    fastUpdateWorldMapViewport();
  }else{
    invalidateMapRenderCache('world');
    renderMap();
  }
}

function resetWorldMapView(){
  worldMapZoom = 1;
  worldMapPanX = 0;
  worldMapPanY = 0;
  fastUpdateWorldMapViewport();
}

function initWorldMapInteractions(svg){
  if(!svg || svg.dataset.worldMapBound === '1') return;
  svg.dataset.worldMapBound = '1';
  svg.addEventListener('pointerdown', (ev)=>{
    if(mapView !== 'world') return;
    svg.setPointerCapture?.(ev.pointerId);
    worldMapDragState = {id:ev.pointerId, x:ev.clientX, y:ev.clientY, panX:worldMapPanX, panY:worldMapPanY};
    worldMapDidPan = false;
    svg.classList.add('world-dragging');
  });
  svg.addEventListener('pointermove', (ev)=>{
    if(!worldMapDragState || worldMapDragState.id !== ev.pointerId || worldMapZoom <= 1) return;
    const rect = svg.getBoundingClientRect();
    const scaleX = (440 / worldMapZoom) / Math.max(1, rect.width);
    const scaleY = (260 / worldMapZoom) / Math.max(1, rect.height);
    const dx = (ev.clientX - worldMapDragState.x) * scaleX;
    const dy = (ev.clientY - worldMapDragState.y) * scaleY;
    if(Math.abs(dx) + Math.abs(dy) > .8) worldMapDidPan = true;
    worldMapPanX = worldMapDragState.panX - dx;
    worldMapPanY = worldMapDragState.panY - dy;
    svg.setAttribute('viewBox', getWorldMapViewBox());
  });
  svg.addEventListener('pointerup', (ev)=>{
    if(worldMapDragState?.id === ev.pointerId){
      worldMapDragState = null;
      svg.classList.remove('world-dragging');
    }
  });
  svg.addEventListener('pointercancel', ()=>{
    worldMapDragState = null;
    svg.classList.remove('world-dragging');
  });
  svg.addEventListener('wheel', (ev)=>{
    if(mapView !== 'world') return;
    ev.preventDefault();
    adjustWorldMapZoom(ev.deltaY > 0 ? -0.25 : 0.25);
  }, {passive:false});
}

