const WORLD_ATLAS_CONTINENT_FILLS = Object.freeze({
  "Africa":["#e7c36f","#d8b85f","#f0d48a"],
  "Asia":["#c9df7a","#b7d98e","#d5e89a"],
  "Europe":["#b4d2ec","#a4cfe7","#c2dbf2"],
  "North America":["#9fd7a3","#b8d88d","#8fcf9a"],
  "South America":["#e7a978","#f0b48a","#d89067"],
  "Oceania":["#d9b0d8","#c8a0d0","#e4c3e8"],
  "Antarctica":["#e9edf0"]
});
function getWorldAtlasCountryFill(continent, index){
  const palette = WORLD_ATLAS_CONTINENT_FILLS[continent] || ["#d6d98f","#c7d88a"];
  return palette[index % palette.length];
}
function buildNaturalEarthAtlasLayer(){
  return `<g class="natural-earth-atlas" aria-label="Natural Earth real country boundaries">` + WORLD_ATLAS_COUNTRIES.map(([name,continent,d],index)=>`<path class="world-country ne-country" d="${d}" fill="${getWorldAtlasCountryFill(continent,index)}"><title>${phoneSafe(name)}</title></path>`).join('') + `</g>`;
}
// NATURAL EARTH WORLD ATLAS END

function buildWorldAtlasBaseLayer(regionTint){
  let s = `<defs>
    <linearGradient id="worldSeaGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#d9f2fb"/>
      <stop offset=".52" stop-color="${regionTint}"/>
      <stop offset="1" stop-color="#b8dfea"/>
    </linearGradient>
    <filter id="atlasShadow" x="-8%" y="-8%" width="116%" height="116%">
      <feDropShadow dx=".8" dy="1.1" stdDeviation=".9" flood-color="#5f6f69" flood-opacity=".22"/>
    </filter>
    <pattern id="atlasHatch" width="7" height="7" patternUnits="userSpaceOnUse">
      <path d="M0 7 L7 0" stroke="#ffffff" stroke-width=".35" opacity=".18"/>
    </pattern>
  </defs>`;
  s += `<rect width="440" height="260" fill="url(#worldSeaGrad)" rx="6"/>`;
  s+=`<style>
    .world-chart text{font-family:'Share Tech Mono',monospace;letter-spacing:0}
    .political-atlas .natural-earth-atlas{filter:url(#atlasShadow)}
    .political-atlas .world-country{stroke:#314942;stroke-width:.34;vector-effect:non-scaling-stroke;opacity:.98;fill-rule:evenodd}
    .political-atlas .ne-country:hover{filter:brightness(1.08) saturate(1.08)}
    .political-atlas .world-country-line{fill:none;stroke:#314942;stroke-width:.34;opacity:.72;vector-effect:non-scaling-stroke}
    .political-atlas .atlas-label{fill:#1d2f38;stroke:#fff7d0;stroke-width:1.55;stroke-opacity:.84;font-weight:700}
    .political-atlas .country-label{fill:#233f47;stroke:#fff7d0;stroke-width:1.1;stroke-opacity:.76;font-weight:700}
    .political-atlas .sea-title{fill:#245c78;stroke:#eaf8fb;stroke-width:1.2;stroke-opacity:.82;font-style:italic}
    .world-lane{fill:none;stroke:#9b3151;stroke-width:1.35;stroke-dasharray:7 5;opacity:.56}
    .world-lane.secondary{stroke:#245f9a;stroke-width:1.05;opacity:.4}
    .world-grid{stroke:#6ea8ba;stroke-width:.42;opacity:.22}
    .world-meridian-label{fill:#56869a;font:5px 'Share Tech Mono',monospace;stroke:none}
  </style><g class="world-chart political-atlas">`;
  for(let x=40;x<440;x+=40) s+=`<path class="world-grid" d="M${x} 12 V249"/><text class="world-meridian-label" x="${x-5}" y="256">${x-220 > 0 ? '+' : ''}${Math.round((x-220)/2)}°</text>`;
  for(let y=40;y<260;y+=40) s+=`<path class="world-grid" d="M8 ${y} H432"/>`;
  s+=`<text class="sea-title" x="63" y="88" font-size="8.5">NORTH ATLANTIC</text>
    <text class="sea-title" x="92" y="207" font-size="8">SOUTH ATLANTIC</text>
    <text class="sea-title" x="345" y="128" font-size="9">PACIFIC</text>
    <text class="sea-title" x="278" y="205" font-size="8.5">INDIAN OCEAN</text>`;

  s += buildNaturalEarthAtlasLayer();
  s += `<path class="world-country-line" d="M222 58 L235 64 M243 77 L262 76 M268 87 L288 91 M318 91 L350 104 M353 116 L372 140 M174 120 L252 132"/>
    <text class="atlas-label" x="48" y="47" font-size="8.5">N. AMERICA</text>
    <text class="atlas-label" x="109" y="195" font-size="8.2">S. AMERICA</text>
    <text class="atlas-label" x="184" y="78" font-size="8">EUROPE</text>
    <text class="atlas-label" x="217" y="170" font-size="8.3">AFRICA</text>
    <text class="atlas-label" x="320" y="96" font-size="9">ASIA</text>
    <text class="atlas-label" x="390" y="229" font-size="7.6">AUSTRALIA</text>
    <text class="country-label" x="56" y="72" font-size="5.8">USA</text>
    <text class="country-label" x="63" y="122" font-size="5.8">MEXICO</text>
    <text class="country-label" x="112" y="169" font-size="5.8">BRAZIL</text>
    <text class="country-label" x="187" y="93" font-size="5.6">FRANCE</text>
    <text class="country-label" x="210" y="96" font-size="5.6">TURKEY</text>
    <text class="country-label" x="240" y="126" font-size="5.6">EGYPT</text>
    <text class="country-label" x="321" y="143" font-size="5.6">IRAN</text>
    <text class="country-label" x="340" y="164" font-size="5.6">INDIA</text>
    <text class="country-label" x="384" y="116" font-size="5.6">CHINA</text>
    <text class="country-label" x="407" y="91" font-size="5.4">JAPAN</text>`;
  s+=`<path class="world-lane" d="M190 82 Q176 103 174 120 Q207 122 252 132 Q270 166 300 166 Q338 166 371 167 Q398 142 420 104"/>`;
  s+=`<path class="world-lane" d="M69 150 Q118 133 174 120 Q218 116 252 132"/>`;
  s+=`<path class="world-lane secondary" d="M232 237 Q276 204 330 178 Q360 166 382 143"/>`;
  s+=`<path class="world-lane secondary" d="M86 78 Q132 70 187 82 Q230 88 286 72 Q350 60 414 82"/>`;
  s += `</g>`;
  return s;
}

function buildWorldMapFeatureLayer(){
  const detailLimit = worldMapZoom >= 2.15 ? 99 : worldMapZoom >= 1.45 ? 1.45 : 1.05;
  return WORLD_MAP_FEATURES
    .filter(f=>f.min <= detailLimit)
    .map((f)=>{
      const cls = f.kind === 'ocean' ? 'ocean' : f.kind === 'sea' ? 'sea' : f.kind === 'canal' ? 'canal' : 'chokepoint';
      const size = f.kind === 'ocean' ? 7.4 : f.kind === 'sea' ? 6.4 : 6.2;
      const mark = f.kind === 'canal'
        ? `<rect x="${f.x-2.8}" y="${f.y-2.8}" width="5.6" height="5.6" rx="1" fill="#d4a017" opacity=".9"/>`
        : f.kind === 'chokepoint'
          ? `<path d="M${f.x} ${f.y-4} L${f.x+4} ${f.y} L${f.x} ${f.y+4} L${f.x-4} ${f.y} Z" fill="#9b3151" opacity=".86"/>`
          : '';
      const zone = `<circle class="world-click-zone" cx="${f.x}" cy="${f.y}" r="${f.kind === 'ocean' ? 20 : 13}" fill="rgba(255,212,90,.01)" stroke="#7b3550" stroke-width=".6" opacity=".12"><title>${f.name} chart dosyasini ac</title></circle>`;
      return `${zone}${mark}<text class="world-atlas-label ${cls}" x="${f.x+5}" y="${f.y+3}" font-size="${size}">${f.name}</text>`;
    }).join('');
}

function handleWorldMapClick(svg, ev){
  if(worldMapDidPan){
    worldMapDidPan = false;
    return;
  }
  const pos = getSvgClickPoint(svg, ev);
  const folioSheet = getClickedWorldChartIndexSheet(pos.x, pos.y);
  if(folioSheet){
    const targetName = getSheetDrilldownChartName(folioSheet.no, null);
    const target = getPortChartByName(targetName);
    if(target){
      selectedPortChart = target.name;
      visitedPorts.add(target.name);
      mapView = 'library';
      portChartZoom = Math.max(portChartZoom || 1, 1.18);
      showNotif('DUNYA ATLASI', `${folioSheet.no} paftasi`, `${target.name} chart dosyasi acildi.`);
      addLiveLogbook('DUNYA ATLASI', `${folioSheet.no} paftasi uzerinden ${target.name} chartina gecildi.`, true);
      renderMap();
      return;
    }
  }
  let best = null;
  getPortChartEntries().forEach((p)=>{
    const wp = getWorldMapPoint(p);
    const d = Math.hypot(pos.x - wp.x, pos.y - wp.y);
    if(!best || d < best.d) best = {port:p, d};
  });
  if(!best || best.d > 22) return;
  selectedPortChart = best.port.name;
  visitedPorts.add(best.port.name);
  mapView = 'library';
  showNotif('HARITA', 'Chart acildi', `${best.port.name} chart dosyasi yuklendi.`);
  renderMap();
}

