function getWorldMapLegendText(){
  return `Aktif sefer: ${getActiveVoyageRoute()?.name || 'rota yok'} · ${getVoyageLegProgress()}% · Nokta/liman/gecit uzerine tiklayinca chart acilir · 🟢 Ugranan/aktif WP  🔵 Planlanan nokta  🔷 Kanal/bogaz  🟡 ${sn||'Gemimiz'} — ${visitedPorts.size} nokta islendi`;
}

function renderMap(){
  const panel = document.getElementById('map-panel');
  const tabs = document.querySelectorAll('.map-tab');
  if(panel){
    panel.classList.toggle('library', mapView === 'library');
  }
  tabs.forEach(btn=>{
    const wants = btn.textContent.toLowerCase().includes('haritalarim') ? 'library' : 'world';
    btn.classList.toggle('active', wants===mapView);
  });
  if(mapView === 'library'){
    renderMapLibrary();
    return;
  }
  const svg = document.getElementById('map-svg');
  const legend = document.getElementById('map-legend');
  svg?.classList.add('shodb-style');
  initWorldMapInteractions(svg);
  updateWorldMapZoomLabel();
  if(svg){
    svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    svg.setAttribute('viewBox', getWorldMapViewBox());
  }
  const region = getMapRegionByPosition(shipPosition);
  const regionTint =
    region==='ORTA AKDENIZ' ? '#cfeaf3' :
    region==='TURK BOGAZLARI / ADRIYATIK' ? '#c7e6f0' :
    region==='KARADENIZ / AZAK' ? '#c2e1ed' :
    region==='KUZEY DENIZI / BALTIK' ? '#c0ddea' :
    region==='ATLANTIK / BATI AVRUPA' ? '#c9e6f1' :
    region==='AMERIKA / KARAYIPLER' ? '#ccebf4' :
    region==='GUNEY AMERIKA' ? '#c8e3ef' :
    region==='KIZILDENIZ / HINT OKYANUSU GIRISI' ? '#c7e4ee' :
    region==='BASRA KORFEZI / ARAP DENIZI' ? '#c4e2ec' :
    region==='GUNEYDOGU ASYA' ? '#c6eaf1' :
    region==='DOGU ASYA' ? '#c1e4ee' :
    region==='KUZEY PASIFIK / JAPONYA' ? '#bedfea' :
    '#d8eef7';
  const activeRoute = getActiveVoyageRoute();
  const worldKey = [
    region,
    getWorldMapDetailBucket(),
    activeRoute?.key || selectedVoyageRouteKey || '',
    activeVoyageProgress,
    routeHistory.length,
    `${shipPosition.x},${shipPosition.y}`,
    [...visitedPorts].sort().join('|')
  ].join('::');
  if(svg && mapRenderCache.worldKey === worldKey && mapRenderCache.worldHtml){
    if(svg.dataset.cacheKey !== worldKey){
      svg.innerHTML = mapRenderCache.worldHtml;
      svg.dataset.cacheKey = worldKey;
    }
    svg.onclick = (ev)=>handleWorldMapClick(svg, ev);
    if(legend) legend.textContent = getWorldMapLegendText();
    return;
  }
  let s = buildWorldAtlasBaseLayer(regionTint);
  s+=buildWorldShodbChartIndexOverlay();
  s+=buildWorldMapFeatureLayer();
  // Sea texture
  for(let i=0;i<8;i++){
    s+=`<path d="M${i*60} ${80+i*20} Q${i*60+30} ${75+i*20} ${i*60+60} ${80+i*20}" fill="none" stroke="#8cbfd0" stroke-width="1" opacity=".35"/>`;
  }

  if(activeRoute?.waypoints?.length){
    const routePoints = activeRoute.waypoints.map((w,i)=>getWorldMapPoint(w, i, activeRoute.waypoints.length));
    const pts = routePoints.map(w=>`${w.x},${w.y}`).join(' ');
    s+=`<polyline points="${pts}" fill="none" stroke="#d4a017" stroke-width="2.3" stroke-dasharray="9 5" opacity=".72"/>`;
    activeRoute.waypoints.forEach((w,i)=>{
      const {x:wx, y:wy} = routePoints[i];
      const done = i <= activeVoyageProgress;
      s+=`<circle cx="${wx}" cy="${wy}" r="${done?5:3.2}" fill="${done?'#d4a017':'#0b304f'}" stroke="#ffd783" stroke-width="${done?1.4:.8}" opacity="${done?1:.82}"/>`;
      if(i===activeVoyageProgress || i===0 || i===activeRoute.waypoints.length-1){
        s+=`<text x="${wx+7}" y="${wy-6}" fill="#7b3550" font-size="6.6">${i+1}. ${w.name}</text>`;
      }
    });
    const currentWp = getVoyageWaypoint();
    const curIdx = Math.max(0, Math.min(activeRoute.waypoints.length-1, activeVoyageProgress || 0));
    const cur = activeRoute.waypoints[curIdx];
    const nxt = activeRoute.waypoints[Math.min(activeRoute.waypoints.length-1, curIdx+1)];
    if(cur && nxt && cur !== nxt){
      const p1 = routePoints[curIdx];
      const p2 = routePoints[Math.min(activeRoute.waypoints.length-1, curIdx+1)];
      const cx1 = p1.x, cy1 = p1.y, cx2 = p2.x, cy2 = p2.y;
      s+=`<path d="M${cx1} ${cy1} L${cx2} ${cy2}" stroke="#ffd45a" stroke-width="3" opacity=".34"/>
        <circle r="6" fill="#ffd45a" stroke="#102033" stroke-width="1.4">
          <animate attributeName="cx" values="${cx1};${cx2};${cx1}" dur="8s" repeatCount="indefinite"/>
          <animate attributeName="cy" values="${cy1};${cy2};${cy1}" dur="8s" repeatCount="indefinite"/>
        </circle>`;
    }
    s+=`<rect x="238" y="10" width="192" height="42" rx="7" fill="rgba(255,255,255,.72)" stroke="#9b8356" stroke-width=".8"/>`;
    s+=`<text x="246" y="24" fill="#7b3550" font-size="7.2">${activeRoute.name}</text>`;
    s+=`<text x="246" y="36" fill="#264f75" font-size="6.5">${activeRoute.trade} · ${activeRoute.distanceNm} NM · ETA ${activeRoute.etaDays} gun</text>`;
    s+=`<text x="246" y="48" fill="#264f75" font-size="6.5">Aktif WP: ${currentWp?.name || '-'} · ${getVoyageLegProgress()}%</text>`;
  }

  // Route line
  if(routeHistory.length > 1){
    const historyPoints = routeHistory.map((p,i)=>getWorldMapPoint(p, i, routeHistory.length));
    let d = `M${historyPoints[0].x} ${historyPoints[0].y}`;
    for(let i=1;i<routeHistory.length;i++){
      d += ` L${historyPoints[i].x} ${historyPoints[i].y}`;
    }
    s+=`<path d="${d}" fill="none" stroke="#2e6bbf" stroke-width="1.5" stroke-dasharray="5,3" opacity=".7"/>`;
  }

  const labelWhitelist = new Set([
    'İstanbul','Çanakkale','İzmir','Ambarli','Aliaga','Rotterdam','Singapur','Panama Kanali','Suveys Kanali',
    'Hurmuz Bogazi','Babulmendep','Malakka Bogazi','Dover Bogazi','Gibraltar','Kiel Kanali',
    'Kuzey Atlantik Ana Hatti','Avrupa - Uzak Dogu Konteyner Rotasi','Transpasifik Dogu Hatti',
    'Basra Korfezi Tanker Hatti','Cape of Good Hope Alternatif Rotasi'
  ]);
  const distToShip = p => Math.hypot(p.x - shipPosition.x, p.y - shipPosition.y);

  // Ports
  ROUTE_PORTS.forEach(p => {
    const {x:px, y:py} = getWorldMapPoint(p);
    const visited = visitedPorts.has(p.name);
    const nearby = distToShip(p) < 28;
    const important = labelWhitelist.has(p.name);
    const labeled = visited || nearby || important;
    const color = p.kind==='waterway' ? (visited ? '#9b3151' : '#264f75') : p.kind==='route' ? '#7b3550' : (visited ? '#287b57' : '#29577d');
    const markOpacity = labeled ? (visited ? 1 : .82) : (p.kind==='route' ? .22 : .34);
    if(p.kind==='waterway'){
      const sz = labeled ? (visited ? 5 : 3.8) : 2.7;
      s+=`<path d="M${px} ${py-sz} L${px+sz} ${py} L${px} ${py+sz} L${px-sz} ${py} Z" fill="${color}" opacity="${markOpacity}"/>`;
    }else{
      const r = labeled ? (visited ? 5 : p.kind==='route' ? 3 : 3.3) : (p.kind==='route' ? 1.8 : 2.2);
      s+=`<circle cx="${px}" cy="${py}" r="${r}" fill="${color}" opacity="${markOpacity}"/>`;
    }
    if(labeled){
      const fontSize = important || visited ? 7.2 : 6.4;
      s+=`<text x="${px+7}" y="${py+4}" fill="${color}" font-size="${fontSize}" opacity="${visited?1:.76}">${p.name}</text>`;
    }
    if(visited){
      s+=`<circle cx="${px}" cy="${py}" r="9" fill="none" stroke="${color}" stroke-width="1" opacity=".3"/>`;
    }
    if(labeled || important || p.kind!=='port'){
      s+=`<circle class="world-click-zone" cx="${px}" cy="${py}" r="${important?14:11}" fill="rgba(255,212,90,.01)" stroke="${color}" stroke-width=".8" opacity=".18"><title>${p.name} chart dosyasini ac</title></circle>`;
    }
  });

  // Ship position
  const shipMapPoint = getWorldMapPoint(getVoyageWaypoint() || shipPosition);
  const sx = shipMapPoint.x, sy = shipMapPoint.y;
  s+=`<circle cx="${sx}" cy="${sy}" r="5" fill="#d4a017"/>`;
  s+=`<path d="M${sx-4} ${sy} L${sx} ${sy-8} L${sx+4} ${sy} Z" fill="#d4a017"/>`;
  s+=`<circle cx="${sx}" cy="${sy}" r="10" fill="none" stroke="#d4a017" stroke-width="1" opacity=".5" class="blink"/>`;
  s+=`<text x="${sx+12}" y="${sy+4}" fill="#9b3151" font-size="8">${sn||'Gemi'}</text>`;
  s+=`<text x="12" y="16" fill="#264f75" font-size="8" opacity=".85">${region}</text>`;
  s+=`<text x="12" y="248" fill="#627c8f" font-size="7" opacity=".82">ECDIS OVERVIEW - isimler yakin/stratejik noktalarda acilir</text>`;
  s+=`<path d="M28 214 h26 l7 3 h7 v2 h-40 z" fill="#204765" opacity=".62"/>`;
  s+=`<rect x="35" y="207" width="10" height="7" rx="1" fill="#9b3151" opacity=".72"/>`;
  s+=`<path d="M362 68 h22 l7 3 h6 v2 h-35 z" fill="#204765" opacity=".45"/>`;
  s+=`</g>`;

  mapRenderCache.worldKey = worldKey;
  mapRenderCache.worldHtml = s;
  svg.innerHTML = s;
  svg.dataset.cacheKey = worldKey;
  svg.onclick = (ev)=>handleWorldMapClick(svg, ev);
  if(legend) legend.textContent = getWorldMapLegendText();
}

