function getDeviceDef(key){
  return DEVICE_TRAINER.find(d=>d.key===key) || DEVICE_TRAINER[0];
}

function openDevices(){
  if(!canUseFeature('devices')) return;
  completeMissionFromFeature('devices');
  const p = document.getElementById('devices-panel');
  if(p) p.classList.add('show');
  renderDevices();
}
function closeDevices(){
  const p = document.getElementById('devices-panel');
  if(p) p.classList.remove('show');
  deviceScreenZoomed = false;
}
function toggleDeviceScreenZoom(force){
  deviceScreenZoomed = typeof force === 'boolean' ? force : !deviceScreenZoomed;
  renderDevices();
}
function selectDevice(key){
  activeDeviceKey = key;
  deviceMenuPath[key] = 'root';
  if(!(key in devicePracticeProgress)) devicePracticeProgress[key] = 0;
  deviceLogLine = `${getDeviceDef(key).name} acildi. Menulerden goreve uygun adimi sec.`;
  renderDevices();
}
function getDeviceMenuId(key){
  return deviceMenuPath[key] || 'root';
}
function getDeviceMenuEntries(def){
  const tree = DEVICE_MENU_TREE[def.key];
  const menuId = getDeviceMenuId(def.key);
  if(tree && tree[menuId]) return tree[menuId];
  return (def.keys || []).map(k=>mAct(k));
}
function getDeviceBreadcrumb(def){
  const menuId = getDeviceMenuId(def.key);
  if(menuId === 'root') return 'MAIN MENU';
  const root = DEVICE_MENU_TREE[def.key]?.root || [];
  const item = root.find(x=>x.target === menuId);
  return `MAIN MENU / ${item ? item.label : menuId.toUpperCase()}`;
}
function getDevicePractice(def){
  if(def.key === 'vhf'){
    const idx = devicePracticeVariant.vhf || 0;
    return VHF_PRACTICE_VARIANTS[idx % VHF_PRACTICE_VARIANTS.length];
  }
  return DEVICE_PRACTICE[def.key] || null;
}
function getDevicePracticeIndex(def){
  const practice = getDevicePractice(def);
  if(!practice) return 0;
  return Math.min(devicePracticeProgress[def.key] || 0, practice.steps.length);
}
function getDeviceExpectedAction(def){
  const practice = getDevicePractice(def);
  if(!practice) return def.correct;
  const idx = getDevicePracticeIndex(def);
  return practice.steps[idx] || practice.steps[practice.steps.length - 1] || def.correct;
}
function resetDevicePractice(){
  const def = getDeviceDef(activeDeviceKey);
  if(def.key === 'vhf') devicePracticeVariant.vhf = ((devicePracticeVariant.vhf || 0) + 1) % VHF_PRACTICE_VARIANTS.length;
  devicePracticeProgress[def.key] = 0;
  deviceMenuPath[def.key] = 'root';
  deviceLogLine = `${def.name}: pratik sifirlandi. Ilk adimdan basla.`;
  renderDevices();
}

function getDeviceTrainingCoach(def, expected){
  const key = def?.key || '';
  if(key === 'vhf') return `Kanal secimi tek basina yetmez; mesaj turu, DSC zinciri, PTT disiplini ve readback sirasini takip et. Siradaki beklenen adim: ${expected}.`;
  if(key === 'radar') return `Once hedefi acquire et, sonra CPA/TCPA ve vektorleri oku. Trial manoeuvre ancak hedef verisi oturduktan sonra anlamli olur.`;
  if(key === 'ecdis') return `Route check, safety contour ve alarm acknowledge ayni zincirin parcalari. Sadece rotaya degil, no-go ve sensor durumuna da bak.`;
  if(key === 'gmdss' || key === 'mf-hf') return `Distress/urgency rutini cihaz menusu, kanal/frekans, mesaj tipi ve onay adimlariyla okunur.`;
  if(key === 'ais') return `AIS bilgi verir ama tek basina karar verdirmez; radar/visual kontrol ve CPA karsilastirmasi gerekir.`;
  if(key === 'starlink') return `Baglanti sagligi, obstruction, failover ve latency ayni panelden takip edilir; kritik haberlesmede backup dusun.`;
  return `Cihaz pratigi sira mantigiyla ilerler. Beklenen adim: ${expected}. Yanlis adimda stat degil, once egitim aciklamasi gelir.`;
}

function getDeviceWrongExplanation(def, label, expected){
  const key = def?.key || '';
  if(key === 'vhf') return `VHF'de ${label} erken/yanlis secildi. Once ${expected} adimini tamamla; kanal, mesaj tipi ve readback sirasi bozulmamali.`;
  if(key === 'radar') return `Radar ekraninda ${label} icin veri zinciri eksik. Beklenen adim ${expected}; hedef acquire edilmeden CPA/TCPA yorumu zayif kalir.`;
  if(key === 'ecdis') return `ECDIS'te ${label} dogru baglamda degil. Beklenen adim ${expected}; route check, safety contour ve alarm listesi birlikte okunur.`;
  if(key === 'gmdss' || key === 'mf-hf') return `${label} secimi haberlesme zincirini atliyor. Beklenen adim ${expected}; distress/urgency menusu sirasiyla ilerler.`;
  return `${label} bu adim icin erken. Beklenen adim: ${expected}. Sirayi takip et ve menude ilgili alani yeniden sec.`;
}

function renderDevicePracticeTask(def){
  const practice = getDevicePractice(def);
  const expected = getDeviceExpectedAction(def);
  const coach = `<div class="device-coach-card"><i>?</i><div><b>Cihaz koçu</b>${phoneSafe(getDeviceTrainingCoach(def, expected))}</div></div>`;
  if(!practice) return `${def.task}${coach}<div class="device-task-path">Beklenen adim: ${expected}</div>`;
  const idx = getDevicePracticeIndex(def);
  const done = idx >= practice.steps.length;
  return `<div class="device-practice-title">${practice.title}</div>
    <div class="device-practice-phrase">${practice.phrase}</div>
    ${coach}
    <div class="device-practice-steps">${practice.steps.map((s,i)=>`<span class="${i<idx?'done':i===idx?'active':''}">${i+1}. ${s}</span>`).join('')}</div>
    <div class="device-task-path">${done?'Pratik tamamlandi. Istersen sifirlayip tekrar dene.':'Siradaki adim: '+expected}</div>
    <button class="device-mini-btn" onclick="resetDevicePractice()">Pratigi sifirla</button>`;
}
function updateDeviceChartOverlay(def, label, ok=false){
  if(!def || !['radar','ais','ecdis'].includes(def.key)) return;
  const l = String(label || '').toUpperCase();
  const next = {...deviceChartOverlayState, updatedAt:Date.now(), source:def.name};
  if(def.key === 'radar'){
    next.radar = true;
    if(/ARPA ACQUIRE/.test(l)) next.arpa = true;
    if(/CPA|TCPA|VECTOR/.test(l)) next.cpa = true;
    if(/GUARD ZONE/.test(l)) next.guard = true;
    if(/EBL|VRM|PARALLEL|TRAILS|TRUE MOTION/.test(l)) next.ebl = true;
    if(/TRIAL/.test(l)) next.trial = true;
    if(/RANGE|GAIN|CLUTTER|PULSE|TUNE/.test(l)) next.radar = true;
  }
  if(def.key === 'ais'){
    next.ais = true;
    if(/CPA SORT|TARGET DETAIL|SENSOR CHECK/.test(l)) next.cpa = true;
  }
  if(def.key === 'ecdis'){
    if(/ROUTE CHECK|NEXT WP|WHEEL|TURN|XTD/.test(l)) next.ebl = true;
    if(/SAFETY CONTOUR|SAFETY DEPTH|NO-GO|DANGER|LOOK-AHEAD|ALARM/.test(l)) next.guard = true;
    if(/RADAR OVERLAY/.test(l)) next.radar = true;
    if(/SENSOR|GPS|GYRO|SPEED LOG/.test(l)) next.ais = true;
    if(/CPA ALARM/.test(l)) next.cpa = true;
    if(/ROUTE CHECK|ALARM LIST|SENSOR STATUS/.test(l)) next.radar = next.radar || deviceChartOverlayState.radar;
  }
  deviceChartOverlayState = next;
  const chart = getVoyageWaypoint()?.chart || selectedPortChart;
  if(chart) selectedPortChart = chart;
  mapView = 'library';
  if(ok || /ARPA ACQUIRE|CPA|GUARD ZONE|EBL|VRM|CPA SORT|TARGET DETAIL/.test(l)){
    addLiveLogbook('RADAR / CHART OVERLAY', `${def.name}: ${label} harita uzerine isaretlendi.`, true);
    showNotif('MAP','Harita Overlay',`${label} chart ustunde gorunuyor.`);
    document.getElementById('map-panel')?.classList.add('show');
  }
  if(document.getElementById('map-panel')?.classList.contains('show')) renderMap();
}
function useDeviceKey(label, type='action', target=''){
  const def = getDeviceDef(activeDeviceKey);
  if(type === 'back'){
    deviceMenuPath[def.key] = 'root';
    deviceLogLine = `${def.name}: ana menuye donuldu.`;
    renderDevices();
    return;
  }
  if(type === 'submenu'){
    deviceMenuPath[def.key] = target || 'root';
    deviceLogLine = `${def.name}: ${label} menusu acildi.`;
    renderDevices();
    return;
  }
  const practice = getDevicePractice(def);
  const expected = getDeviceExpectedAction(def);
  devicePracticeScore.total++;
  if(label === expected){
    devicePracticeScore.ok++;
    awardMetaXp(8, `${def.name} dogru cihaz adimi`, 'device');
    progressRetentionMission('device', {deviceKey:def.key, label});
    progressFirstFiveStep('device');
    addWatchFeed(`${def.name}: ${label} dogru uygulandi`, def.key==='vhf' ? 'warn' : 'good');
    if(def.key === 'vhf') playVhfPracticeBurst();
    if(def.key === 'starlink') updateStarlinkFromDeviceStep(label, true);
    updateDeviceChartOverlay(def, label, true);
    if(practice){
      const next = (devicePracticeProgress[def.key] || 0) + 1;
      devicePracticeProgress[def.key] = next;
      if(next >= practice.steps.length){
        deviceLogLine = `PRATIK TAMAM: ${practice.title}. Haberlesme/cihaz zinciri dogru sirayla uygulandi.`;
        addJournalEntry(`[CIHAZ] ${def.name}: ${practice.title} tamamlandi.`, 'Egitim', 'Simulator');
      }else{
        deviceLogLine = `DOGRU ADIM: ${label}. Siradaki adim: ${practice.steps[next]}.`;
      }
    }else{
      deviceLogLine = `DOGRU: ${getDeviceBreadcrumb(def)} > ${label}. ${def.name} icin uygulama kayda alindi.`;
      addJournalEntry(`[CIHAZ] ${def.name}: ${getDeviceBreadcrumb(def)} > ${label} dogru uygulandi.`, 'Egitim', 'Simulator');
    }
  }else{
    if(def.key === 'starlink') updateStarlinkFromDeviceStep(label, false);
    updateDeviceChartOverlay(def, label, false);
    deviceLogLine = `YANLIS SIRA / EKSIK: ${getDeviceBreadcrumb(def)} > ${label}. ${getDeviceWrongExplanation(def, label, expected)}`;
  }
  renderDevices();
}
function updateStarlinkFromDeviceStep(label, ok){
  const l=String(label || '').toUpperCase();
  starlinkStatus.lastCheck = document.getElementById('tbd')?.textContent || '--:--';
  if(ok){
    starlinkStatus.online = true;
    if(/NETWORK HEALTH|FAILOVER/.test(l)) starlinkStatus.latency = Math.max(28, starlinkStatus.latency - 6);
    if(/OBSTRUCTION|ALIGNMENT/.test(l)) starlinkStatus.obstruction = Math.max(0, starlinkStatus.obstruction - 2);
    if(/DATA PRIORITY|OPS VLAN/.test(l)) starlinkStatus.plan = 'Ops priority active';
    addLiveLogbook('STARLINK', `${label} kontrolu tamamlandi. Latency ${starlinkStatus.latency} ms, obstruction ${starlinkStatus.obstruction}%.`, true);
  }else{
    starlinkStatus.latency = Math.min(140, starlinkStatus.latency + 9);
    starlinkStatus.obstruction = Math.min(28, starlinkStatus.obstruction + 3);
    if(starlinkStatus.latency > 95) starlinkStatus.online = false;
  }
}
function renderDevices(){
  const list = document.getElementById('devices-list');
  const name = document.getElementById('device-name');
  const sub = document.getElementById('device-sub');
  const score = document.getElementById('device-score');
  const screen = document.getElementById('device-screen');
  const keys = document.getElementById('device-softkeys');
  const task = document.getElementById('device-task');
  const log = document.getElementById('device-log');
  if(!list || !screen || !keys) return;
  const def = getDeviceDef(activeDeviceKey);
  const box = document.getElementById('devices-box');
  if(box) box.classList.toggle('device-zoomed', !!deviceScreenZoomed);
  list.innerHTML = DEVICE_TRAINER.map(d=>`
    <button class="device-tab ${d.key===activeDeviceKey?'active':''}" onclick="selectDevice('${d.key}')">
      <span class="device-tab-ico">${d.ico}</span><span>${d.name}<small>${d.sub}</small></span>
    </button>`).join('');
  if(name) name.textContent = def.name;
  if(sub) sub.textContent = def.sub;
  if(score) score.textContent = `${devicePracticeScore.ok}/${devicePracticeScore.total}`;
  screen.innerHTML = buildDeviceScreen(def);
  screen.onclick = (ev)=>{
    if(ev.target.closest?.('button')) return;
    toggleDeviceScreenZoom();
  };
  screen.setAttribute('title', deviceScreenZoomed ? 'Cihaz ekranini normal boya dondur' : 'Cihaz ekranini buyut');
  const menuId = getDeviceMenuId(def.key);
  const entries = getDeviceMenuEntries(def);
  const expected = getDeviceExpectedAction(def);
  const backBtn = menuId !== 'root' ? `<button class="device-key back" onclick="useDeviceKey('BACK','back','')">GERI / MENU</button>` : '';
  keys.innerHTML = backBtn + entries.map(k=>{
    const cls = [k.label===expected?'good':'', k.type==='submenu'?'folder':''].filter(Boolean).join(' ');
    return `<button class="device-key ${cls}" onclick="useDeviceKey('${k.label.replace(/'/g,"\\'")}','${k.type}','${k.target||''}')">${k.type==='submenu'?'▸ ':''}${k.label}</button>`;
  }).join('');
  if(task) task.innerHTML = `<div class="device-task-head">SIMULASYON PRATIGI · ${getDeviceBreadcrumb(def)}</div>${renderDevicePracticeTask(def)}`;
  if(log) log.textContent = deviceLogLine;
  normalizeClickableSurface('#devices-panel button,#device-screen');
}

function getDeviceLiveStrip(def){
  const st = computeLiveVoyageState(sceneQueue[currentIdx] || {});
  const expected = getDeviceExpectedAction(def);
  const route = st.route || getActiveVoyageRoute()?.name || 'Rota yok';
  const mode = {
    radar:'ARPA / CPA',
    ecdis:'ROUTE CHECK',
    vhf:'DSC WATCH',
    ais:'TARGET COMPARE',
    gmdss:'DISTRESS',
    navtex:'MSI',
    starlink:'SATCOM',
    ecr:'ECR WATCH'
  }[def.key] || def.name;
  return `<div class="device-live-strip">
    <span><b>MODE</b>${phoneSafe(mode)}</span>
    <span><b>ROUTE</b>${phoneSafe(route)}</span>
    <span><b>CPA/TCPA</b>${phoneSafe(st.cpa)} NM / ${phoneSafe(st.tcpa)}m</span>
    <span><b>SOG/COG</b>${phoneSafe(st.sog)} kt / ${phoneSafe(st.cog)}</span>
    <span class="${st.alert?'warn':'ok'}"><b>NEXT</b>${phoneSafe(expected)}</span>
  </div>`;
}

function getDeviceSimOverlay(def){
  const st = liveVoyageState || computeLiveVoyageState(sceneQueue[currentIdx] || {});
  const rows = {
    radar:['RADAR / ARPA SIM', `Acquire target, read CPA/TCPA, set guard zone. UKC ${st.ukc} m.`],
    ecdis:['ECDIS ROUTE CHECK', `Safety contour, no-go area and next waypoint: ${st.nextWp}.`],
    vhf:['VHF / DSC CONSOLE', `Use channel, PTT, DSC and radio log in the correct order.`],
    ais:['AIS COMPARE', `Compare AIS identity, COG/SOG and radar echo before reporting.`],
    gmdss:['GMDSS DISTRESS', 'Open DSC menu, choose distress type, then follow voice procedure.'],
    navtex:['NAVTEX MSI', 'Read warning, match area, and add the route risk note.'],
    starlink:['STARLINK OPS', `Latency ${starlinkStatus.latency} ms, obstruction ${starlinkStatus.obstruction}%.`],
    ecr:['ECR LINK', 'Bridge report must match generator, bilge, purifier and cooling alarms.']
  };
  const data = rows[def.key] || ['DEVICE SIM', def.task || 'Menu adimini dogru sec.'];
  return `<div class="device-sim-overlay ${st.alert?'warn':''}">
    <b>${phoneSafe(data[0])}</b>
    <span>${phoneSafe(data[1])}</span>
  </div>`;
}

function buildDeviceScreen(def){
  const panel = {
    radar:GFX.radar,
    ecdis:GFX.ecdis_panel,
    ais:GFX.ais_panel,
    gyro:GFX.gyro_panel,
    echo:GFX.echo_panel,
    speedlog:GFX.speedlog_panel,
    autopilot:GFX.autopilot_panel,
    bnwas:GFX.bnwas_panel
  }[def.key];
  const hint = `<button class="device-zoom-toggle" onclick="event.stopPropagation(); toggleDeviceScreenZoom()">${deviceScreenZoomed?'Kucult':'Buyut'}</button>`;
  const svg = panel
    ? `<svg viewBox="0 0 480 145" xmlns="http://www.w3.org/2000/svg">${panel}</svg>`
    : `<svg viewBox="0 0 480 145" xmlns="http://www.w3.org/2000/svg">${buildGmdssDeviceSvg(def)}</svg>`;
  return `<div class="device-console-shell device-console-${phoneSafe(def.key)}">
    ${svg}
    ${getDeviceLiveStrip(def)}
    ${buildDeviceMenuOverlay(def)}
    ${getDeviceSimOverlay(def)}
    ${hint}
  </div>`;
}

function buildDeviceMenuOverlay(def){
  const entries = getDeviceMenuEntries(def);
  const expected = getDeviceExpectedAction(def);
  return `<div class="device-screen-menu">
    <div class="device-screen-menu-head">${getDeviceBreadcrumb(def)}</div>
    ${entries.map(e=>`<div class="device-screen-menu-row ${e.label===expected?'target':''}">${e.type==='submenu'?'DIR':'KEY'} · ${e.label}</div>`).join('')}
  </div>`;
}

