function togglePhone(){
  if(!phoneOpen && !canUseFeature('phone')) return;
  if(!phoneOpen) completeMissionFromFeature('phone');
  phoneOpen = !phoneOpen;
  renderPhone();
}
function setPhoneTab(tab){
  phoneTab = tab;
  renderPhone();
}
function setPhoneContact(name){
  ensureFamilyGroup();
  activePhoneContact = familyNames().includes(name) ? 'AILE' : name;
  if(isFamilyChat(activePhoneContact)) familyUnread = 0;
  phoneTab = 'messages';
  renderPhone();
}

function getVoyageRouteByKey(key){
  return TRADE_VOYAGE_ROUTES.find(r=>r.key === key) || TRADE_VOYAGE_ROUTES[0];
}

const MAJOR_TRADE_ROUTE_KEYS = [
  'eu_far_east',
  'india_europe_container',
  'china_us_east_coast_suez',
  'med_shortsea_feeder',
  'transpacific',
  'north_atlantic',
  'gulf_asia_energy',
  'panama_neo_panamax_chain',
  'suez_redsea_resilience',
  'brazil_china_bulk',
  'south_america_europe_reefer',
  'rio_plate_europe_grain',
  'car_carrier_asia_europe',
  'jebelali_east_africa_feeder',
  'round_world_training_route',
  'us_pnw_asia_grain',
  'australia_japan_lng',
  'gulf_europe_crude_cape',
  'blacksea_india_bulk',
  'west_med_west_africa_feeder',
  'north_europe_canada_stlawrence',
  'med_us_gulf_products',
  'asia_australia_container',
  'australia_china_iron',
  'indonesia_china_coal',
  'west_africa_europe_tanker',
  'blacksea_grain_med',
  'turkey_adriatic_roro'
];

function getMajorTradeRouteChoices(type=selType){
  const preferred = new Set(MAJOR_TRADE_ROUTE_KEYS);
  const typePick = selectVoyageRouteForShipType(type);
  const routes = TRADE_VOYAGE_ROUTES
    .filter(r=>preferred.has(r.key))
    .concat(typePick ? [typePick] : [])
    .filter((r, idx, arr)=>r && arr.findIndex(x=>x.key===r.key)===idx);
  return routes;
}

function setSelectedVoyageRoute(key){
  selectedVoyageRouteKey = TRADE_VOYAGE_ROUTES.some(r=>r.key===key) ? key : '';
  renderVoyageRouteSelector();
  renderShipChoiceSummary();
}

function getSelectedVoyageRoute(){
  return selectedVoyageRouteKey ? getVoyageRouteByKey(selectedVoyageRouteKey) : selectVoyageRouteForShipType(selType);
}

function renderVoyageRouteSelector(){
  const box = document.getElementById('route-select-grid');
  if(!box) return;
  if(!Array.isArray(TRADE_VOYAGE_ROUTES) || !TRADE_VOYAGE_ROUTES.length) return;
  const choices = getMajorTradeRouteChoices(selType);
  if(!selectedVoyageRouteKey && choices[0]) selectedVoyageRouteKey = choices[0].key;
  box.innerHTML = choices.map(route=>{
    const active = route.key === selectedVoyageRouteKey;
    const wpCount = route.waypoints?.length || 0;
    return `<button type="button" class="route-card ${active?'active':''}" onclick="setSelectedVoyageRoute('${route.key}')">
      <b>${phoneSafe(route.name)}</b>
      <span>${phoneSafe(route.trade)} · ${route.distanceNm} NM · ${route.etaDays} gun</span>
      <small>${phoneSafe(route.start)} → ${phoneSafe(route.end)} · ${wpCount} waypoint</small>
    </button>`;
  }).join('');
  renderShipChoiceSummary();
}

function selectVoyageRouteForShipType(type=selType){
  const typeKey = String(type || '').toLowerCase();
  let candidates = TRADE_VOYAGE_ROUTES;
  if(/tanker|lng/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/energy|gulf|tanker|lng|west_africa|norway|shuttle|offload|jebelali|crude|products|australia_japan_lng|med_us_gulf/.test(`${r.key} ${r.trade}`));
  else if(/bulk|kuru/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/blacksea|brazil|australia|indonesia|us_gulf|bulk|komur|cevheri|tahil|grain|rio_plate|pnw|blacksea_india/.test(`${r.key} ${r.trade}`));
  else if(/kont|container/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/eu_far_east|transpacific|north_atlantic|panama_far_east|feeder|konteyner|container|india_europe|china_us|med_shortsea|round_world|stlawrence|asia_australia/.test(`${r.key} ${r.trade}`));
  else if(/roro/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/roro|feeder|turkey_adriatic|blacksea|eu_far_east|car_carrier|pctc|vehicle/.test(`${r.key} ${r.trade}`));
  else if(/proje|project/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/project|proje|heavy|modul/.test(`${r.key} ${r.trade}`));
  else if(/kruvaziyer|cruise/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/cruise|kruvaziyer|passenger/.test(`${r.key} ${r.trade}`));
  else if(/arastirma|research|survey/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/research|arastirma|survey|oceanographic|hydrographic/.test(`${r.key} ${r.trade}`));
  else if(/offshore|psv|ahts/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/offshore|platform|psv|ahts/.test(`${r.key} ${r.trade}`));
  else if(/buz|ice/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/ice|buz|baltic_ice|convoy/.test(`${r.key} ${r.trade}`));
  else if(/cable/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/cable|kablo|subsea/.test(`${r.key} ${r.trade}`));
  else if(/pipe/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/pipe|boru|lay/.test(`${r.key} ${r.trade}`));
  else if(/shuttle|fpso/.test(typeKey)) candidates = TRADE_VOYAGE_ROUTES.filter(r=>/shuttle|fpso|offload/.test(`${r.key} ${r.trade}`));
  return candidates[Math.floor(Math.random()*candidates.length)] || TRADE_VOYAGE_ROUTES[0];
}
function findStartPortByName(name){
  const clean = normalizeTrAscii(name || '');
  return START_PORTS.find(p=>normalizeTrAscii(p.name) === clean)
    || START_PORTS.find(p=>normalizeTrAscii(p.name).includes(clean) || clean.includes(normalizeTrAscii(p.name)))
    || START_PORTS[0];
}
function activateVoyageRoute(routeOrKey){
  const route = typeof routeOrKey === 'string' ? getVoyageRouteByKey(routeOrKey) : (routeOrKey || selectVoyageRouteForShipType());
  activeVoyageRoute = JSON.parse(JSON.stringify(route));
  activeVoyageProgress = 0;
  const first = activeVoyageRoute.waypoints[0];
  if(first){
    shipPosition = {x:first.x, y:first.y};
    routeHistory = [{x:first.x,y:first.y}];
    visitedPorts = new Set([activeVoyageRoute.start, first.name, first.chart].filter(Boolean));
    selectedPortChart = first.chart || activeVoyageRoute.chart;
  }
  return activeVoyageRoute;
}
function getActiveVoyageRoute(){
  if(!activeVoyageRoute) activateVoyageRoute(selectVoyageRouteForShipType());
  return activeVoyageRoute;
}
function getVoyageWaypoint(index=activeVoyageProgress){
  const route = getActiveVoyageRoute();
  return route?.waypoints?.[Math.max(0, Math.min(route.waypoints.length-1, index))] || null;
}
function getVoyageLegProgress(){
  const route = getActiveVoyageRoute();
  if(!route?.waypoints?.length) return 0;
  return Math.round((Math.max(0, activeVoyageProgress) / Math.max(1, route.waypoints.length-1)) * 100);
}
function advanceVoyageRoute(step=1, reason='seyir'){
  const route = getActiveVoyageRoute();
  if(!route?.waypoints?.length) return null;
  activeVoyageProgress = Math.max(0, Math.min(route.waypoints.length-1, activeVoyageProgress + step));
  const wp = getVoyageWaypoint(activeVoyageProgress);
  if(wp){
    shipPosition = {x:wp.x, y:wp.y};
    routeHistory.push({x:wp.x, y:wp.y});
    visitedPorts.add(wp.name);
    if(wp.chart) visitedPorts.add(wp.chart);
    if(wp.chart) selectedPortChart = wp.chart;
    addLiveLogbook('ROUTE MONITOR', `${route.name}: ${wp.name} · ${wp.note}`, true);
    addWatchFeed(`Rota ilerledi: ${wp.name}`, /security|weather|traffic|tss/i.test(wp.risk||'') ? 'warn' : '');
    createLiveVoyageWaypointEvent(wp, route, reason);
  }
  return wp;
}

function getVoyageWaypointEventType(wp={}, route={}){
  const blob = `${wp.name || ''} ${wp.note || ''} ${wp.risk || ''} ${route.name || ''} ${route.trade || ''}`.toLowerCase();
  if(/pilot|berth|approach|port|terminal/.test(blob)) return 'pilot';
  if(/tss|traffic|strait|channel|dover|malacca|suez|panama|hormuz|bosphorus|dardanelles/.test(blob)) return 'vts';
  if(/weather|swell|monsoon|storm|atlantic|ice|icing/.test(blob)) return 'weather';
  if(/ukc|draft|shallow|canal|river|squat/.test(blob)) return 'ukc';
  if(/security|piracy|aden|bab|high risk/.test(blob)) return 'security';
  return 'cpa';
}

function createLiveVoyageWaypointEvent(wp, route, reason='route'){
  if(!wp || !route) return null;
  const key = `${route.key || route.name}-${activeVoyageProgress}-${wp.name}`;
  if(liveVoyageEventState.lastKey === key) return null;
  liveVoyageEventState.lastKey = key;
  const type = getVoyageWaypointEventType(wp, route);
  const st = computeLiveVoyageState(sceneQueue[currentIdx] || {});
  const templates = {
    pilot:{title:'Pilot / Approach Event', msg:`${wp.name}: pilot station, VHF channel, speed reduction and ladder readiness must be checked.`, action:'openMap()'},
    vts:{title:'VTS / Traffic Event', msg:`${wp.name}: reporting point, TSS lane, CPA/TCPA and VHF watch are now active.`, action:'openDevices()'},
    weather:{title:'Weather Routing Event', msg:`${wp.name}: swell/weather note is active; route margin, speed and watch handover need a short report.`, action:'openMap()'},
    ukc:{title:'UKC / Squat Event', msg:`${wp.name}: draft, UKC, tide window and safety contour should be reviewed before next leg.`, action:'openMap()'},
    security:{title:'Security Watch Event', msg:`${wp.name}: BMP/ISPS watch, door control, radar targets and VHF readiness must be confirmed.`, action:'openDevices()'},
    cpa:{title:'CPA Watch Event', msg:`${wp.name}: ARPA acquire, AIS compare, ECDIS route monitor and logbook note are expected.`, action:'openDevices()'}
  };
  const event = {
    key,
    type,
    title:templates[type].title,
    msg:templates[type].msg,
    action:templates[type].action,
    route:route.name,
    chart:wp.chart || route.chart || selectedPortChart,
    progress:getVoyageLegProgress(),
    eta:st.eta,
    cpa:st.cpa,
    ukc:st.ukc,
    reason,
    ts:Date.now()
  };
  liveVoyageEventState.events = [event, ...(liveVoyageEventState.events || [])].slice(0,8);
  addWatchFeed(`${event.title}: ${event.msg}`, ['weather','security','ukc'].includes(type) ? 'warn' : 'good');
  addLiveLogbook('WAYPOINT EVENT', `${event.route}: ${event.msg} ETA ${event.eta}, CPA ${event.cpa}, UKC ${event.ukc}.`, true);
  pushPhoneMessage(type === 'pilot' ? 'Acenta' : type === 'vts' ? 'VTS' : type === 'security' ? 'Kaptan' : 'Kopruustu', event.msg, {open:false});
  if(event.chart) selectedPortChart = event.chart;
  if(panelIsOpen('sim-panel')) renderSimCenter();
  return event;
}
function makeVoyageScene(route, wp, idx){
  const isFirst = idx === 0;
  const isLast = idx >= route.waypoints.length - 1;
  const risk = wp.risk || 'Route monitoring';
  const loc = isFirst ? `${wp.name} - Departure` : isLast ? `${wp.name} - Landfall / Approach` : `${wp.name} - Passage Monitor`;
  const gfx = /weather|swell|heavy|monsoon/i.test(risk) ? 'storm' : /pilot|approach|port|berth/i.test(risk+wp.note) ? 'harbor' : /traffic|tss|security|canal|narrow/i.test(risk) ? 'radar' : 'ecdis_panel';
  return {
    id:`voyage_${route.key}_${idx}`,
    gfx,
    alert:/security|heavy|alarm|traffic|tss/i.test(risk),
    day:`Seyir ${idx+1}`,
    time:['04:20','08:00','12:00','16:00','20:00'][idx%5],
    loc,
    sub:`${route.name} · ${route.trade}`,
    who: idx%3===0?'z2':idx%3===1?'z1':'suvari',
    voyageRouteKey:route.key,
    voyageWpIndex:idx,
    text:`ECDIS route monitor ${route.name} hattini gosteriyor.

Aktif waypoint: ${wp.name}
Chart: ${wp.chart || route.chart}
Not: ${wp.note}
Risk: ${risk}

2. Zabiti senden seyir mantigini net duymak istiyor: bu noktada once neyi kontrol edersin?`,
    choices:[
      {text:'ECDIS route monitor, radar/AIS cross-check, waypoint notu ve logbook zincirini birlikte kontrol ederim',tag:'kritik',effect:{bilgi:16,sayginlik:10,dinclik:-2},voyageAdvance:true,chartName:wp.chart},
      {text:'Once harita chartini acar, TSS/reporting/UKC veya hava notunu okuyup kaptana kisa rapor veririm',tag:'akilli',effect:{bilgi:13,sayginlik:8},voyageAdvance:true,chartName:wp.chart},
      {text:'Sadece ETA iyi gorunuyorsa rotayi aynen takip ederim',tag:'itaatkar',effect:{bilgi:3,sayginlik:-2,dinclik:1},voyageAdvance:true,chartName:wp.chart},
      {text:'Hiz kazanmak icin safety contour ve alternatif rota uyarilarini sonra kontrol ederim',tag:'hileli',effect:{bilgi:-10,sayginlik:-9,dinclik:-3},voyageAdvance:false,chartName:wp.chart}
    ]
  };
}
function buildVoyageScenesForRoute(route, totalDays){
  const maxScenes = Math.min(route.waypoints.length, Math.max(4, Math.floor(totalDays / 5)));
  const picks = [];
  const last = route.waypoints.length - 1;
  for(let i=0;i<maxScenes;i++){
    const idx = maxScenes === 1 ? 0 : Math.round((i/(maxScenes-1))*last);
    if(!picks.includes(idx)) picks.push(idx);
  }
  if(!picks.includes(last)) picks.push(last);
  return picks.slice(0, Math.min(7, picks.length)).map(idx=>makeVoyageScene(route, route.waypoints[idx], idx));
}
