function renderInteractionPanel(sc, ch){
  const panel = document.getElementById('calc-panel');
  const cfg = INTERACTION_PANEL_CONFIGS[sc?.id] || getAutoInteractionConfig(sc);
  if(!panel || !cfg) return false;
  const kind = getInteractionKind(cfg, sc);
  cfg.kind = kind;
  panel.className='calc-panel show';
  const visual = kind === 'vhf'
    ? renderVhfInteractionVisual(cfg)
    : kind === 'radar' ? renderRadarInteractionVisual(cfg)
    : kind === 'ecdis' ? renderEcdisInteractionVisual(cfg)
    : kind === 'fire' ? renderFireInteractionVisual(cfg)
    : kind === 'survival' ? renderSurvivalInteractionVisual(cfg)
    : kind === 'bunker' ? renderBunkerInteractionVisual(cfg)
    : kind === 'mob' ? renderMobInteractionVisual(cfg)
    : kind === 'mooring' ? renderMooringInteractionVisual(cfg)
    : renderGenericInteractionVisual(cfg);
  panel.dataset.locked = '';
  panel.innerHTML = `<div class="decision-box">
    <div class="decision-title">${cfg.title}</div>
    <div class="decision-hint">${cfg.hint}</div>
    ${renderInteractionGuideCard(kind)}
    ${visual}
    <div id="interaction-feedback" class="decision-feedback"></div>
  </div>`;
  panel.querySelectorAll('[data-hotspot]').forEach(btn=>{
    btn.onclick=(ev)=>{
      if(panel.dataset.locked === 'true') return;
      const hit = ev.target.closest('[data-hotspot]') || btn;
      const pickedId = hit.dataset.hotspot;
      const picked = pickedId === cfg.expected
        ? (sc.choices.find(c=>c.tag===cfg.correctTag) || sc.choices[0])
        : (sc.choices.find(c=>c.tag===cfg.midTag) || sc.choices[1] || sc.choices[0]);
      const feedback = document.getElementById('interaction-feedback');
      const good = pickedId === cfg.expected;
      if(kind === 'vhf') completeMissionStep('vhf', good ? 'VHF kanali dogru secildi' : 'VHF kanali secildi, teyit gerekli');
      else if(kind === 'mooring' || kind === 'bunker' || kind === 'survival') completeMissionStep('deck', good ? `${cfg.title} dogru secildi` : `${cfg.title} tekrar kontrol gerekli`);
      else if(kind === 'fire' || kind === 'mob') completeMissionStep('alarm', good ? `${cfg.title} dogru secildi` : `${cfg.title} tekrar kontrol gerekli`);
      else completeMissionStep(kind === 'radar' ? 'radar' : kind === 'ecdis' ? 'ecdis' : 'device');
      feedback.className = `decision-feedback ${good?'':'warn'}`.trim();
      feedback.innerHTML = `<b>${phoneSafe(good ? 'Dogru karar' : 'Tekrar oku')}</b><span>${phoneSafe(getInteractionFeedbackText(kind, good))}</span>${renderInteractionReplay(kind, good)}`;
      panel.dataset.locked = 'true';
      panel.querySelectorAll('[data-hotspot]').forEach(el=>el.disabled=true);
      setTimeout(()=>handleSceneChoice(sc,picked,ch),850);
    };
  });
  normalizeClickableSurface('#calc-panel button,#calc-panel [data-hotspot]');
  return true;
}

// ===== SİSTEMLERİ ENTEGRE ET =====
// Bu fonksiyon mevcut renderScene'e ek olarak çalışır
function onSceneRender(sc){
  const sceneArea = document.getElementById('scene-area');
  if(sceneArea){
    sceneArea.classList.remove('scene-fade-once');
    void sceneArea.offsetWidth;
    sceneArea.classList.add('scene-fade-once');
  }
  // Hava güncelle
  updateWeather(sc.gfx);
  updateOpsHud(sc);
  syncWatchDirector3(sc);
  tickWorkRestFromScene(sc);
  applyScenePsychDrift(sc);
  maybeTriggerCompanyPressureBeat(sc);
  // Harita pozisyonunu güncelle
  if(sc?.voyageRouteKey){
    const route = getActiveVoyageRoute();
    const wp = route?.waypoints?.[sc.voyageWpIndex || 0];
    if(wp){
      shipPosition = {x:wp.x, y:wp.y};
      selectedPortChart = wp.chart || route.chart || selectedPortChart;
      visitedPorts.add(wp.name);
      if(wp.chart) visitedPorts.add(wp.chart);
    }
  }else{
    updateShipPosition(sc.loc);
  }
  autoOpenVoyageChart(sc);
  // Gün sayacını güncelle
  if(sc.day) {
    const m = sc.day.match(/\d+/);
    if(m) currentDay = parseInt(m[0]);
  }
  // Crew trust güncelle (sahne gösteriminde +1 tanışma)
  const crewKey = getCrewKeyFromWho(sc.who);
  if(crewKey) updateCrewTrust(crewKey, 1);
  // Önemli anlarda fotoğraf çek
  if(sc.alert) tryAddMomentPhoto(`scene-${sc.id}`, `ACIL: ${sc.sub}`, sc.day+' · '+sc.time, sc.gfx);
  else if(sc.id==='s01') tryAddMomentPhoto('scene-s01', 'Ilk Adim', 'Iskeleye ilk kez ayak basiyorum...', 'harbor');
  else if(sc.id==='FINAL') tryAddMomentPhoto('scene-final', 'Son Gun', 'Bu yolculugun son sahnesi.', 'bridge');
  else maybeAddOceanPhoto(sc);
  if(!careerMemory.firstPilot && (sc.id==='s134' || sc.id==='s361')){
    careerMemory.firstPilot = true;
    tryAddMomentPhoto('career-first-pilot','Ilk Pilot','Ilk ciddi pilot brifingini yasadim. Kopru bir anda daha resmi geldi.','bridge');
  }
  if(!careerMemory.firstStorm && (/storm/.test(sc.gfx||'') || sc.id==='kriz04' || sc.id==='kriz05b' || sc.id==='s258')){
    careerMemory.firstStorm = true;
    tryAddMomentPhoto('career-first-storm','Ilk Firtina','Ilk sert hava gecisinde geminin gercekten yasadigini hissettim.','storm');
  }
  if(!careerMemory.firstAllFast && (sc.id==='s364' || /all fast/i.test(`${sc.loc||''} ${sc.sub||''}`))){
    careerMemory.firstAllFast = true;
    tryAddMomentPhoto('career-first-allfast','Ilk All Fast','Halatlar oturdu, gemi rihtima nefes alarak yaslandi.','harbor');
  }
  if(!careerMemory.firstNearMiss && (sc.id==='s124' || sc.id==='s124b' || sc.id==='s129')){
    careerMemory.firstNearMiss = true;
    tryAddMomentPhoto('career-first-nearmiss','Ilk Near-Miss','Buyumeden duran bir olay bile insanin icine oturuyor.','cargo');
  }
  if(!careerMemory.firstPraise && (sc.id==='s371' || sc.id==='s373' || sc.id==='s384')){
    careerMemory.firstPraise = true;
    tryAddMomentPhoto('career-first-praise','Ilk Tebrik','Bir ustun gozunde ilk kez gercekten bir seylerin oturdugunu hissettim.','bridge');
  }
  if(sc.id==='s365') tryAddMomentPhoto('ops-container-bayplan','Konteyner Plani','Bay / row / tier baskisinin sadece sayi degil, denge ve sequence isi oldugunu ilk kez net gordum.','cargo');
  if(sc.id==='s366' || sc.id==='s381') tryAddMomentPhoto('ops-tanker-manifold','Manifold Hatti','Terminal tarafinda line-up ve ESD teyidi bende ilk kez gercek operasyon hissi yaratti.','cargo');
  if(sc.id==='s367' || sc.id==='s382') tryAddMomentPhoto('ops-bulk-loading','Bulk Yuk Akisi','Trim, draft ve loading order ayni anda kafamda oturmaya basladi.','cargo');
  if(sc.id==='s383') tryAddMomentPhoto('ops-project-cargo','Agir Yuk Gunu','COG, sling angle ve exclusion zone bir anda kagittan cikti, sahaya indi.','cargo');
  if(sc.id==='s447') tryAddMomentPhoto('career-first-survey','Ilk Survey','Surveyor gemiye adim attiginda herkes ayni anda daha dik durmaya basladi.','harbor');
  if(sc.id==='s391' || sc.id==='s397' || sc.id==='s398') tryAddMomentPhoto('career-incident-followup','Soruşturma Dosyasi','Near-miss raporunun kapanmasi degil, takibi ve dersi asil agir kismiymis.','bridge');
  const hint = COLREG_HINTS[sc.id];
  if(hint && !seenColregHints.has(sc.id)){
    seenColregHints.add(sc.id);
    setTimeout(()=>{
      showNotif(hint.icon, hint.title, hint.body);
      addJournalEntry(`[COLREG] ${hint.body}`, sc.day, sc.time);
    }, 250);
  }
  scheduleSceneLiveSequence(sc);
  maybeTriggerMidScenePhone(sc);
  maybeTriggerAiMateSceneNudge(sc);
  maybeTriggerLivingShipBeat(sc);
  maybeTriggerLiveRoutineFlow(sc);
  maybeTriggerSurpriseInspection(sc);
  scheduleDynamicMiniChain(sc);
  // Rastgele olay
  maybeTrigerEvent();
}


// ===== SES SİSTEMİ (Web Audio API) =====
let audioCtx = null;
let currentMusic = null;
let musicGain = null;
let sceneAudioLoopTimers = [];
let introThemePlaying = false;
let introThemeTimers = [];
const INTRO_THEME_SRC = './assets/audio/groan-of-the-keel.mp3';
let introRecordedTrack = null;
let introRecordedTrackFadeTimer = null;
let introRecordedTrackFailed = false;

const VIBRATION_PREF_KEY = 'guverte-vibration-enabled';
const VIBRATION_PATTERNS = {
  'oneshot-mob-flash':[180,80,180,80,260],
  'oneshot-rope-snap':[90,45,180,40,80],
  'oneshot-fire-pulse':[120,80,120,80,240],
  'oneshot-storm-hit':[80,70,80],
  'oneshot-engine-hit':[160,90,260],
  'oneshot-vhf-burst':[45,45,45,100,90],
  'oneshot-sensor-glow':[35],
  crisis:[220,90,220,90,320],
  danger:[120,70,160]
};
let vibrationEnabled = (()=>{try{return localStorage.getItem(VIBRATION_PREF_KEY) !== '0';}catch(e){return true;}})();
let lastVibrationAt = 0;
let soundEnabled = true;
let audioLevels = {music:.48, effects:.92, ambiance:.78};
function toggleSound(){
  soundEnabled = !soundEnabled;
  document.querySelectorAll('#sound-btn,#home-sound-btn,#game-settings-sound-btn').forEach(btn=>{
    if(btn) btn.textContent = soundEnabled ? `🔊 ${t('ui.soundOn','Ses Acik')}` : `🔇 ${t('ui.soundOff','Ses Kapali')}`;
  });
  if(!soundEnabled) stopAllMusic();
  else maybeStartIntroMaritimeTheme();
  renderAudioMixer();
}

function canVibrateDevice(){
  return vibrationEnabled && typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function';
}

function stopDeviceVibration(){
  try{
    if(typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') navigator.vibrate(0);
  }catch(e){}
}

function vibrateDanger(pattern='danger', minGap=900){
  if(!canVibrateDevice()) return false;
  const now = Date.now();
  if(now - lastVibrationAt < minGap) return false;
  const value = Array.isArray(pattern) ? pattern : (VIBRATION_PATTERNS[pattern] || VIBRATION_PATTERNS.danger);
  try{
    navigator.vibrate(value);
    lastVibrationAt = now;
    return true;
  }catch(e){
    return false;
  }
}

function toggleVibration(force){
  vibrationEnabled = typeof force === 'boolean' ? force : !vibrationEnabled;
  try{localStorage.setItem(VIBRATION_PREF_KEY, vibrationEnabled ? '1' : '0');}catch(e){}
  if(!vibrationEnabled) stopDeviceVibration();
  applyLanguageUI();
  if(phoneOpen) renderPhone();
  showNotif('VIB', t('ui.vibration','Tehlike titresimi'), vibrationEnabled ? t('ui.vibrationOn','Titresim acik') : t('ui.vibrationOff','Titresim kapali'));
}

function clampAudioLevel(value){
  return Math.max(0, Math.min(1, Number(value) || 0));
}

function getAudioLevel(kind){
  return soundEnabled ? clampAudioLevel(audioLevels[kind] == null ? 1 : audioLevels[kind]) : 0;
}

function setAudioLevel(kind, value){
  if(!['music','effects','ambiance'].includes(kind)) return;
  audioLevels[kind] = clampAudioLevel(value);
  if(kind === 'music'){
    if(introRecordedTrack && introThemePlaying){
      introRecordedTrack.volume = .48 * getAudioLevel('music');
    }
    if(musicGain && audioCtx){
      musicGain.gain.setTargetAtTime(.78 * getAudioLevel('music'), audioCtx.currentTime, .18);
    }
  }
  renderAudioMixer();
}

function renderAudioMixer(){
  const rows = [
    ['music','Muzik'],
    ['effects','Efekt'],
    ['ambiance','Ambiyans']
  ].map(([key,label])=>{
    const value = Math.round(getAudioLevel(key) * 100);
    return `<label class="audio-row"><b>${label}</b><input type="range" min="0" max="100" value="${value}" data-audio-kind="${key}" oninput="setAudioLevel('${key}', this.value/100)"><output>${value}%</output></label>`;
  }).join('');
  document.querySelectorAll('.audio-mixer').forEach(box=>{
    box.innerHTML = rows;
    box.classList.toggle('muted', !soundEnabled);
  });
}

const _origPlayTone = playTone;
// Wrap functions to respect soundEnabled - handled by checking at call sites

function getAudioCtx(){
  if(!soundEnabled) return null;
  if(!audioCtx){
    try{
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }catch(e){ return null; }
  }
  if(audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

// Basit ses efekti üreticisi - Web Audio API ile synthtic sesler
function playTone(freq, type, duration, vol, delay=0){
  const ctx = getAudioCtx();
  if(!ctx) return;
  vol = Math.max(0.0001, Number(vol || 0) * getAudioLevel('effects'));
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.frequency.value = freq;
  osc.type = type;
  gain.gain.setValueAtTime(0, ctx.currentTime + delay);
  gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + delay + 0.05);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + delay + duration);
  osc.start(ctx.currentTime + delay);
  osc.stop(ctx.currentTime + delay + duration + 0.1);
}

function playNoise(duration, vol, delay=0){
  const ctx = getAudioCtx();
  if(!ctx) return;
  vol = Math.max(0.0001, Number(vol || 0) * getAudioLevel('effects'));
  const bufSize = ctx.sampleRate * duration;
  const buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for(let i=0;i<bufSize;i++) data[i] = (Math.random()*2-1);
  const src = ctx.createBufferSource();
  const gain = ctx.createGain();
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 400;
  src.buffer = buf;
  src.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  gain.gain.setValueAtTime(0, ctx.currentTime + delay);
  gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + delay + 0.1);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + delay + duration);
  src.start(ctx.currentTime + delay);
  src.stop(ctx.currentTime + delay + duration + 0.1);
}

// Müzik/ambians döngü sistemi
let ambianceNodes = [];
function stopAllMusic(){
  stopIntroRecordedTrack(true);
  introThemePlaying = false;
  introThemeTimers.forEach(t=>clearTimeout(t));
  introThemeTimers = [];
  ambianceNodes.forEach(n=>{ try{ n.stop(); }catch(e){} });
  ambianceNodes = [];
  if(musicGain) musicGain.gain.setTargetAtTime(0, getAudioCtx()?.currentTime||0, 0.3);
}

function clearSceneAudioLoops(){
  sceneAudioLoopTimers.forEach(t=>clearTimeout(t));
  sceneAudioLoopTimers = [];
}

function playDroneNote(freq, vol, ctx){
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.value = freq;
  gain.gain.value = Math.max(0.0001, Number(vol || 0) * getAudioLevel('ambiance'));
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start();
  ambianceNodes.push(osc);
  return osc;
}

function isIntroAudioScreen(){
  return document.body.classList.contains('screen-home');
}

function getIntroRecordedTrack(){
  if(introRecordedTrack || introRecordedTrackFailed) return introRecordedTrack;
  try{
    introRecordedTrack = new Audio(INTRO_THEME_SRC);
    introRecordedTrack.preload = 'auto';
    introRecordedTrack.loop = true;
    introRecordedTrack.volume = 0.0001;
  }catch(e){
    introRecordedTrackFailed = true;
  }
  return introRecordedTrack;
}

function fadeIntroRecordedTrack(target=.46, ms=1500){
  const audio = introRecordedTrack;
  if(!audio) return;
  if(introRecordedTrackFadeTimer) clearInterval(introRecordedTrackFadeTimer);
  const start = audio.volume || 0.0001;
  const startedAt = Date.now();
  introRecordedTrackFadeTimer = setInterval(()=>{
    const t = Math.min(1, (Date.now() - startedAt) / Math.max(1, ms));
    audio.volume = start + (target - start) * t;
    if(t >= 1){
      clearInterval(introRecordedTrackFadeTimer);
      introRecordedTrackFadeTimer = null;
    }
  }, 80);
}

function stopIntroRecordedTrack(reset=false){
  if(introRecordedTrackFadeTimer){
    clearInterval(introRecordedTrackFadeTimer);
    introRecordedTrackFadeTimer = null;
  }
  if(!introRecordedTrack) return;
  try{
    introRecordedTrack.pause();
    introRecordedTrack.volume = 0.0001;
    if(reset) introRecordedTrack.currentTime = 0;
  }catch(e){}
}

function startIntroRecordedTrack(){
  const audio = getIntroRecordedTrack();
  if(!audio || introRecordedTrackFailed) return false;
  try{
    audio.volume = 0.0001;
    const playPromise = audio.play();
    if(playPromise && typeof playPromise.then === 'function'){
      playPromise
        .then(()=>fadeIntroRecordedTrack(.48 * getAudioLevel('music'), 1800))
        .catch(()=>{
          introRecordedTrackFailed = true;
          stopIntroRecordedTrack(true);
          if(introThemePlaying && soundEnabled && isIntroAudioScreen()) playIntroSynthMaritimeTheme();
        });
    }else{
      fadeIntroRecordedTrack(.48 * getAudioLevel('music'), 1800);
    }
    return true;
  }catch(e){
    introRecordedTrackFailed = true;
    stopIntroRecordedTrack(true);
    return false;
  }
}

function playIntroThemeNote(freq, delay=0, dur=.72, vol=.035){
  const ctx = getAudioCtx();
  if(!ctx || !musicGain) return;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  const filter = ctx.createBiquadFilter();
  osc.type = 'triangle';
  osc.frequency.value = freq;
  filter.type = 'lowpass';
  filter.frequency.value = 880;
  gain.gain.setValueAtTime(0.0001, ctx.currentTime + delay);
  gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + delay + .06);
  gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + delay + dur);
  osc.connect(filter);
  filter.connect(gain);
  gain.connect(musicGain);
  osc.start(ctx.currentTime + delay);
  osc.stop(ctx.currentTime + delay + dur + .08);
}

function playIntroMaritimeTheme(){
  if(!soundEnabled || !isIntroAudioScreen() || introThemePlaying) return;
  stopAllMusic();
  introThemePlaying = true;
  if(startIntroRecordedTrack()) return;
  playIntroSynthMaritimeTheme();
}

function playIntroSynthMaritimeTheme(){
  const ctx = getAudioCtx();
  if(!ctx) return;
  musicGain = ctx.createGain();
  musicGain.gain.setValueAtTime(0.0001, ctx.currentTime);
  musicGain.gain.linearRampToValueAtTime(0.78 * getAudioLevel('music'), ctx.currentTime + 1.2);
  musicGain.connect(ctx.destination);

  const low = ctx.createOscillator();
  const mid = ctx.createOscillator();
  const lfo = ctx.createOscillator();
  const lfoGain = ctx.createGain();
  const droneGain = ctx.createGain();
  low.type = 'sine';
  mid.type = 'triangle';
  low.frequency.value = 48;
  mid.frequency.value = 96;
  lfo.frequency.value = .08;
  lfoGain.gain.value = .012;
  droneGain.gain.value = .028 * getAudioLevel('ambiance');
  lfo.connect(lfoGain);
  lfoGain.connect(droneGain.gain);
  low.connect(droneGain);
  mid.connect(droneGain);
  droneGain.connect(musicGain);
  low.start(); mid.start(); lfo.start();
  ambianceNodes.push(low, mid, lfo);

  const motif = [196, 246.94, 293.66, 329.63, 293.66, 246.94, 220, 196];
  function motifLoop(){
    if(!introThemePlaying || !soundEnabled || !isIntroAudioScreen()) return;
    motif.forEach((freq,i)=>playIntroThemeNote(freq, i*.58, i===3 ? 1.05 : .64, i===3 ? .046 : .032));
    playIntroThemeNote(98, 0, 3.8, .018);
    playIntroThemeNote(146.83, 2.4, 2.4, .016);
    introThemeTimers.push(setTimeout(motifLoop, 7600));
  }
  function seaBreath(){
    if(!introThemePlaying || !soundEnabled || !isIntroAudioScreen()) return;
    playNoise(.34, .012);
    introThemeTimers.push(setTimeout(seaBreath, 4200 + Math.random()*1800));
  }
  motifLoop();
  introThemeTimers.push(setTimeout(seaBreath, 1200));
}

function stopIntroMaritimeTheme(){
  stopIntroRecordedTrack(true);
  introThemePlaying = false;
  introThemeTimers.forEach(t=>clearTimeout(t));
  introThemeTimers = [];
}

function maybeStartIntroMaritimeTheme(){
  if(!soundEnabled || !isIntroAudioScreen()) return;
  playIntroMaritimeTheme();
}

