function playSoftWaveWash(vol=.08, duration=2.8, delay=0){
  const ctx = getAudioCtx();
  if(!ctx) return;
  const seconds = Math.max(.5, Number(duration) || 2.8);
  const bufSize = Math.max(1, Math.floor(ctx.sampleRate * seconds));
  const buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
  const data = buf.getChannelData(0);
  let brown = 0;
  for(let i=0;i<bufSize;i++){
    brown = (brown + (Math.random()*2-1) * .035) * .985;
    const t = i / bufSize;
    const rise = Math.min(1, t / .22);
    const fall = Math.min(1, (1 - t) / .42);
    const swell = Math.sin(Math.PI * t);
    data[i] = brown * rise * fall * (.52 + swell * .48);
  }
  const src = ctx.createBufferSource();
  const low = ctx.createBiquadFilter();
  const high = ctx.createBiquadFilter();
  const gain = ctx.createGain();
  low.type = 'lowpass';
  low.frequency.value = 820;
  high.type = 'highpass';
  high.frequency.value = 38;
  gain.gain.setValueAtTime(0.0001, ctx.currentTime + delay);
  gain.gain.linearRampToValueAtTime(Math.max(0.0001, vol * getAudioLevel('ambiance')), ctx.currentTime + delay + .45);
  gain.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + delay + seconds);
  src.buffer = buf;
  src.connect(high);
  high.connect(low);
  low.connect(gain);
  gain.connect(ctx.destination);
  src.start(ctx.currentTime + delay);
  src.stop(ctx.currentTime + delay + seconds + .05);
}

