// Deniz dalgası arka plan sesi
function sfxOceanAmbiance(profile='sea'){
  const ctx = getAudioCtx();
  if(!ctx) return;
  stopAllMusic();
  const intensity = profile === 'storm' ? 1.45 : profile === 'harbor' ? .88 : profile === 'engine' ? .72 : 1;
  const createWave = (freq, amp, lfoRate=.08, delay=0) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    lfo.frequency.value = lfoRate + Math.random()*0.025;
    lfoGain.gain.value = amp * .34 * intensity * getAudioLevel('ambiance');
    lfo.connect(lfoGain);
    lfoGain.connect(gain.gain);
    osc.type = 'sine';
    osc.frequency.value = freq;
    gain.gain.value = Math.max(0.0001, amp * intensity * getAudioLevel('ambiance'));
    filter.type = 'lowpass';
    filter.frequency.value = 260;
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    osc.start(ctx.currentTime + delay);
    lfo.start(ctx.currentTime + delay);
    ambianceNodes.push(osc); ambianceNodes.push(lfo);
  };
  createWave(42, 0.038, .055);
  createWave(63, 0.026, .073, .2);
  createWave(86, 0.016, .105, .55);
  let waveT = 0;
  function waveImpact(){
    if(ambianceNodes.length === 0) return;
    playSoftWaveWash((profile === 'storm' ? .085 : .045) * intensity, profile === 'storm' ? 3.4 : 2.7);
    waveT++;
    if(ambianceNodes.length > 0){
      const nextWave = profile === 'storm' ? 2400 + Math.random()*2200 : 4200 + Math.random()*5200;
      sceneAudioLoopTimers.push(setTimeout(waveImpact, nextWave));
    }
  }
  sceneAudioLoopTimers.push(setTimeout(waveImpact, profile === 'storm' ? 900 : 1800));
}

