function sfxHomesickSigh(){
  const ctx = getAudioCtx();
  if(!ctx) return;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  const filter = ctx.createBiquadFilter();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(210, ctx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(132, ctx.currentTime + 1.25);
  filter.type = 'lowpass';
  filter.frequency.value = 540;
  gain.gain.setValueAtTime(0.0001, ctx.currentTime);
  gain.gain.linearRampToValueAtTime(0.02, ctx.currentTime + 0.22);
  gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 1.4);
  osc.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  osc.start(ctx.currentTime);
  osc.stop(ctx.currentTime + 1.45);
  playNoise(0.6, 0.008, 0.05);
}

function sfxLonelyShipCreak(){
  const ctx = getAudioCtx();
  if(!ctx) return;
  for(let i=0;i<3;i++){
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(180 + Math.random()*70, ctx.currentTime + i*0.65);
    osc.frequency.linearRampToValueAtTime(95 + Math.random()*35, ctx.currentTime + i*0.65 + 0.55);
    filter.type = 'bandpass';
    filter.frequency.value = 260 + Math.random()*140;
    filter.Q.value = 0.8;
    gain.gain.setValueAtTime(0.0001, ctx.currentTime + i*0.65);
    gain.gain.linearRampToValueAtTime(0.007 + Math.random()*0.004, ctx.currentTime + i*0.65 + 0.08);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + i*0.65 + 0.7);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    osc.start(ctx.currentTime + i*0.65);
    osc.stop(ctx.currentTime + i*0.65 + 0.75);
  }
}

function sfxDistantEngineHum(){
  const ctx = getAudioCtx();
  if(!ctx) return;
  const oscA = ctx.createOscillator();
  const oscB = ctx.createOscillator();
  const gain = ctx.createGain();
  const filter = ctx.createBiquadFilter();
  oscA.type = 'sine';
  oscB.type = 'triangle';
  oscA.frequency.value = 46;
  oscB.frequency.value = 69;
  filter.type = 'lowpass';
  filter.frequency.value = 180;
  gain.gain.setValueAtTime(0.0001, ctx.currentTime);
  gain.gain.linearRampToValueAtTime(0.014, ctx.currentTime + 0.4);
  gain.gain.linearRampToValueAtTime(0.009, ctx.currentTime + 1.8);
  gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 3.4);
  oscA.connect(filter);
  oscB.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  oscA.start(ctx.currentTime);
  oscB.start(ctx.currentTime);
  oscA.stop(ctx.currentTime + 3.5);
  oscB.stop(ctx.currentTime + 3.5);
}

function playHomesickAmbiance(sc){
  if(!sc) return;
  const sadScene = ['s115','s116','s130','kriz05b'].includes(sc.id) || /aile ozlemi|yalnizlik|ic ses|uykusuzluk|ozlem|arkadas|aglamaya basladin|ilk buyuk firtina/.test(`${sc.sub||''} ${sc.text||''}`.toLowerCase());
  if(!sadScene) return;
  sfxDistantEngineHum();
  setTimeout(sfxLonelyShipCreak, 260);
  const sfx = Math.random() > 0.45 ? sfxHomesickCry : sfxHomesickSigh;
  setTimeout(sfx, 420);
}

function playSceneAmbientLayers(sc){
  const blob = `${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  if(/storm|firtina|wind|squall|swell/.test(blob)) return;
  if(/harbor|liman|terminal|berth|all fast|mooring|halat/.test(blob)){
    sceneAudioLoopTimers.push(setTimeout(()=>playSoftWaveWash(.028, 2.8), 1200));
  } else if(/bridge|kopruustu|radar|ecdis|ais|arpa|sea|deniz|route|seyir/.test(blob)){
    sceneAudioLoopTimers.push(setTimeout(()=>playSoftWaveWash(.022, 2.6), 1500));
  }
  if(/vhf|dsc|mayday|pan-pan|securite|sahil guvenlik/.test(blob)){
    sceneAudioLoopTimers.push(setTimeout(()=>{
      playTone(810,'sine',0.025,0.012);
    },240));
  }
  if(/engine|makine|compressor|generator|pump|ventilation|blower/.test(blob)){
    sceneAudioLoopTimers.push(setTimeout(()=>{
      playSoftWaveWash(.018, 3.2);
    },260));
  }
}

// Sahneye göre ses çal
function playSceneAudio(sc){
  const gfx = sc.gfx || '';
  const alert = sc.alert || false;
  const sceneBlob = `${sc?.id||''} ${sc?.gfx||''} ${sc?.loc||''} ${sc?.sub||''} ${sc?.text||''}`.toLowerCase();
  clearSceneAudioLoops();
  sfxSceneTransition(gfx);
  
  if(alert){
    if(sc?.id === 's124b' || /sling kopuyor|halat\/sling kopuyor|snap-back/.test(sceneBlob)){
      stopAllMusic();
      setTimeout(sfxMetalSnap, 70);
      setTimeout(()=>playTone(190,'sawtooth',0.12,0.08), 120);
      setTimeout(sfxAlarm, 220);
    }
    else if(gfx === 'pirate') { setTimeout(sfxPirateAmbiance, 300); sfxAlarm(); }
    else if(gfx === 'bogaz') { sfxBogazAmbiance(); setTimeout(()=>playTone(440,'square',0.1,0.3),500); }
    else if(gfx === 'engine_fault') { sfxEngineAlarm(); }
    else { sfxAlarm(); }
  } else {
    if(gfx === 'storm') {
      sfxStormAmbiance();
    }
    else if(gfx==='fire') {
      stopAllMusic();
      sfxAlarm();
      setTimeout(()=>playTone(760, 'square', 0.08, 0.08), 260);
    }
    else if(gfx === 'radar') {
      stopAllMusic();
      sfxRadarBip();
      setTimeout(sfxPanelWake, 55);
      setTimeout(sfxRadarBip, 280);
    }
    else if(gfx === 'engine') { stopAllMusic(); sfxShipEngine(); }
    else if(gfx==='harbor') { sfxOceanAmbiance('harbor'); }
    else if(gfx==='sea'||gfx==='night'||gfx==='sunrise'||gfx==='port_arrival') { sfxOceanAmbiance('sea'); }
    else if(gfx==='cabin'||gfx==='galley') {
      sfxOceanAmbiance();
      playHomesickAmbiance(sc);
    }
    else if(/ecdis_panel|ais_panel|gyro_panel|magnetic_panel|echo_panel|speedlog_panel|autopilot_panel|bnwas_panel|gmdss_panel/.test(gfx)) {
      stopAllMusic();
      sfxPanelWake();
      if(/ecdis_panel|ais_panel/.test(gfx)) setTimeout(()=>playTone(1120, 'sine', 0.04, 0.028), 65);
    }
    else { sfxOceanAmbiance('sea'); }
  }
  if(/vhf|dsc alert|distress|sahil guvenlik|secu?rite|mayday|pan-pan/.test(sceneBlob)){
    sceneAudioLoopTimers.push(setTimeout(sfxVHF, 40));
  }
  if(gfx === 'engine_fault'){
    sceneAudioLoopTimers.push(setTimeout(()=>{
      playTone(210, 'sine', 0.08, 0.018);
    }, 100));
  }
  playSceneAmbientLayers(sc);
}


